def _bootstrap_engagement(db_path: Path, engagement_id: int = 1001) -> None:
    con = sqlite3.connect(db_path)
    try:
        apply_schema(con)
        run_migrations(con)
        con.execute(
            """
            INSERT INTO engagements (id, name, scope_json, status, operator)
            VALUES (?, 'Acme Example', '["*.acme.example","+15551234567","security@acme.example","https://downloads.acme.example/app.apk"]',
                    'ACTIVE', 'delta-one')
            """,
            (engagement_id,),
        )
        con.commit()
    finally:
        con.close()


def _social_profile_candidates_from_payload(
    profile_data: Any,
    *,
    anchor: str = "security@acme.example",
    source: str = "identity_provider:test",
    seed_depths: dict[tuple[str, str], int] | None = None,
) -> list[SeedCandidate]:
    engine = EngagementSynthesisEngine(Path("unused-engagement.db"), 1001, depth_limit=3)
    return engine._social_profile_candidates_from_rows(
        [
            {
                "email": anchor,
                "source": source,
                "profile_data": json.dumps(profile_data),
            }
        ],
        seed_depths or {},
    )


def _social_profile_candidate_map(
    candidates: list[SeedCandidate],
) -> dict[tuple[str, str], SeedCandidate]:
    rows: dict[tuple[str, str], SeedCandidate] = {}
    for candidate in candidates:
        rows.setdefault((candidate.seed_value, candidate.seed_type), candidate)
    return rows


def _social_profile_candidate_relations(
    candidates: list[SeedCandidate],
) -> set[tuple[str | None, str, str]]:
    return {
        (candidate.parent_value, candidate.seed_value, candidate.relation_type)
        for candidate in candidates
        if candidate.parent_value
    }


def _tar_bytes(member_name: str, payload: bytes, *, mode: str = "w:gz") -> bytes:
    bundle = BytesIO()
    with tarfile.open(fileobj=bundle, mode=mode) as tf:
        info = tarfile.TarInfo(member_name)
        info.size = len(payload)
        tf.addfile(info, BytesIO(payload))
    return bundle.getvalue()


def _write_ar_archive(path: Path, members: list[tuple[str, bytes]]) -> None:
    with path.open("wb") as handle:
        handle.write(b"!<arch>\n")
        for name, payload in members:
            encoded_name = f"{name}/".encode("ascii")
            if len(encoded_name) > 16:
                raise AssertionError(f"test ar member name too long: {name}")
            handle.write(encoded_name.ljust(16))
            handle.write(b"0           ")
            handle.write(b"0     ")
            handle.write(b"0     ")
            handle.write(b"100644  ")
            handle.write(str(len(payload)).encode("ascii").ljust(10))
            handle.write(b"`\n")
            handle.write(payload)
            if len(payload) % 2:
                handle.write(b"\n")


def _cpio_newc_bytes(members: list[tuple[str, bytes]]) -> bytes:
    bundle = bytearray()

    def _pad4() -> None:
        bundle.extend(b"\x00" * ((4 - (len(bundle) % 4)) % 4))

    def _append_member(name: str, payload: bytes, *, mode: int = 0o100644) -> None:
        encoded_name = name.encode("utf-8") + b"\x00"
        fields = (
            1,
            mode,
            0,
            0,
            1,
            0,
            len(payload),
            0,
            0,
            0,
            0,
            len(encoded_name),
            0,
        )
        header = "070701" + "".join(f"{field:08x}" for field in fields)
        bundle.extend(header.encode("ascii"))
        bundle.extend(encoded_name)
        _pad4()
        bundle.extend(payload)
        _pad4()

    for member_name, member_payload in members:
        _append_member(member_name, member_payload)
    _append_member("TRAILER!!!", b"", mode=0)
    return bytes(bundle)


def _asar_bytes(members: list[tuple[str, bytes]]) -> bytes:
    header_files: dict[str, Any] = {}
    content = bytearray()
    for raw_member_name, payload in members:
        parts = [part for part in str(raw_member_name).split("/") if part]
        if not parts:
            continue
        cursor = header_files
        for part in parts[:-1]:
            entry = cursor.setdefault(part, {"files": {}})
            cursor = entry["files"]
        cursor[parts[-1]] = {"size": len(payload), "offset": str(len(content))}
        content.extend(payload)

    header_json = json.dumps({"files": header_files}, separators=(",", ":")).encode()
    padding = b"\x00" * ((4 - (len(header_json) % 4)) % 4)
    header_size = 4 + len(header_json) + len(padding)
    return (
        struct.pack("<II", header_size, len(header_json)) + header_json + padding + bytes(content)
    )


def test_synthesis_engine_backfills_scope_and_promotes_discovered_seeds(tmp_path: Path) -> None:
    db_path = tmp_path / "engagement.db"
    _bootstrap_engagement(db_path)

    con = sqlite3.connect(db_path)
    try:
        con.execute(
            """
            INSERT INTO emails (engagement_id, email, domain, source)
            VALUES (1001, 'security@acme.example', 'acme.example', 'crawler')
            """
        )
        con.execute(
            """
            INSERT INTO hosts (engagement_id, ip, hostname, os_family, host_context)
            VALUES (1001, '203.0.113.10', 'app.acme.example', 'linux', '{}')
            """
        )
        con.execute(
            """
            INSERT INTO artifact_queue
                (engagement_id, source_url, artifact_type, discovered_from, status, metadata_json)
            VALUES
                (1001, 'https://downloads.acme.example/app.apk', 'apk', 'crawler', 'queued', '{}')
            """
        )
        con.commit()
    finally:
        con.close()

    summary = EngagementSynthesisEngine(db_path, 1001, depth_limit=3).run()
    repeat_summary = EngagementSynthesisEngine(db_path, 1001, depth_limit=3).run()

    assert "acme.example" in summary.root_domains
    assert summary.seeds_inserted >= 2
    assert summary.relations_inserted >= 2
    assert summary.corroborated_count >= 1
    assert repeat_summary.relations_inserted == 0

    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        rows = con.execute(
            """
            SELECT seed_value, seed_type, source, depth, confidence, metadata_json
            FROM engagement_seeds
            WHERE engagement_id=1001
            ORDER BY seed_type, seed_value
            """
        ).fetchall()
        seed_map = {(str(row["seed_value"]), str(row["seed_type"])): row for row in rows}
        assert ("acme.example", "domain") in seed_map
        assert ("+15551234567", "phone") in seed_map
        assert ("security@acme.example", "email") in seed_map
        assert ("https://downloads.acme.example/app.apk", "apk_url") in seed_map
        assert ("security", "username") in seed_map
        assert ("app.acme.example", "subdomain") in seed_map
        assert ("downloads.acme.example", "subdomain") in seed_map
        assert ("203.0.113.10", "ipv4") in seed_map
        assert int(seed_map[("security", "username")]["depth"]) == 2
        assert str(seed_map[("acme.example", "domain")]["source"]) == "scope"
        assert str(seed_map[("security", "username")]["source"]) == "cross_reference"

        domain_metadata = json.loads(str(seed_map[("acme.example", "domain")]["metadata_json"]))
        domain_synthesis = domain_metadata["synthesis"]
        assert domain_synthesis["corroborated"] is True
        assert domain_synthesis["confidence_band"] == "confirmed"
        assert domain_synthesis["supporting_relations"] >= 2
        assert "email" in domain_synthesis["corroborating_seed_types"]
        assert "subdomain" in domain_synthesis["corroborating_seed_types"]

        username_metadata = json.loads(str(seed_map[("security", "username")]["metadata_json"]))
        username_synthesis = username_metadata["synthesis"]
        assert username_synthesis["confidence_band"] in {"medium", "high"}
        assert username_synthesis["supporting_relations"] == 1
        assert float(seed_map[("security", "username")]["confidence"]) >= 0.76

        relation_count = con.execute(
            "SELECT COUNT(*) FROM seed_relations WHERE engagement_id=1001"
        ).fetchone()[0]
        assert relation_count >= 2
    finally:
        con.close()


def test_synthesis_engine_backfills_dict_shaped_scope_json(tmp_path: Path) -> None:
    db_path = tmp_path / "engagement.db"
    _bootstrap_engagement(db_path)

    con = sqlite3.connect(db_path)
    try:
        con.execute(
            """
            UPDATE engagements
            SET scope_json=?
            WHERE id=1001
            """,
            (
                json.dumps(
                    {
                        "domains": ["*.acme.example"],
                        "domain_allowlist": ["portal.acme.example"],
                        "urls": ["https://downloads.acme.example/app.apk"],
                        "authorized_seeds": ["+15551234567", "security@acme.example"],
                        "allowed_seeds": ["@acmeops"],
                    }
                ),
            ),
        )
        con.commit()
    finally:
        con.close()

    summary = EngagementSynthesisEngine(db_path, 1001, depth_limit=3).run()

    con = sqlite3.connect(db_path)
    try:
        seed_rows = {
            (str(row[0]), str(row[1]), str(row[2]))
            for row in con.execute(
                """
                SELECT seed_value, seed_type, source
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
    finally:
        con.close()

    assert ("acme.example", "domain", "scope") in seed_rows
    assert ("portal.acme.example", "domain", "scope") in seed_rows
    assert ("https://downloads.acme.example/app.apk", "apk_url", "scope") in seed_rows
    assert ("+15551234567", "phone", "scope") in seed_rows
    assert ("security@acme.example", "email", "scope") in seed_rows
    assert ("@acmeops", "username", "scope") in seed_rows
    assert "acme.example" in summary.root_domains


