def test_synthesis_engine_parallelizes_scope_seed_backfill_and_preserves_upsert_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    _bootstrap_engagement(db_path)
    engine = EngagementSynthesisEngine(db_path, 1001)
    active = 0
    peak = 0
    lock = threading.Lock()
    entered = 0
    gate = threading.Event()
    delays = {
        "*.alpha.example": 0.05,
        "+15550001111": 0.01,
        " user@acme.example ": 0.03,
        "   ": 0.02,
        "https://downloads.example/client.apk": 0.04,
        "203.0.113.20": 0.015,
    }
    captured: list[tuple[str, str, str, int, float]] = []

    con = sqlite3.connect(db_path)
    try:
        con.execute(
            """
            UPDATE engagements
            SET scope_json=?
            WHERE id=1001
            """,
            (
                json.dumps(
                    [
                        "*.alpha.example",
                        "+15550001111",
                        " user@acme.example ",
                        "   ",
                        "https://downloads.example/client.apk",
                        "203.0.113.20",
                    ]
                ),
            ),
        )
        con.commit()
    finally:
        con.close()

    original_scope_seed_candidate = EngagementSynthesisEngine._scope_seed_candidate

    def _fake_scope_seed_candidate(value: Any) -> SeedCandidate | None:
        text = str(value or "")
        nonlocal active, peak, entered
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[text])
            return original_scope_seed_candidate(value)
        finally:
            with lock:
                active -= 1

    def _fake_upsert_seed(
        self,
        con: sqlite3.Connection,
        candidate: SeedCandidate,
    ) -> int:
        del self, con
        captured.append(
            (
                candidate.seed_value,
                candidate.seed_type,
                candidate.source,
                candidate.depth,
                candidate.confidence,
            )
        )
        return len(captured)

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_scope_seed_candidate",
        staticmethod(_fake_scope_seed_candidate),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_upsert_seed",
        _fake_upsert_seed,
    )

    con = sqlite3.connect(db_path)
    try:
        engine._backfill_scope_seeds(con)
    finally:
        con.close()

    assert peak == 4
    assert captured == [
        ("alpha.example", "domain", "scope", 0, 1.0),
        ("+15550001111", "phone", "scope", 0, 1.0),
        ("user@acme.example", "email", "scope", 0, 1.0),
        ("https://downloads.example/client.apk", "apk_url", "scope", 0, 1.0),
        ("203.0.113.20", "ipv4", "scope", 0, 1.0),
    ]


