def test_synthesis_engine_canonicalizes_spaced_social_provider_labels() -> None:
    provider_cases = [
        ("Angel List", "company", "angellistalias", "angellist"),
        ("Bio Link", "pricing", "biolinkalias", "biolink"),
        ("Bio Site", "login", "biositealias", "biosite"),
        ("Blue Sky", "profile", "blueskyalias2", "bluesky"),
        ("Bug Crowd", "programs", "bugcrowdalias", "bugcrowd"),
        ("Cal Com", "login", "calcomalias", "calcom"),
        ("Code Pen", "pens", "codepenalias2", "codepen"),
        ("Git Hub", "marketplace", "githubalias2", "github"),
        ("Git Hub Gist", "explore", "gistalias2", "github_gist"),
        ("Git Lab", "groups", "gitlabalias", "gitlab"),
        ("Hacker News", "news", "hnalias", "hackernews"),
        ("Hacker One", "programs", "hackeronealias", "hackerone"),
        ("Link Tree", "login", "linktreealias", "linktree"),
        ("Lnk Bio", "login", "lnkbioalias", "lnkbio"),
        ("Solo To", "login", "solotoalias", "soloto"),
        ("Try Hack Me", "room", "tryhackmealias", "tryhackme"),
        ("Well Found", "company", "wellfoundalias", "wellfound"),
        ("Yes We Hack", "programs", "yeswehackalias", "yeswehack"),
    ]
    payload = {
        "registeredServices": [
            {
                "source": "epieos",
                "service": service,
                "results": [
                    {"username": reserved_handle},
                    {"username": valid_handle},
                ],
            }
            for service, reserved_handle, valid_handle, _platform in provider_cases
        ]
    }
    seed_rows = _social_profile_candidate_map(
        _social_profile_candidates_from_payload(
            payload,
            source="identity_provider:spaced-labels",
        )
    )

    for _service, _reserved_handle, valid_handle, platform in provider_cases:
        assert (valid_handle, "username") in seed_rows
        assert seed_rows[(valid_handle, "username")].metadata["platform"] == platform

    reserved_handles = {reserved_handle for _, reserved_handle, _, _ in provider_cases}
    for reserved_handle in reserved_handles:
        assert (reserved_handle, "username") not in seed_rows


