def test_synthesis_engine_promotes_confirmed_username_profiles_into_recursive_seeds(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    _bootstrap_engagement(db_path)

    con = sqlite3.connect(db_path)
    try:
        con.execute(
            """
            CREATE TABLE IF NOT EXISTS username_profiles (
                id INTEGER PRIMARY KEY,
                engagement_id INTEGER NOT NULL,
                username TEXT NOT NULL,
                platform TEXT NOT NULL,
                profile_url TEXT,
                status TEXT NOT NULL,
                source_tool TEXT,
                discovered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
            )
            """
        )
        con.executemany(
            """
            INSERT INTO username_profiles
                (engagement_id, username, platform, profile_url, status, source_tool)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            [
                (
                    1001,
                    "aliceops",
                    "github",
                    "https://github.com/aliceops",
                    "CONFIRMED",
                    "sherlock",
                ),
                (
                    1001,
                    "videoops",
                    "youtube",
                    "https://www.youtube.com/@videoops",
                    "CONFIRMED",
                    "whatsmyname",
                ),
                (
                    1001,
                    "customhandle",
                    "obscure",
                    "https://profiles.example/customhandle",
                    "CONFIRMED",
                    "maigret",
                ),
                (
                    1001,
                    "library",
                    "dockerhub",
                    "https://hub.docker.com/r/library/nginx",
                    "CONFIRMED",
                    "sherlock",
                ),
                (
                    1001,
                    "ghost",
                    "github",
                    "https://github.com/ghost",
                    "UNCONFIRMED",
                    "sherlock",
                ),
            ],
        )
        con.commit()
    finally:
        con.close()

    summary = EngagementSynthesisEngine(db_path, 1001, depth_limit=3).run()

    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        seed_rows = {
            (str(row["seed_value"]), str(row["seed_type"])): json.loads(
                str(row["metadata_json"] or "{}")
            )
            for row in con.execute(
                """
                SELECT seed_value, seed_type, metadata_json
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("aliceops", "username") in seed_rows
        assert ("videoops", "username") in seed_rows
        assert ("customhandle", "username") in seed_rows
        assert ("https://github.com/aliceops", "url") in seed_rows
        assert ("https://www.youtube.com/@videoops", "url") in seed_rows
        assert ("https://profiles.example/customhandle", "url") in seed_rows
        assert ("library", "username") not in seed_rows
        assert ("https://hub.docker.com/r/library/nginx", "url") not in seed_rows
        assert ("ghost", "username") not in seed_rows
        assert seed_rows[("aliceops", "username")]["rule"] == "username_profile"
        assert seed_rows[("aliceops", "username")]["source"] == "sherlock"
        assert seed_rows[("videoops", "username")]["platform"] == "youtube"

        relation_rows = {
            (str(row[0]), str(row[1]), str(row[2])): json.loads(str(row[3] or "{}"))
            for row in con.execute(
                """
                SELECT src.seed_value, dst.seed_value, sr.relation_type, sr.evidence_json
                FROM seed_relations sr
                JOIN engagement_seeds src ON src.id=sr.source_seed_id
                JOIN engagement_seeds dst ON dst.id=sr.target_seed_id
                WHERE sr.engagement_id=1001
                """
            ).fetchall()
        }
        expected_relations = [
            ("aliceops", "https://github.com/aliceops", "derived_from"),
            ("videoops", "https://www.youtube.com/@videoops", "derived_from"),
            (
                "customhandle",
                "https://profiles.example/customhandle",
                "derived_from",
            ),
        ]
        for relation in expected_relations:
            assert relation in relation_rows
            assert relation_rows[relation]["rule"] == "username_profile_url"
        assert summary.seeds_inserted >= 6
        assert summary.relations_inserted >= 3
    finally:
        con.close()


def test_synthesis_engine_uses_social_app_profile_uri_handles_for_confirmed_username_profiles(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    _bootstrap_engagement(db_path)

    con = sqlite3.connect(db_path)
