        assert ("alice-example", "username") in seed_rows
        assert ("secopsgram", "username") in seed_rows
        assert ("acmeops", "username") in seed_rows
        assert ("acmerelay", "username") in seed_rows
        assert ("stale-alias", "username") not in seed_rows
        assert ("wrong-gram", "username") not in seed_rows
        assert ("wrong-x", "username") not in seed_rows
        assert ("wrong-telegram", "username") not in seed_rows
