def test_synthesis_engine_parallelizes_social_profile_platform_hint_candidates_and_preserves_order(
    monkeypatch,
) -> None:
    active = 0
    peak = 0
    lock = threading.Lock()
    first = "https://unknown.example/profile"
    second = "https://github.com/octocat"
    third = "https://mastodon.social/@acmefed/112233"
    delays = {
        first: 0.05,
        second: 0.03,
        third: 0.01,
    }

    def _fake_social_profile_platform_hint_candidate(candidate: Any) -> str:
        candidate_text = str(candidate or "").strip()
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[candidate_text])
            return {
                first: "",
                second: "github",
                third: "mastodon",
            }[candidate_text]
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_platform_hint_candidate",
        staticmethod(_fake_social_profile_platform_hint_candidate),
    )

    value = EngagementSynthesisEngine._social_profile_platform_hint(
        {
            "profile_url": first,
            "url": second,
            "external_url": third,
        }
    )

    assert peak == 3
    assert value == "github"


def test_synthesis_engine_parallelizes_social_profile_pivot_families_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    engine = EngagementSynthesisEngine(db_path, 1001)
    active = 0
    peak = 0
    lock = threading.Lock()
    delays = {
        "handles": 0.05,
        "company": 0.01,
        "name": 0.03,
        "emails": 0.02,
        "phones": 0.04,
        "urls": 0.015,
        "hosts": 0.025,
        "domain": 0.035,
    }

    def _track(label: str) -> None:
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[label])
        finally:
            with lock:
                active -= 1

    def _fake_social_profile_is_company_profile(
        cls,
        profile: dict[str, Any],
        *,
        source_label: str,
        platform: str,
    ) -> bool:
        del cls, profile, source_label, platform
        return False

    def _fake_social_profile_handles(
        cls,
        profile: dict[str, Any],
        *,
        platform: str = "",
    ) -> list[str]:
        del cls, profile, platform
        _track("handles")
        return ["handle-one"]

    def _fake_social_profile_company_name(
        cls,
        profile: dict[str, Any],
        *,
        source_label: str,
        platform: str,
    ) -> str:
        del cls, profile, source_label, platform
        _track("company")
        return "Acme Corp"

    def _fake_social_profile_name(cls, profile: dict[str, Any]) -> str:
        del cls, profile
        _track("name")
        return "Alice Example"

    def _fake_social_profile_emails(cls, profile: dict[str, Any]) -> list[str]:
        del cls, profile
        _track("emails")
        return ["ops@acme.example"]

    def _fake_social_profile_phones(cls, profile: dict[str, Any]) -> list[str]:
        del cls, profile
        _track("phones")
        return ["+15550001111"]

    def _fake_social_profile_urls(cls, profile: dict[str, Any]) -> list[str]:
        del cls, profile
        _track("urls")
        return ["https://portal.acme.example/login"]

    def _fake_social_profile_related_hosts(
        cls,
        profile: dict[str, Any],
    ) -> list[tuple[str, str]]:
        del cls, profile
        _track("hosts")
        return [("portal.acme.example", "subdomain")]

    def _fake_pivot_family(
        self,
        family: str,
        *,
        profile: dict[str, Any],
        source_label: str,
        platform: str,
        base_confidence: float,
        company_profile: bool,
    ) -> list[tuple[str, str, str, float, dict[str, Any]]]:
        if family == "domain":
            _track("domain")
        return original_pivot_family(
            self,
            family,
            profile=profile,
            source_label=source_label,
            platform=platform,
            base_confidence=base_confidence,
            company_profile=company_profile,
        )

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_is_company_profile",
        classmethod(_fake_social_profile_is_company_profile),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_handles",
        classmethod(_fake_social_profile_handles),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_company_name",
        classmethod(_fake_social_profile_company_name),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_name",
        classmethod(_fake_social_profile_name),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_emails",
        classmethod(_fake_social_profile_emails),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_phones",
        classmethod(_fake_social_profile_phones),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_urls",
        classmethod(_fake_social_profile_urls),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_related_hosts",
        classmethod(_fake_social_profile_related_hosts),
    )
    original_pivot_family = EngagementSynthesisEngine._social_profile_pivot_family
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_pivot_family",
        _fake_pivot_family,
    )

    pivots = engine._extract_social_profile_pivots(
        {"domain": "acme.example"},
        source_label="epieos",
        platform="twitter",
    )

    assert peak == 4
    assert [pivot[:3] for pivot in pivots] == [
        ("handle-one", "username", "same_entity"),
        ("Acme Corp", "company", "same_entity"),
        ("Alice Example", "name", "same_entity"),
        ("ops@acme.example", "email", "same_entity"),
        ("+15550001111", "phone", "same_entity"),
        ("https://portal.acme.example/login", "url", "related_asset"),
        ("portal.acme.example", "subdomain", "related_asset"),
        ("acme.example", "domain", "related_asset"),
    ]


def test_synthesis_engine_parallelizes_social_profile_seed_pivot_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    engine = EngagementSynthesisEngine(db_path, 1001)
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {
        "one@acme.example": 0.05,
        "two@acme.example": 0.01,
        "three@acme.example": 0.03,
        "four@acme.example": 0.02,
        "five@acme.example": 0.04,
    }
    original_entry = EngagementSynthesisEngine._social_profile_seed_pivot_entry

    def _tracking_entry(entry):  # noqa: ANN001
        nonlocal active, peak, entered
        seed_value = entry[0]
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[seed_value])
            return original_entry(entry)
        finally:
            with lock:
                active -= 1

    def _fake_social_profile_emails(
        cls,
        profile: dict[str, Any],
    ) -> list[str]:
        del cls, profile
        return [
            "one@acme.example",
            "two@acme.example",
            "three@acme.example",
            "four@acme.example",
            "five@acme.example",
        ]

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_seed_pivot_entry",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_emails",
        classmethod(_fake_social_profile_emails),
    )

    pivots = engine._social_profile_pivot_family(
        "emails",
        profile={},
        source_label="epieos",
        platform="twitter",
        base_confidence=0.74,
        company_profile=False,
    )

    assert peak == 4
    assert [pivot[:3] for pivot in pivots] == [
        ("one@acme.example", "email", "same_entity"),
        ("two@acme.example", "email", "same_entity"),
        ("three@acme.example", "email", "same_entity"),
        ("four@acme.example", "email", "same_entity"),
        ("five@acme.example", "email", "same_entity"),
    ]


