def test_synthesis_engine_parallelizes_social_profile_text_fields_and_preserves_order(
    monkeypatch,
) -> None:
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {
        "bio": 0.05,
        "headline": 0.01,
        "contact": 0.03,
        "about": 0.02,
        "summary": 0.04,
    }
    profile = {
        "bio": "bio first",
        "headline": "headline second",
        "contact": "contact third",
        "profile": {
            "about": "nested about fourth",
            "summary": "nested summary fifth",
        },
    }

    def _tracking_text_field_value_candidates(
        cls,
        item_key: tuple[dict[str, Any], str],
    ) -> list[str]:
        del cls
        item, key = item_key
        value = item.get(key) if isinstance(item, dict) else None
        if not value:
            return []
        nonlocal active, peak, entered
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 3:
                gate.set()
        try:
            if current_entered <= 3:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[str(key)])
            return [str(value)]
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_text_field_value_candidates",
        classmethod(_tracking_text_field_value_candidates),
    )

    values = EngagementSynthesisEngine._social_profile_text_values(profile)

    assert peak >= 3
    assert values == [
        "bio first",
        "headline second",
        "contact third",
        "nested about fourth",
        "nested summary fifth",
    ]


