def test_synthesis_engine_parallelizes_social_profile_rows_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    engine = EngagementSynthesisEngine(db_path, 1001)
    active = 0
    peak = 0
    lock = threading.Lock()
    delays = {
        1: 0.05,
        2: 0.01,
        3: 0.03,
        4: 0.02,
        5: 0.04,
    }
    rows = [
        {"row_id": 1, "email": "security@acme.example", "profile_data": "{}"},
        {"row_id": 2, "email": "security@acme.example", "profile_data": "{}"},
        {"row_id": 3, "email": "domain:acme.example", "profile_data": "{}"},
        {"row_id": 4, "email": "phone:+15550001111", "profile_data": "{}"},
        {"row_id": 5, "email": "username:rootops", "profile_data": "{}"},
    ]

    def _fake_social_profile_row_candidates(
        self,
        row: Any,
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        del self, seed_depths
        row_id = int(row["row_id"])
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[row_id])
            return {
                1: [
                    SeedCandidate(
                        seed_value="ghostops",
                        seed_type="username",
                        source="cross_reference",
                        depth=2,
                        confidence=0.91,
                        parent_value="security@acme.example",
                        parent_type="email",
                        relation_type="same_entity",
                        metadata={"row_id": 1},
                    )
                ],
                2: [
                    SeedCandidate(
                        seed_value="ghostops",
                        seed_type="username",
                        source="cross_reference",
                        depth=2,
                        confidence=0.55,
                        parent_value="security@acme.example",
                        parent_type="email",
                        relation_type="same_entity",
                        metadata={"row_id": 2},
                    )
                ],
                3: [
                    SeedCandidate(
                        seed_value="Acme Corp",
                        seed_type="company",
                        source="cross_reference",
                        depth=2,
                        confidence=0.84,
                        parent_value="acme.example",
                        parent_type="domain",
                        relation_type="same_entity",
                        metadata={"row_id": 3},
                    )
                ],
                4: [
                    SeedCandidate(
                        seed_value="https://portal.acme.example/login",
                        seed_type="url",
                        source="cross_reference",
                        depth=2,
                        confidence=0.82,
                        parent_value="+15550001111",
                        parent_type="phone",
                        relation_type="related_asset",
                        metadata={"row_id": 4},
                    )
                ],
                5: [
                    SeedCandidate(
                        seed_value="portal.acme.example",
                        seed_type="subdomain",
                        source="cross_reference",
                        depth=2,
                        confidence=0.79,
                        parent_value="rootops",
                        parent_type="username",
                        relation_type="related_asset",
                        metadata={"row_id": 5},
                    )
                ],
            }[row_id]
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_row_candidates",
        _fake_social_profile_row_candidates,
    )

    values = engine._social_profile_candidates_from_rows(rows, {})

    assert peak == 4
    assert [(item.seed_value, item.seed_type, item.parent_value) for item in values] == [
        ("ghostops", "username", "security@acme.example"),
        ("Acme Corp", "company", "acme.example"),
        ("https://portal.acme.example/login", "url", "+15550001111"),
        ("portal.acme.example", "subdomain", "rootops"),
    ]
    assert values[0].metadata["row_id"] == 1


