def test_synthesis_engine_parallelizes_social_profile_profile_candidate_batch_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    engine = EngagementSynthesisEngine(db_path, 1001)
    row = {
        "email": "security@acme.example",
        "source": "epieos",
        "profile_data": json.dumps(
            [
                {"label": "one"},
                {"label": "two"},
                {"label": "three"},
            ]
        ),
    }
    delays = {
        0: 0.05,
        1: 0.01,
        2: 0.03,
    }
    active = 0
    peak = 0
    lock = threading.Lock()
    original_entry = EngagementSynthesisEngine._social_profile_candidate_batch_entries

    def _tracking_entry(batch_entry):  # noqa: ANN001
        nonlocal active, peak
        batch_index, _batch = batch_entry
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[batch_index])
            return original_entry(batch_entry)
        finally:
            with lock:
                active -= 1

    def _fake_social_profile_profile_candidates(
        self,
        profile: dict[str, Any],
        *,
        row: Any,
        anchor_value: str,
        anchor_type: str,
        base_depth: int,
    ) -> list[SeedCandidate]:
        del self, row, anchor_value, anchor_type, base_depth
        label = str(profile["label"])
        return [
            SeedCandidate(
                seed_value=f"value-{label}",
                seed_type="username",
                source="cross_reference",
                depth=1,
                confidence=0.8,
                parent_value="security@acme.example",
                parent_type="email",
                relation_type="same_entity",
                metadata={"label": label},
            ),
            SeedCandidate(
                seed_value=f"https://{label}.acme.example/profile",
                seed_type="url",
                source="cross_reference",
                depth=1,
                confidence=0.7,
                parent_value="security@acme.example",
                parent_type="email",
                relation_type="related_asset",
                metadata={"label": label},
            ),
        ]

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_candidate_batch_entries",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_profile_candidates",
        _fake_social_profile_profile_candidates,
    )

    values = engine._social_profile_row_candidates(row, {})

    assert peak == 3
    assert [(item.seed_value, item.seed_type) for item in values] == [
        ("value-one", "username"),
        ("https://one.acme.example/profile", "url"),
        ("value-two", "username"),
        ("https://two.acme.example/profile", "url"),
        ("value-three", "username"),
        ("https://three.acme.example/profile", "url"),
    ]


