def test_synthesis_engine_parallelizes_social_profile_payload_entries_and_preserves_order(
    monkeypatch,
) -> None:
    active = 0
    peak = 0
    lock = threading.Lock()
    delays = {
        "one": 0.05,
        "two": 0.01,
        "three": 0.03,
        "four": 0.02,
        "five": 0.04,
    }

    original_payload_entry = EngagementSynthesisEngine._social_profile_payload_entry

    def _fake_social_profile_payload_entry(
        item: Any,
        *,
        row_source: str,
    ) -> dict[str, Any] | None:
        if isinstance(item, dict):
            label = str(item["label"])
            nonlocal active, peak
            with lock:
                active += 1
                peak = max(peak, active)
            try:
                time.sleep(delays[label])
                return original_payload_entry(item, row_source=row_source)
            finally:
                with lock:
                    active -= 1
        return original_payload_entry(item, row_source=row_source)

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_payload_entry",
        staticmethod(_fake_social_profile_payload_entry),
    )

    values = EngagementSynthesisEngine._social_profile_payload_entries(
        [
            {"label": "one"},
            {"label": "two", "source": "custom"},
            "skip",
            {"label": "three"},
            {"label": "four"},
            {"label": "five"},
        ],
        row_source="epieos",
    )

    assert peak == 4
    assert values == [
        {"label": "one", "source": "epieos"},
        {"label": "two", "source": "custom"},
        {"label": "three", "source": "epieos"},
        {"label": "four", "source": "epieos"},
        {"label": "five", "source": "epieos"},
    ]


def test_synthesis_engine_parallelizes_social_profile_payload_child_expansion_and_preserves_order(
    monkeypatch,
) -> None:
    active = 0
    peak = 0
    lock = threading.Lock()
    delays = {
        "one": 0.05,
        "two": 0.01,
        "three": 0.03,
        "four": 0.02,
        "five": 0.04,
    }

    original_child_worker = EngagementSynthesisEngine._social_profile_payload_child_candidate_items

    def _fake_social_profile_payload_child_candidate_items(
        job: tuple[Any, int, set[int], dict[str, Any]],
    ) -> list[dict[str, Any]]:
        child, _depth, _seen, _context = job
        label = str(child.get("label")) if isinstance(child, dict) else ""
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays.get(label, 0.002))
            return original_child_worker(job)
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_payload_child_candidate_items",
        staticmethod(_fake_social_profile_payload_child_candidate_items),
    )

    values = EngagementSynthesisEngine._social_profile_payload_candidate_items(
        [
            {"label": "one"},
            {"label": "two"},
            "skip",
            {"label": "three"},
            {"label": "four"},
            {"label": "five"},
        ]
    )

    assert peak == 4
    assert values == [
        {"label": "one"},
        {"label": "two"},
        {"label": "three"},
        {"label": "four"},
        {"label": "five"},
    ]


def test_synthesis_engine_promotes_bluesky_custom_domain_handles_as_domain_pivots(
    tmp_path: Path,
) -> None:
    engine = EngagementSynthesisEngine(tmp_path / "engagement.db", 1001)
    pivots = engine._extract_social_profile_pivots(
        {
            "platform": "bluesky",
            "profile_url": "https://bsky.app/profile/security.acme.example",
        },
        source_label="artifact_social_url_extract",
        platform="bluesky",
    )
    pivot_map = {
        (seed_value, seed_type): metadata
        for seed_value, seed_type, _relation_type, _confidence, metadata in pivots
    }

    assert ("security.acme.example", "username") in pivot_map
    assert ("security.acme.example", "domain") in pivot_map
    assert pivot_map[("security.acme.example", "domain")]["rule"] == "social_profile_domain_handle"

    bsky_social_pivots = engine._extract_social_profile_pivots(
        {
            "platform": "bluesky",
            "profile_url": "https://bsky.social/profile/ops.acme.example",
        },
        source_label="artifact_social_url_extract",
        platform="bluesky",
    )
    bsky_social_pivot_map = {
        (seed_value, seed_type): metadata
        for seed_value, seed_type, _relation_type, _confidence, metadata in bsky_social_pivots
    }
    assert ("ops.acme.example", "username") in bsky_social_pivot_map
    assert ("ops.acme.example", "domain") in bsky_social_pivot_map
    assert (
        bsky_social_pivot_map[("ops.acme.example", "domain")]["rule"]
        == "social_profile_domain_handle"
    )

    weak_name_search_pivots = engine._extract_social_profile_pivots(
        {"platform": "bluesky", "handle": "alice.blue"},
        source_label="name_search",
        platform="bluesky",
    )
    assert ("alice.blue", "username") in {
        (seed_value, seed_type)
        for seed_value, seed_type, _relation_type, _confidence, _metadata in weak_name_search_pivots
    }
    assert ("alice.blue", "domain") not in {
        (seed_value, seed_type)
        for seed_value, seed_type, _relation_type, _confidence, _metadata in weak_name_search_pivots
    }

    verified_name_search_pivots = engine._extract_social_profile_pivots(
        {
            "platform": "bluesky",
            "handle": "alice.blue",
            "verified_domain": True,
        },
        source_label="name_search",
        platform="bluesky",
    )
    assert ("alice.blue", "domain") in {
        (seed_value, seed_type)
        for seed_value, seed_type, _relation_type, _confidence, _metadata in verified_name_search_pivots
    }

    non_bluesky_pivots = engine._extract_social_profile_pivots(
        {"platform": "twitter", "handle": "security.acme.example"},
        source_label="artifact_social_url_extract",
        platform="twitter",
    )
    assert ("security.acme.example", "domain") not in {
        (seed_value, seed_type)
        for seed_value, seed_type, _relation_type, _confidence, _metadata in non_bluesky_pivots
    }


def test_synthesis_engine_promotes_verified_claimed_and_associated_domain_aliases(
    tmp_path: Path,
) -> None:
    engine = EngagementSynthesisEngine(tmp_path / "engagement.db", 1001)

    pivots = engine._extract_social_profile_pivots(
        {
            "platform": "github",
            "verifiedDomains": [
                "verified.acme.example",
                {"value": "https://proof.acme.example/.well-known/security.txt"},
                "github.com",
            ],
            "claimedDomains": [{"domain": "*.claimed.acme.example"}],
            "associatedDomains": [
                {"hostname": "docs.acme.example"},
                "applinks:app.acme.co.uk",
                {"value": "webcredentials:auth.acme.example"},
            ],
            "associatedDomain": "pages.dev",
        },
        source_label="epieos",
        platform="github",
    )
    pivot_map = {
        (seed_value, seed_type): metadata
        for seed_value, seed_type, _relation_type, _confidence, metadata in pivots
    }

    assert pivot_map[("verified.acme.example", "subdomain")]["rule"] == "social_profile_domain"
    assert pivot_map[("proof.acme.example", "subdomain")]["rule"] == "social_profile_domain"
    assert pivot_map[("claimed.acme.example", "subdomain")]["rule"] == "social_profile_domain"
    assert pivot_map[("docs.acme.example", "subdomain")]["rule"] == "social_profile_domain"
    assert pivot_map[("app.acme.co.uk", "subdomain")]["rule"] == "social_profile_domain"
    assert pivot_map[("auth.acme.example", "subdomain")]["rule"] == "social_profile_domain"
    assert ("acme.example", "domain") in pivot_map
    assert ("acme.co.uk", "domain") in pivot_map
    assert ("co.uk", "domain") not in pivot_map
    assert ("github.com", "domain") not in pivot_map
    assert ("pages.dev", "domain") not in pivot_map


