def test_synthesis_engine_parallelizes_legacy_social_profile_rows_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    engine = EngagementSynthesisEngine(db_path, 1001)
    active = 0
    peak = 0
    lock = threading.Lock()
    delays = {
        "one": 0.05,
        "two": 0.01,
        "three": 0.03,
        "four": 0.02,
        "five": 0.04,
    }
    captured_rows: list[dict[str, Any]] = []

    con = sqlite3.connect(db_path)
    try:
        con.execute(
            """
            CREATE TABLE social_profiles (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                engagement_id INTEGER,
                email TEXT,
                platform TEXT,
                profile_url TEXT,
                display_name TEXT
            )
            """
        )
        con.executemany(
            """
            INSERT INTO social_profiles
                (engagement_id, email, platform, profile_url, display_name)
            VALUES (?, ?, ?, ?, ?)
            """,
            [
                (1001, "one@acme.example", "github", "https://github.com/one", "One Example"),
                (
                    1001,
                    "two@acme.example",
                    "linkedin",
                    "https://linkedin.example/two",
                    "Two Example",
                ),
                (1001, "three@acme.example", "twitter", "https://x.com/three", "Three Example"),
                (1001, "four@acme.example", "", "https://profiles.example/four", "Four Example"),
                (
                    1001,
                    "five@acme.example",
                    "mastodon",
                    "https://mastodon.social/@five",
                    "Five Example",
                ),
            ],
        )
        con.commit()
    finally:
        con.close()

    original_legacy_row = EngagementSynthesisEngine._legacy_social_profile_candidate_row

    def _fake_legacy_social_profile_candidate_row(row: Any) -> dict[str, str] | None:
        label = str(row["display_name"] or "").split(" ", 1)[0].lower()
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[label])
            return original_legacy_row(row)
        finally:
            with lock:
                active -= 1

    def _fake_social_profile_candidates_from_rows(
        self,
        rows: list[Any],
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        del self, seed_depths
        captured_rows.extend(rows)
        return []

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_legacy_social_profile_candidate_row",
        staticmethod(_fake_legacy_social_profile_candidate_row),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_candidates_from_rows",
        _fake_social_profile_candidates_from_rows,
    )

    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        values = engine._derive_social_profile_candidates(con, {})
    finally:
        con.close()

    assert values == []
    assert peak == 4
    assert [row["email"] for row in captured_rows] == [
        "one@acme.example",
        "two@acme.example",
        "three@acme.example",
        "four@acme.example",
        "five@acme.example",
    ]
    assert [row["source"] for row in captured_rows] == [
        "github",
        "linkedin",
        "twitter",
        "epieos",
        "mastodon",
    ]
    assert [json.loads(row["profile_data"]) for row in captured_rows] == [
        {
            "source": "epieos",
            "platform": "github",
            "profile_url": "https://github.com/one",
            "display_name": "One Example",
        },
        {
            "source": "epieos",
            "platform": "linkedin",
            "profile_url": "https://linkedin.example/two",
            "display_name": "Two Example",
        },
        {
            "source": "epieos",
            "platform": "twitter",
            "profile_url": "https://x.com/three",
            "display_name": "Three Example",
        },
        {
            "source": "epieos",
            "platform": "",
            "profile_url": "https://profiles.example/four",
            "display_name": "Four Example",
        },
        {
            "source": "epieos",
            "platform": "mastodon",
            "profile_url": "https://mastodon.social/@five",
            "display_name": "Five Example",
        },
    ]


