def test_synthesis_engine_parallelizes_social_profile_embedded_container_key_scans(
    monkeypatch,
) -> None:
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {
        "links": 0.05,
        "accounts": 0.01,
        "profile": 0.03,
        "contact": 0.02,
    }
    original_entry = EngagementSynthesisEngine._social_profile_embedded_container_key_items

    def _tracking_entry(
        cls,
        item_key: tuple[dict[str, Any], str],
    ) -> list[Any]:
        del cls
        _item, key = item_key
        nonlocal active, peak, entered
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[str(key)])
            return original_entry(item_key)
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_SOCIAL_PROFILE_RAW_LINK_LIST_KEYS",
        ("links", "accounts"),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_SOCIAL_PROFILE_NESTED_PROFILE_KEYS",
        ("profile", "contact"),
    )
    monkeypatch.setattr(
        EngagementSynthesisEngine,
        "_social_profile_embedded_container_key_items",
        classmethod(_tracking_entry),
    )

    values = EngagementSynthesisEngine._social_profile_embedded_container_items(
        {
            "links": [{"label": "one"}],
            "accounts": [{"label": "two"}],
            "profile": {"label": "three"},
            "contact": [{"label": "four"}, {"label": "five"}],
        }
    )

    assert peak == 4
    assert values == [
        {"label": "one"},
        {"label": "two"},
        {"label": "three"},
        {"label": "four"},
        {"label": "five"},
    ]


