def test_synthesis_engine_promotes_epieos_matrix_federated_and_nostr_identities(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    _bootstrap_engagement(db_path)
    npub = "npub1" + "q" * 58

    parsed_profiles = _parse_epieos_response(
        {
            "email": "security@acme.example",
            "matrix": {
                "mxid": "@matrixblue:matrix.acme.example",
                "name": "Matrix Blue",
            },
            "activitypub": {
                "actorUrl": "https://social.acme.example/users/fedblue",
                "name": "Fed Blue",
            },
            "webfinger": {
                "subject": "acct:webfingerblue@wf.acme.example",
                "name": "WebFinger Blue",
            },
            "nostr": {
                "npub": npub,
                "name": "Nostr Blue",
            },
            "matrix_room": {
                "platform": "matrix",
                "profileUrl": "https://matrix.to/#/#public-room:matrix.acme.example",
            },
        }
    )

    con = sqlite3.connect(db_path)
    try:
        con.execute(
            """
            CREATE TABLE IF NOT EXISTS social_profiles (
                id INTEGER PRIMARY KEY,
                engagement_id INTEGER NOT NULL,
                email TEXT NOT NULL,
                source TEXT NOT NULL DEFAULT 'epieos',
                profile_data TEXT,
                queried_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(engagement_id, email, source)
            )
            """
        )
        con.execute(
            """
            INSERT INTO social_profiles (engagement_id, email, source, profile_data)
            VALUES (?, ?, ?, ?)
            """,
            (
                1001,
                "security@acme.example",
                "epieos:matrix-fediverse-nostr",
                json.dumps(parsed_profiles),
            ),
        )
        con.commit()
    finally:
        con.close()

    summary = EngagementSynthesisEngine(db_path, 1001, depth_limit=3).run()

    assert summary.seeds_inserted >= 8
    assert summary.relations_inserted >= 8

    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        seed_rows = {
            (str(row["seed_value"]), str(row["seed_type"])): json.loads(
                str(row["metadata_json"] or "{}")
            )
            for row in con.execute(
                """
                SELECT seed_value, seed_type, metadata_json
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("matrixblue", "username") in seed_rows
        assert ("fedblue", "username") in seed_rows
        assert ("webfingerblue", "username") in seed_rows
        assert (npub, "username") in seed_rows
        assert ("Matrix Blue", "name") in seed_rows
        assert ("Fed Blue", "name") in seed_rows
        assert ("WebFinger Blue", "name") in seed_rows
        assert ("Nostr Blue", "name") in seed_rows
        assert ("matrix.acme.example", "subdomain") in seed_rows
        assert ("social.acme.example", "subdomain") in seed_rows
        assert ("wf.acme.example", "subdomain") in seed_rows
        assert ("public-room", "username") not in seed_rows
        assert seed_rows[("matrixblue", "username")]["platform"] == "matrix"
        assert (
            seed_rows[("matrix.acme.example", "subdomain")]["rule"]
            == "social_profile_matrix_homeserver"
        )
        assert (
            seed_rows[("social.acme.example", "subdomain")]["rule"]
            == "social_profile_federated_instance"
        )
        assert (
            seed_rows[("wf.acme.example", "subdomain")]["rule"]
            == "social_profile_federated_instance"
        )

        relation_rows = {
            (str(row[0]), str(row[1]), str(row[2]))
            for row in con.execute(
                """
                SELECT src.seed_value, dst.seed_value, sr.relation_type
                FROM seed_relations sr
                JOIN engagement_seeds src ON src.id=sr.source_seed_id
                JOIN engagement_seeds dst ON dst.id=sr.target_seed_id
                WHERE sr.engagement_id=1001
                """
            ).fetchall()
        }
        assert ("security@acme.example", "matrixblue", "same_entity") in relation_rows
        assert ("security@acme.example", "fedblue", "same_entity") in relation_rows
        assert ("security@acme.example", "webfingerblue", "same_entity") in relation_rows
        assert ("security@acme.example", npub, "same_entity") in relation_rows
        assert ("security@acme.example", "matrix.acme.example", "related_asset") in relation_rows
        assert ("security@acme.example", "social.acme.example", "related_asset") in relation_rows
        assert ("security@acme.example", "wf.acme.example", "related_asset") in relation_rows
    finally:
        con.close()


