def test_artifact_queue_processor_extracts_mobile_configs_and_feedback_seeds(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifacts"
    artifact_root.mkdir()
    _bootstrap_engagement(db_path)

    apk_path = artifact_root / "acme-app.apk"
    with zipfile.ZipFile(apk_path, "w") as zf:
        zf.writestr(
            "google-services.json",
            """
            {
              "project_info": {
                "project_id": "acme-firebase-prod",
                "firebase_url": "https://acme-firebase-prod.firebaseio.com",
                "storage_bucket": "acme-firebase-prod.appspot.com"
              },
              "client": [
                {
                  "api_key": [
                    { "current_key": "AIzaSyDUMMYKEY1234567890" }
                  ]
                }
              ]
            }
            """.strip(),
        )
        zf.writestr(
            "assets/supabase.js",
            """
            export const url = "https://acmeproj123.supabase.co";
            export const anon = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImFjbWVwcm9qMTIzIiwicm9sZSI6ImFub24ifQ.signature123";
            export const owner = "mobile-owner@acme.example";
            export const endpoint = "https://mobile.acme.example/review";
            """.strip(),
        )

    processor = ArtifactQueueProcessor(db_path, 1001)
    queued = processor.ingest_local_artifacts([artifact_root])
    summary = processor.process()
    synthesis_summary = EngagementSynthesisEngine(db_path, 1001, depth_limit=3).run()

    assert queued >= 1
    assert summary.processed >= 1
    assert summary.firebase_projects >= 1
    assert summary.supabase_configs >= 1
    assert summary.discovered_seeds >= 5
    assert "acme.example" in synthesis_summary.root_domains
    assert "acme-firebase-prod" not in synthesis_summary.root_domains
    assert "acmeproj123" not in synthesis_summary.root_domains

    con = sqlite3.connect(db_path)
    try:
        cloud_assets = con.execute(
            """
            SELECT asset_type, identifier
            FROM cloud_assets
            WHERE engagement_id=1001
            ORDER BY asset_type, identifier
            """
        ).fetchall()
        assert ("firebase", "acme-firebase-prod") in cloud_assets
        assert ("gcs", "acme-firebase-prod.appspot.com") in cloud_assets
        assert ("supabase", "acmeproj123") in cloud_assets

        key_findings = con.execute(
            "SELECT service, pattern_name FROM key_scanner_findings WHERE engagement_id=1001 ORDER BY service"
        ).fetchall()
        assert ("firebase", "firebase_mobile_config") in key_findings
        assert ("supabase", "supabase_mobile_config") in key_findings

        artifact_status = con.execute(
            "SELECT status FROM artifact_queue WHERE engagement_id=1001"
        ).fetchone()[0]
        assert artifact_status == "parsed"

        seeds = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("acme-firebase-prod", "other") in seeds
        assert ("https://storage.googleapis.com/acme-firebase-prod.appspot.com", "url") in seeds
        assert ("https://acmeproj123.supabase.co", "url") in seeds
        assert ("acmeproj123", "other") in seeds
        assert ("mobile-owner@acme.example", "email") in seeds
        assert ("https://mobile.acme.example/review", "url") in seeds
        assert ("acmeproj123.supabase.co", "subdomain") not in seeds
        assert ("acmeproj123.supabase.co", "domain") not in seeds
        assert ("acme-firebase-prod.firebaseio.com", "subdomain") not in seeds
        assert ("acme-firebase-prod.firebaseio.com", "domain") not in seeds

        emails = {
            row[0]
            for row in con.execute("SELECT email FROM emails WHERE engagement_id=1001").fetchall()
        }
        assert "mobile-owner@acme.example" in emails
    finally:
        con.close()


def test_artifact_queue_processor_preserves_source_relative_child_seed_depth(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifacts"
    artifact_root.mkdir()
    _bootstrap_engagement(db_path)

    source_url = "https://downloads.acme.example/second-stage/config.env"
    config_path = artifact_root / "config.env"
    config_path.write_text(
        dedent(
            """
            CONTACT_EMAIL=artifact-depth-owner@acme.example
            API_URL=https://depth-api.acme.example/v1
            FIREBASE_URL=https://depth-firebase.firebaseio.com
            """
        ).strip(),
        encoding="utf-8",
    )

    con = sqlite3.connect(db_path)
    try:
        con.execute(
            """
            INSERT INTO engagement_seeds
                (engagement_id, seed_value, seed_type, source, status, depth, confidence, metadata_json)
            VALUES (1001, ?, 'url', 'cross_reference', 'pending', 2, 0.82, '{}')
            """,
            (source_url,),
        )
        con.execute(
            """
            INSERT INTO artifact_queue
                (engagement_id, source_url, local_path, artifact_type, discovered_from, status, metadata_json)
            VALUES (1001, ?, ?, 'config', 'engagement_seed', 'downloaded', '{}')
            """,
            (source_url, config_path.resolve().as_posix()),
        )
        con.commit()
    finally:
        con.close()

    summary = ArtifactQueueProcessor(db_path, 1001).process()
    assert summary.processed == 1

    con = sqlite3.connect(db_path)
    try:
        depths = {
            (str(row[0]), str(row[1])): int(row[2])
            for row in con.execute(
                """
                SELECT seed_value, seed_type, depth
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert depths[(source_url, "url")] == 2
        assert depths[("artifact-depth-owner@acme.example", "email")] == 3
        assert depths[("https://depth-api.acme.example/v1", "url")] == 3

        relations = {
            (str(row[0]), str(row[1]), str(row[2]), str(row[3] or ""))
            for row in con.execute(
                """
                SELECT src.seed_value, dst.seed_value, sr.relation_type, sr.evidence_json
                FROM seed_relations sr
                JOIN engagement_seeds src ON src.id=sr.source_seed_id
                JOIN engagement_seeds dst ON dst.id=sr.target_seed_id
                WHERE sr.engagement_id=1001
                """
            ).fetchall()
        }
        assert any(
            src == source_url
            and dst == "artifact-depth-owner@acme.example"
            and relation == "derived_from"
            and "artifact_seed_provenance" in evidence
            for src, dst, relation, evidence in relations
        )
        assert any(
            src == source_url
            and dst == "https://depth-api.acme.example/v1"
            and relation == "derived_from"
            and "artifact_seed_provenance" in evidence
            for src, dst, relation, evidence in relations
        )
    finally:
        con.close()


def test_artifact_queue_processor_does_not_requeue_unchanged_parsed_local_artifact(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifacts"
    artifact_root.mkdir()
    _bootstrap_engagement(db_path)

    config_path = artifact_root / "static-config.yaml"
    config_path.write_text(
        dedent(
            """
            apiVersion: v1
            kind: ConfigMap
            metadata:
              name: acme-static-config
            data:
              CONTACT_EMAIL: replay-owner@acme.example
              PORTAL_URL: https://replay.acme.example/portal
            """
        ).strip(),
        encoding="utf-8",
    )

    processor = ArtifactQueueProcessor(db_path, 1001)

    assert processor.ingest_local_artifacts([artifact_root]) == 1
    first_summary = processor.process()
    assert first_summary.processed == 1

    assert processor.ingest_local_artifacts([artifact_root]) == 0
    second_summary = processor.process()
    assert second_summary.processed == 0
    assert second_summary.failed == 0

    con = sqlite3.connect(db_path)
    try:
        row = con.execute(
            """
            SELECT status, discovered_from
            FROM artifact_queue
            WHERE engagement_id=1001 AND source_url=?
            """,
            (config_path.resolve().as_posix(),),
        ).fetchone()
        assert row == ("parsed", "local_filesystem")
    finally:
        con.close()


