    assert queued >= 5
    assert summary.processed >= 5
    assert summary.discovered_seeds >= 9

    con = sqlite3.connect(db_path)
    try:
        emails = {
            row[0]
            for row in con.execute("SELECT email FROM emails WHERE engagement_id=1001").fetchall()
        }
        for expected_email in {
            "mcp-owner@acme.example",
            "cursor-owner@acme.example",
            "claude-agent-owner@acme.example",
            "codex-owner@acme.example",
            "windsurf-owner@acme.example",
        }:
            assert expected_email in emails

        seeds = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        for expected_url in {
            "https://mcp.acme.example/sse",
            "https://cursor.acme.example/rules",
            "https://claude-agent.acme.example/api",
            "https://codex.acme.example/api",
            "https://windsurf.acme.example/workflows",
        }:
            assert (expected_url, "url") in seeds
        assert ("mcp-owner@acme.example", "email") in seeds
        assert ("cursor-owner@acme.example", "email") in seeds
        assert ("codex-owner@acme.example", "email") in seeds

        cloud_assets = con.execute(
            """
            SELECT asset_type, identifier
            FROM cloud_assets
            WHERE engagement_id=1001
            ORDER BY asset_type, identifier
            """
        ).fetchall()
        assert ("aws_s3", "acme-agent-bucket") in cloud_assets
        assert ("firebase", "mcp-firebase") in cloud_assets
        assert ("gcs", "acme-codex-gcs") in cloud_assets
        assert ("supabase", "cursorvault") in cloud_assets

        artifact_meta = {
            row[0]: json.loads(str(row[1] or "{}"))
            for row in con.execute(
                """
                SELECT source_url, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert artifact_meta[mcp_path.resolve().as_posix()]["format"] == "mcp-config"
        assert artifact_meta[cursor_rule_path.resolve().as_posix()]["format"] == "cursor-rules"
        assert (
            artifact_meta[claude_desktop_path.resolve().as_posix()]["format"]
            == "claude-desktop-config"
        )
        assert artifact_meta[codex_path.resolve().as_posix()]["format"] == "codex-config"
        assert artifact_meta[windsurf_path.resolve().as_posix()]["format"] == "windsurf-rules"
    finally:
        con.close()


