def test_artifact_queue_processor_extracts_scheduler_cron_artifacts(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifact_scheduler_cron"
    cron_d = artifact_root / "etc" / "cron.d"
    cron_d.mkdir(parents=True)
    _bootstrap_engagement(db_path)

    cron_job_path = cron_d / "acme-backup"
    cron_job_path.write_text(
        dedent(
            """
            MAILTO=cron-owner@acme.example
            */15 * * * * root curl -fsS https://cron.acme.example/health
            10 2 * * * root /usr/local/bin/backup --bucket s3://acme-cron-bucket/backups/latest.tar.gz
            30 2 * * * root echo gs://acme-cron-gcs/reports/final.json
            """
        ).strip(),
        encoding="utf-8",
    )

    crontab_path = artifact_root / "crontab"
    crontab_path.write_text(
        dedent(
            """
            SHELL=/bin/sh
            0 * * * * curl https://crontab.acme.example/status && echo crontab-owner@acme.example
            5 * * * * echo https://cronvault.supabase.co/rest/v1
            """
        ).strip(),
        encoding="utf-8",
    )

    archive_path = artifact_root / "cron-bundle.zip"
    with zipfile.ZipFile(archive_path, "w") as zf:
        zf.writestr(
            "cron.daily/report.cron",
            dedent(
                """
                0 5 * * * root echo https://daily-cron-firebase.firebaseio.com
                0 6 * * * root echo daily-cron-owner@acme.example
                """
            ).strip(),
        )

    assert _classify_artifact_name(cron_job_path) == "config"
    assert _classify_artifact_name("notes/acme-backup") is None
    assert _artifact_format_label(cron_job_path) == "cron-config"
    assert _artifact_format_label(crontab_path) == "cron-config"
    assert _artifact_format_label("cron.daily/report.cron") == "cron-config"
    assert (
        _classify_remote_artifact_url("https://downloads.acme.example/etc/cron.d/acme-backup")
        == "config"
    )
    assert (
        _select_remote_artifact_filename(
            42,
            "https://downloads.acme.example/etc/cron.d/acme-backup",
            "config",
        )
        == "acme-backup.cron"
    )
    assert _suffix_from_content_type("text/x-crontab") == ".cron"

    processor = ArtifactQueueProcessor(db_path, 1001)
    queued = processor.ingest_local_artifacts([artifact_root])
    summary = processor.process()

    assert queued >= 3
    assert summary.processed >= 3
    assert summary.discovered_seeds >= 8

    con = sqlite3.connect(db_path)
    try:
        emails = {
            row[0]
            for row in con.execute("SELECT email FROM emails WHERE engagement_id=1001").fetchall()
        }
        assert "cron-owner@acme.example" in emails
        assert "crontab-owner@acme.example" in emails
        assert "daily-cron-owner@acme.example" in emails

        seeds = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("https://cron.acme.example/health", "url") in seeds
        assert ("https://crontab.acme.example/status", "url") in seeds
        assert ("https://cronvault.supabase.co/rest/v1", "url") in seeds
        assert ("https://daily-cron-firebase.firebaseio.com", "url") in seeds
        assert ("cron-owner@acme.example", "email") in seeds
        assert ("crontab-owner@acme.example", "email") in seeds

        cloud_assets = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT asset_type, identifier
                FROM cloud_assets
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("aws_s3", "acme-cron-bucket") in cloud_assets
        assert ("gcs", "acme-cron-gcs") in cloud_assets
        assert ("supabase", "cronvault") in cloud_assets
        assert ("firebase", "daily-cron-firebase") in cloud_assets

        artifact_meta = {
            row[0]: json.loads(str(row[1] or "{}"))
            for row in con.execute(
                """
                SELECT source_url, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert artifact_meta[cron_job_path.resolve().as_posix()]["format"] == "cron-config"
        assert artifact_meta[crontab_path.resolve().as_posix()]["format"] == "cron-config"
        assert artifact_meta[archive_path.resolve().as_posix()]["format"] == "zip"
        assert artifact_meta[archive_path.resolve().as_posix()]["payload_count"] >= 1
    finally:
        con.close()


