def test_artifact_queue_processor_extracts_container_orchestration_metadata_artifacts(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifact_container_orchestration"
    artifact_root.mkdir()
    kube_dir = artifact_root / ".kube"
