        assert artifact_meta[envrc_path.resolve().as_posix()]["format"] == "direnv"
        assert artifact_meta[mise_path.resolve().as_posix()]["format"] == "mise-config"
        assert artifact_meta[doppler_path.resolve().as_posix()]["format"] == "doppler-config"
        assert artifact_meta[infisical_path.resolve().as_posix()]["format"] == "infisical-config"
