def test_artifact_queue_processor_extracts_observability_config_targets(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifact_observability"
    artifact_root.mkdir(parents=True, exist_ok=True)
    _bootstrap_engagement(db_path)

    prometheus_path = artifact_root / "prometheus.yml"
    prometheus_path.write_text(
        dedent(
            """
            global:
              scrape_interval: 15s
            remote_write:
              - url: https://metrics.acme.example/api/v1/write
            alerting:
              alertmanagers:
                - scheme: https
                  static_configs:
                    - targets:
                        - alerts.acme.example:9093
            scrape_configs:
              - job_name: api
                scheme: https
                static_configs:
                  - targets:
                      - api.acme.example:9443
                      - localhost:9090
                      - 127.0.0.1:9100
                      - "{{ template_target }}:9100"
                    labels:
                      owner: prom-owner@acme.example
              - job_name: workers
                static_configs:
                  - targets:
                      - worker.acme.example:9100/custom
            """
        ).strip(),
        encoding="utf-8",
    )

    alertmanager_path = artifact_root / "alertmanager.yml"
    alertmanager_path.write_text(
        dedent(
            """
            route:
              receiver: ops
            receivers:
              - name: ops
                email_configs:
                  - to: alert-owner@acme.example
                webhook_configs:
                  - url: https://hooks.acme.example/alert
            """
        ).strip(),
        encoding="utf-8",
    )

    grafana_dir = artifact_root / "grafana" / "provisioning" / "datasources"
    grafana_dir.mkdir(parents=True, exist_ok=True)
    grafana_path = grafana_dir / "datasources.yaml"
    grafana_path.write_text(
        dedent(
            """
            apiVersion: 1
            datasources:
              - name: Prometheus
                type: prometheus
                url: https://grafana-prometheus.acme.example
              - name: Loki
                type: loki
                url: http://loki-gateway.acme.example:3100
              - name: Local Grafana
                type: grafana
                url: localhost:3000
            """
        ).strip(),
        encoding="utf-8",
    )

    otel_path = artifact_root / "otel-collector-config.yaml"
    otel_path.write_text(
        dedent(
            """
            receivers:
              otlp:
                protocols:
                  grpc:
                    endpoint: 0.0.0.0:4317
            exporters:
              otlp:
                endpoint: traces.acme.example:4317
              prometheusremotewrite:
                endpoint: https://otel-metrics.acme.example/api/v1/write
            """
        ).strip(),
        encoding="utf-8",
    )

    tempo_path = artifact_root / "tempo.yaml"
    tempo_path.write_text(
        dedent(
            """
            distributor:
              receivers:
                otlp:
                  protocols:
                    grpc:
                      endpoint: tempo-ingest.acme.example:4317
            metrics_generator:
              remote_write:
                - url: https://tempo-metrics.acme.example/api/v1/write
            """
        ).strip(),
        encoding="utf-8",
    )

    processor = ArtifactQueueProcessor(db_path, 1001)
    queued = processor.ingest_local_artifacts([artifact_root])
    summary = processor.process()

    assert queued >= 5
    assert summary.processed >= 5
    assert summary.discovered_seeds >= 10

    con = sqlite3.connect(db_path)
    try:
        seeds = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("https://api.acme.example:9443", "url") in seeds
        assert ("https://alerts.acme.example:9093", "url") in seeds
        assert ("http://worker.acme.example:9100/custom", "url") in seeds
        assert ("https://metrics.acme.example/api/v1/write", "url") in seeds
        assert ("https://hooks.acme.example/alert", "url") in seeds
        assert ("https://grafana-prometheus.acme.example", "url") in seeds
        assert ("http://loki-gateway.acme.example:3100", "url") in seeds
        assert ("http://traces.acme.example:4317", "url") in seeds
        assert ("https://otel-metrics.acme.example/api/v1/write", "url") in seeds
        assert ("http://tempo-ingest.acme.example:4317", "url") in seeds
        assert ("https://tempo-metrics.acme.example/api/v1/write", "url") in seeds
        assert ("prom-owner@acme.example", "email") in seeds
        assert ("alert-owner@acme.example", "email") in seeds
        assert ("http://localhost:9090", "url") not in seeds
        assert ("http://127.0.0.1:9100", "url") not in seeds
        assert ("http://{{ template_target }}:9100", "url") not in seeds
        assert ("http://0.0.0.0:4317", "url") not in seeds
        assert ("http://localhost:3000", "url") not in seeds

        artifact_meta = {
            row[0]: json.loads(str(row[1] or "{}"))
            for row in con.execute(
                """
                SELECT source_url, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert artifact_meta[prometheus_path.resolve().as_posix()]["format"] == "prometheus-config"
        assert (
            artifact_meta[alertmanager_path.resolve().as_posix()]["format"] == "alertmanager-config"
        )
        assert artifact_meta[grafana_path.resolve().as_posix()]["format"] == "grafana-config"
        assert artifact_meta[otel_path.resolve().as_posix()]["format"] == "otel-config"
        assert artifact_meta[tempo_path.resolve().as_posix()]["format"] == "tempo-config"
    finally:
        con.close()


