def test_artifact_queue_processor_routes_cloudflare_refs_through_worker_pool(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    processor = ArtifactQueueProcessor(db_path, 1001)
    normalized = {
        "name": "acme-worker",
        "main": "src/index.ts",
        "pages_build_output_dir": "./dist",
        "r2_bucket_name": "assets-prod",
        "d1_database_name": "main-db",
        "kv_namespace_id": "cache-kv",
    }
    observed_ref_batches: list[list[tuple[str, str]]] = []
    original_batch = ArtifactQueueProcessor._run_ordered_local_batch

    def _tracking_batch(self, items, worker, *, default_factory):  # noqa: ANN001
        materialized = list(items)
        if getattr(worker, "__name__", "") == "_cloudflare_uri_candidate_entry":
            observed_ref_batches.append(
                [(str(family), str(value)) for family, value in materialized]
            )
        return original_batch(self, materialized, worker, default_factory=default_factory)

    monkeypatch.setattr(ArtifactQueueProcessor, "_run_ordered_local_batch", _tracking_batch)

    candidates = processor._yaml_cloudflare_structured_candidates(
        {},
        normalized,
        "wrangler.toml",
    )

    assert observed_ref_batches == [
        [
            ("r2", "assets-prod"),
            ("d1", "main-db"),
            ("kv", "cache-kv"),
            ("worker", "acme-worker"),
            ("pages", "acme-worker"),
        ]
    ]
    assert candidates == [
        "cloudflare-r2://assets-prod",
        "cloudflare-d1://main-db",
        "cloudflare-kv://cache-kv",
        "cloudflare-worker://acme-worker",
        "cloudflare-pages://acme-worker",
    ]


