def test_artifact_queue_processor_extracts_dockerconfigjson_registry_pivots(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifact_docker_config"
    artifact_root.mkdir()
    _bootstrap_engagement(db_path)

    kubernetes_docker_config = {
        "auths": {
            "registry.acme.example": {
                "username": "registry-bot@acme.example",
                "email": "registry-owner@acme.example",
                "auth": base64.b64encode(b"registry-bot@acme.example:do-not-store").decode("ascii"),
            }
        }
    }
    secret_path = artifact_root / "registry-secret.yaml"
    secret_path.write_text(
        dedent(
            f"""
        apiVersion: v1
        kind: Secret
        metadata:
          name: registry-secret
        type: kubernetes.io/dockerconfigjson
        data:
          .dockerconfigjson: {base64.b64encode(json.dumps(kubernetes_docker_config).encode("utf-8")).decode("ascii")}
        """
        ).strip(),
        encoding="utf-8",
    )

    standalone_docker_config = {
        "auths": {
            "https://registry2.acme.example/team": {
                "email": "registry2-owner@acme.example",
                "auth": base64.b64encode(b"robot-two@acme.example:do-not-store-either").decode(
                    "ascii"
                ),
            }
        },
        "credHelpers": {
            "ghcr.io": "desktop",
            "registry3.acme.example/team": "ecr-login",
        },
    }
    standalone_path = artifact_root / ".dockerconfigjson"
    standalone_path.write_text(json.dumps(standalone_docker_config), encoding="utf-8")

    legacy_dockercfg = {
        "legacy-registry.acme.example": {
            "email": "legacy-registry-owner@acme.example",
            "auth": base64.b64encode(b"legacy-robot@acme.example:legacy-do-not-store").decode(
                "ascii"
            ),
        }
    }
    legacy_path = artifact_root / ".dockercfg"
    legacy_path.write_text(json.dumps(legacy_dockercfg), encoding="utf-8")

    processor = ArtifactQueueProcessor(db_path, 1001)
    queued = processor.ingest_local_artifacts([artifact_root])
    summary = processor.process()

    assert queued >= 2
    assert summary.processed >= 2
    assert summary.discovered_seeds >= 4

    con = sqlite3.connect(db_path)
    try:
        emails = {
            row[0]
            for row in con.execute("SELECT email FROM emails WHERE engagement_id=1001").fetchall()
        }
        assert "registry-bot@acme.example" in emails
        assert "registry-owner@acme.example" in emails
        assert "registry2-owner@acme.example" in emails
        assert "robot-two@acme.example" in emails
        assert "legacy-registry-owner@acme.example" in emails
        assert "legacy-robot@acme.example" in emails

        seeds = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("https://registry.acme.example", "url") in seeds
        assert ("https://registry2.acme.example/team", "url") in seeds
        assert ("https://ghcr.io", "url") in seeds
        assert ("https://registry3.acme.example/team", "url") in seeds
        assert ("https://legacy-registry.acme.example", "url") in seeds

        artifact_meta = {
            row[0]: json.loads(str(row[1] or "{}"))
            for row in con.execute(
                """
                SELECT source_url, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert artifact_meta[secret_path.resolve().as_posix()]["format"] == "yaml"
        assert artifact_meta[standalone_path.resolve().as_posix()]["format"] == "dockerconfigjson"
        assert artifact_meta[legacy_path.resolve().as_posix()]["format"] == "dockercfg"

        persisted_text = json.dumps({"emails": sorted(emails), "seeds": sorted(seeds)})
        assert "do-not-store" not in persisted_text
        assert "do-not-store-either" not in persisted_text
        assert "legacy-do-not-store" not in persisted_text
    finally:
        con.close()


def test_docker_auth_config_candidates_use_bounded_static_workers_and_preserve_order(
    monkeypatch,
) -> None:
    monkeypatch.setenv("FORGE_STATIC_ARTIFACT_MAX_WORKERS", "4")
    original_entry = ArtifactQueueProcessor._docker_auth_config_auth_entry_candidates
    active = 0
    peak = 0
    lock = threading.Lock()
    delays = {
        "registry-one.acme.example": 0.05,
        "registry-two.acme.example": 0.01,
        "registry-three.acme.example": 0.03,
        "registry-four.acme.example": 0.02,
    }

    def _fake_docker_auth_config_auth_entry_candidates(
        item: tuple[Any, Any],
    ) -> list[str]:
        raw_registry, _raw_entry = item
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[str(raw_registry)])
            return original_entry(item)
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_docker_auth_config_auth_entry_candidates",
        staticmethod(_fake_docker_auth_config_auth_entry_candidates),
    )

    candidates = ArtifactQueueProcessor._docker_auth_config_candidates(
        {
            "auths": {
                "registry-one.acme.example": {"email": "one@acme.example"},
                "registry-two.acme.example": {"email": "two@acme.example"},
                "registry-three.acme.example": {"email": "three@acme.example"},
                "registry-four.acme.example": {"email": "four@acme.example"},
            }
        }
    )

    assert peak == 4
    assert candidates == [
        "https://registry-one.acme.example",
        "one@acme.example",
        "https://registry-two.acme.example",
        "two@acme.example",
        "https://registry-three.acme.example",
        "three@acme.example",
        "https://registry-four.acme.example",
        "four@acme.example",
    ]


def test_docker_auth_structured_env_scan_uses_bounded_static_workers_and_preserves_order(
    monkeypatch,
) -> None:
    monkeypatch.setenv("FORGE_STATIC_ARTIFACT_MAX_WORKERS", "4")
    original_entry = ArtifactQueueProcessor._docker_auth_structured_env_entry_candidates
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {
        "DOCKER_ALPHA_CONFIG": 0.05,
        "CONTAINER_REGISTRY_BETA": 0.01,
        "IGNORED_VALUE": 0.02,
        "INLINE_AUTH_JSON": 0.03,
    }

    def _tracking_entry(entry):  # noqa: ANN001
        nonlocal active, peak, entered
        raw_name, _raw_value = entry
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[str(raw_name)])
            return original_entry(entry)
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_docker_auth_structured_env_entry_candidates",
        staticmethod(_tracking_entry),
    )

    candidates = ArtifactQueueProcessor._docker_auth_structured_candidates_from_env_map(
        {
            "DOCKER_ALPHA_CONFIG": json.dumps(
                {"auths": {"registry-alpha.acme.example": {"email": "alpha@acme.example"}}}
            ),
            "CONTAINER_REGISTRY_BETA": json.dumps(
                {"auths": {"registry-beta.acme.example": {"email": "beta@acme.example"}}}
            ),
            "IGNORED_VALUE": "registry-ignored.acme.example",
            "INLINE_AUTH_JSON": json.dumps(
                {"auths": {"registry-inline.acme.example": {"email": "inline@acme.example"}}}
            ),
        }
    )

    assert peak == 4
    assert candidates == [
        "https://registry-alpha.acme.example",
        "alpha@acme.example",
        "https://registry-beta.acme.example",
        "beta@acme.example",
        "https://registry-inline.acme.example",
        "inline@acme.example",
    ]


