            ("https://playwright-live.acme.example", "url"),
            ("https://cypress-hostonly.acme.example/e2e", "url"),
            ("https://cypress-live.acme.example/api", "url"),
            ("https://testcafe-hostonly.acme.example/app", "url"),
            ("https://testcafe-live.acme.example", "url"),
            ("https://wdio-hostonly.acme.example/app", "url"),
