    dependabot_path = artifact_root / ".github" / "dependabot.yml"
    dependabot_path.parent.mkdir(parents=True, exist_ok=True)
    dependabot_path.write_text(
        dedent(
            """
            version: 2
            ownerEmail: dependabot-owner@acme.example
            dashboardUrl: https://dependabot.acme.example/dashboard
            firebase: https://dependabot-firebase.firebaseio.com
            registries:
              npm-github:
                type: npm-registry
                url: npm.pkg.github.com
              docker-ghcr:
                type: docker-registry
                url: ghcr.io
              private-pypi:
                type: python-index
                url: https://pypi.acme.example/simple/
              maven-central:
                type: maven-repository
                registry: repo.maven.apache.org
            updates:
              - package-ecosystem: npm
                directory: /
                registries:
                  - npm-github
              - package-ecosystem: docker
                directory: /containers
                registries:
                  - docker-ghcr
            """
        ).strip(),
        encoding="utf-8",
    )

    hadolintignore_path = artifact_root / ".hadolintignore"
    hadolintignore_path.write_text(
        dedent(
            """
            # owner hadolint-owner@acme.example
            # policy https://hadolint.acme.example/policies/docker
            # supabase https://hadolintvault.supabase.co/rest/v1
            DL3008
            """
        ).strip(),
        encoding="utf-8",
    )

    nested_bundle = artifact_root / "maintenance-configs.zip"
