def test_orm_config_artifact_format_labels_are_source_aware() -> None:
    assert _artifact_format_label("schema.prisma") == "prisma-schema"
    assert _artifact_format_label("prisma.config.ts") == "prisma-config"
    assert _artifact_format_label("drizzle.config.ts") == "drizzle-config"
    assert _artifact_format_label("ormconfig.json") == "typeorm-config"
    assert _artifact_format_label("database/data-source.ts") == "typeorm-config"
    assert _artifact_format_label("knexfile.js") == "knexfile"
    assert _artifact_format_label("liquibase.properties") == "liquibase-config"
    assert _artifact_format_label("flyway.conf") == "flyway-config"
    assert _artifact_format_label("data-source.ts") == "ts"
    assert _classify_artifact_name("schema.prisma") == "config"
    assert (
        _classify_remote_artifact_url("https://downloads.acme.example/prisma/schema.prisma")
        == "config"
    )
    assert (
        _select_remote_artifact_filename(
            42,
            "https://downloads.acme.example/prisma/schema.prisma",
            "config",
        )
        == "schema.prisma"
    )


