    assert _artifact_format_label("application.properties") == "properties"
    assert _artifact_format_label("appsettings.json") == "dotnet-appsettings"
    assert _artifact_format_label("web.config") == "dotnet-web-config"
    assert _artifact_format_label("alembic.ini") == "alembic-config"
    assert _artifact_format_label("laravel/config/database.php") == "laravel-database-config"
