def test_artifact_queue_processor_parallelizes_warc_record_summary_and_body_families_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    warc_path = tmp_path / "parallel-record-families.warc"
    job = types.SimpleNamespace(
        source_file=str(warc_path),
        member_name=warc_path.name,
        record_index=1,
        record=b"WARC/1.0",
    )
    active = 0
    peak = 0
    lock = threading.Lock()

    def _track_family(delay: float) -> None:
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delay)
        finally:
            with lock:
                active -= 1

    def _fake_warc_record_payload(
        _self,
        record: bytes,
    ) -> tuple[list[str], str]:
        assert record == b"WARC/1.0"
        return (["warc.start_line=WARC/1.0"], "warc-body@acme.example")

    def _fake_extract_warc_record_summary_payloads(
        _self,
        record_job,
        summary_lines,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        assert record_job.record_index == 1
        assert list(summary_lines) == ["warc.start_line=WARC/1.0"]
        _track_family(0.05)
        return [(record_job.source_file, f"{record_job.member_name}#warc-record-1", "summary")]

    def _fake_extract_warc_record_body_payloads(
        _self,
        record_job,
        body_text: str,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        assert record_job.record_index == 1
        assert body_text == "warc-body@acme.example"
        _track_family(0.01)
        return [(record_job.source_file, f"{record_job.member_name}#warc-body-1", "body")]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_warc_record_payload",
        _fake_warc_record_payload,
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_warc_record_summary_payloads",
        _fake_extract_warc_record_summary_payloads,
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_warc_record_body_payloads",
        _fake_extract_warc_record_body_payloads,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=2)
    payloads = processor._extract_warc_record_payloads(job)

    assert peak == 2
    assert payloads == [
        (str(warc_path), f"{warc_path.name}#warc-record-1", "summary"),
        (str(warc_path), f"{warc_path.name}#warc-body-1", "body"),
    ]


