def _classic_pcap_bytes(packet_payloads: list[bytes]) -> bytes:
    pcap_data = bytearray()
    pcap_data.extend(b"\xd4\xc3\xb2\xa1")
    pcap_data.extend(struct.pack("<HHIIII", 2, 4, 0, 0, 65535, 1))
    for index, payload in enumerate(packet_payloads, start=1):
        pcap_data.extend(struct.pack("<IIII", index, index * 1000, len(payload), len(payload)))
        pcap_data.extend(payload)
    return bytes(pcap_data)


def _pcapng_block(block_type: int, body: bytes) -> bytes:
    padded_body = body + (b"\x00" * ((4 - (len(body) % 4)) % 4))
    block_length = 12 + len(padded_body)
    return (
        struct.pack("<II", block_type, block_length) + padded_body + struct.pack("<I", block_length)
    )


def _pcapng_bytes(packet_payloads: list[bytes]) -> bytes:
    pcapng_data = bytearray()
    pcapng_data.extend(_pcapng_block(0x0A0D0D0A, struct.pack("<IHHq", 0x1A2B3C4D, 1, 0, -1)))
    pcapng_data.extend(_pcapng_block(0x00000001, struct.pack("<HHI", 1, 0, 65535)))
    for index, payload in enumerate(packet_payloads, start=1):
        body = struct.pack("<IIIII", 0, index, index * 1000, len(payload), len(payload)) + payload
        pcapng_data.extend(_pcapng_block(0x00000006, body))
    return bytes(pcapng_data)


def test_artifact_queue_processor_extracts_pcap_and_nested_pcapng_payloads(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifact_pcap"
    artifact_root.mkdir()
    _bootstrap_engagement(db_path)

    pcap_path = artifact_root / "traffic-capture.pcap"
    pcap_path.write_bytes(
        _classic_pcap_bytes(
            [
                (
                    b"GET https://portal.acme.example/api/session HTTP/1.1\r\n"
                    b"Host: portal.acme.example\r\n"
                    b"X-Owner: pcap-owner@acme.example\r\n"
                    b"X-Firebase: https://pcap-firebase.firebaseio.com\r\n"
                    b"X-Supabase: https://pcappipe.supabase.co\r\n"
                    b"X-Supabase-Key: "
                    b"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9."
                    b"eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBjYXBwaXBlIiwicm9sZSI6ImFub24ifQ.signature555\r\n"
                    b"X-Bucket: s3://acme-pcap-bucket/reports/latest.pdf\r\n"
                    b"\r\n"
                ),
            ]
        )
    )

    nested_zip_path = artifact_root / "capture-bundle.zip"
    nested_packet = (
        b"POST https://nested-pcap.acme.example/api/graph HTTP/1.1\r\n"
        b"Host: nested-pcap.acme.example\r\n"
        b"X-Contact: nested-pcap-owner@acme.example\r\n"
        b"\r\n"
    )
    with zipfile.ZipFile(nested_zip_path, "w") as zf:
        zf.writestr("captures/nested-session.pcapng", _pcapng_bytes([nested_packet]))

    processor = ArtifactQueueProcessor(db_path, 1001)
    queued = processor.ingest_local_artifacts([artifact_root])
    summary = processor.process()

    assert queued >= 2
    assert summary.processed >= 2
    assert summary.firebase_projects >= 1
    assert summary.supabase_configs >= 1
    assert summary.discovered_seeds >= 5

    con = sqlite3.connect(db_path)
    try:
        emails = {
            row[0]
            for row in con.execute("SELECT email FROM emails WHERE engagement_id=1001").fetchall()
        }
        assert "pcap-owner@acme.example" in emails
        assert "nested-pcap-owner@acme.example" in emails

        seeds = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("https://portal.acme.example/api/session", "url") in seeds
        assert ("https://nested-pcap.acme.example/api/graph", "url") in seeds
        assert ("pcap-owner@acme.example", "email") in seeds
        assert ("nested-pcap-owner@acme.example", "email") in seeds

        cloud_assets = con.execute(
            """
            SELECT asset_type, identifier
            FROM cloud_assets
            WHERE engagement_id=1001
            ORDER BY asset_type, identifier
            """
        ).fetchall()
        assert ("aws_s3", "acme-pcap-bucket") in cloud_assets
        assert ("firebase", "pcap-firebase") in cloud_assets
        assert ("supabase", "pcappipe") in cloud_assets

        artifact_meta = {
            row[0]: json.loads(str(row[1] or "{}"))
            for row in con.execute(
                """
                SELECT source_url, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert artifact_meta[pcap_path.resolve().as_posix()]["format"] == "pcap"
        assert artifact_meta[pcap_path.resolve().as_posix()]["metadata_payload_count"] >= 2
        assert artifact_meta[nested_zip_path.resolve().as_posix()]["format"] == "zip"
        assert artifact_meta[nested_zip_path.resolve().as_posix()]["metadata_payload_count"] >= 1
    finally:
        con.close()


