    payload_texts = {
        f"{mbox_path.name}.message-1.eml": "message-one@acme.example",
        f"{mbox_path.name}.message-2.eml": "message-two@acme.example",
        f"{mbox_path.name}.message-3.eml": "message-three@acme.example",
    }
    active = 0
    peak = 0
