    def _fake_extract_email_message_payloads(
        _self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        del data, depth
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[member_name])
            return [(source_file, member_name, payload_texts[member_name])]
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_email_message_payloads",
        _fake_extract_email_message_payloads,
    )

