    mbox = mailbox.mbox(str(mbox_path), create=True)
    try:
        for index in range(1, 6):
            message = EmailMessage()
            message["From"] = f"planning-{index}@acme.example"
            message["To"] = "ops@acme.example"
            message["Subject"] = f"Planning message {index}"
            message.set_content(f"Planning message {index} body")
            mbox.add(message)
        mbox.flush()
    finally:
        mbox.close()

    delays = {
        1: 0.05,
        2: 0.01,
        3: 0.03,
        4: 0.02,
        5: 0.04,
    }
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    original_entry = ArtifactQueueProcessor._mbox_message_job

    def _tracking_entry(message_job):  # noqa: ANN001
        nonlocal active, peak, entered
        index, _message_bytes = message_job
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[index])
            return original_entry(message_job)
        finally:
            with lock:
                active -= 1

    def _fake_extract_mbox_message_payloads(
        _self,
        message_jobs,
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        del depth
        assert [index for index, _message_bytes in message_jobs] == [1, 2, 3, 4, 5]
        return [
            (
                source_file,
                f"{member_name}.message-{index}.eml",
                f"message-{index}@acme.example",
            )
            for index, _message_bytes in message_jobs
        ]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_mbox_message_job",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_mbox_message_payloads",
        _fake_extract_mbox_message_payloads,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=8)
    payloads = processor._extract_mbox_bytes_payloads(
        mbox_path.read_bytes(),
        str(mbox_path),
        mbox_path.name,
        depth=0,
    )

    assert peak >= 4
    assert payloads == [
        (str(mbox_path), f"{mbox_path.name}#mbox-meta", "message_count=5"),
        (str(mbox_path), f"{mbox_path.name}.message-1.eml", "message-1@acme.example"),
        (str(mbox_path), f"{mbox_path.name}.message-2.eml", "message-2@acme.example"),
        (str(mbox_path), f"{mbox_path.name}.message-3.eml", "message-3@acme.example"),
        (str(mbox_path), f"{mbox_path.name}.message-4.eml", "message-4@acme.example"),
        (str(mbox_path), f"{mbox_path.name}.message-5.eml", "message-5@acme.example"),
    ]


