def test_artifact_queue_processor_parallelizes_tar_member_payload_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    archive_path = tmp_path / "parallel-archive-payload-entries.tar"
    member_payloads = {
        "docs/member-1.txt": b"member one",
        "docs/member-2.txt": b"member two",
        "docs/member-3.txt": b"member three",
    }
    with tarfile.open(archive_path, "w") as tf:
        for member_name, payload in member_payloads.items():
            info = tarfile.TarInfo(member_name)
            info.size = len(payload)
            tf.addfile(info, BytesIO(payload))

    delays = {0: 0.05, 1: 0.01, 2: 0.03}
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    original_entry = ArtifactQueueProcessor._artifact_payload_tuple_batch_entries

    def _tracking_entry(payload_batch):  # noqa: ANN001
        nonlocal active, peak, entered
        batch_index, _batch = payload_batch
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 3:
                gate.set()
        try:
            if current_entered <= 3:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[batch_index])
            return original_entry(payload_batch)
        finally:
            with lock:
                active -= 1

    def _fake_extract_member_data_payloads(
        _self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        assert data == member_payloads[member_name]
        del depth
        return [
            (source_file, member_name, f"{Path(member_name).stem}@acme.example"),
            (source_file, f"{member_name}#empty", ""),
            ("", "ignored", "ignored"),
        ]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_artifact_payload_tuple_batch_entries",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_member_data_payloads",
        _fake_extract_member_data_payloads,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=4)
    with tarfile.open(archive_path) as tf:
        payloads = processor._extract_text_payloads_from_tar(
            tf,
            str(archive_path),
            depth=0,
        )

    assert peak == 3
    assert payloads == [
        (str(archive_path), "docs/member-1.txt", "member-1@acme.example"),
        (str(archive_path), "docs/member-2.txt", "member-2@acme.example"),
        (str(archive_path), "docs/member-3.txt", "member-3@acme.example"),
    ]


