    def _tracking_entry(name):  # noqa: ANN001
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[name])
            return original_entry(name)
        finally:
            with lock:
                active -= 1

    def _fake_extract_supabase_from_text(self, text, source_file, extract_path):  # noqa: ANN001
        del self, text
        ref = Path(extract_path).stem.lower()
        return [
            SupabaseConfig(ref, f"https://{ref}.supabase.co", "anon", source_file, extract_path)
        ]

    monkeypatch.setattr(
        FirebaseExtractor,
        "_supabase_ipa_member_entry",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        FirebaseExtractor,
        "_extract_supabase_from_text",
        _fake_extract_supabase_from_text,
    )

    configs = extractor.extract_supabase_ipa(ipa_path)

    assert peak == 4
    assert [config.project_ref for config in configs] == [
        "alpha",
        "bravo",
        "charlie",
        "delta",
        "echo",
    ]
    assert [config.extract_path for config in configs] == [
        "Payload/Alpha.plist",
        "Payload/Bravo.json",
        "Payload/Charlie.js",
        "Payload/Delta.ts",
        "Payload/Echo.plist",
    ]


