    apk_path = tmp_path / "sample.apk"
    nested_bytes = BytesIO()
    with zipfile.ZipFile(nested_bytes, "w") as nested_zip:
        nested_zip.writestr("assets/nested-supabase.js", "nested")
    with zipfile.ZipFile(apk_path, "w") as zf:
        zf.writestr("assets/alpha-supabase.js", "alpha")
        zf.writestr("config/bravo.json", "bravo")
        zf.writestr("scripts/charlie.ts", "charlie")
        zf.writestr("nested/client.xapk", nested_bytes.getvalue())
        zf.writestr("assets/ignore.txt", "ignore")

    text_delays = {
        "assets/alpha-supabase.js": 0.05,
        "config/bravo.json": 0.01,
        "scripts/charlie.ts": 0.03,
        "nested/client.xapk": 0.02,
        "assets/ignore.txt": 0.01,
    }
    nested_delays = {
        "assets/alpha-supabase.js": 0.05,
        "config/bravo.json": 0.01,
        "scripts/charlie.ts": 0.03,
        "nested/client.xapk": 0.04,
        "assets/ignore.txt": 0.01,
    }
    active = 0
    peak = 0
    lock = threading.Lock()
    extractor = FirebaseExtractor()
    original_text_entry = FirebaseExtractor._supabase_android_text_member_entry
    original_nested_entry = FirebaseExtractor._supabase_android_nested_bundle_entry

    def _tracking_text_entry(self, name, *, nested_prefix):  # noqa: ANN001
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(text_delays[name])
            return original_text_entry(self, name, nested_prefix=nested_prefix)
        finally:
            with lock:
                active -= 1

    def _tracking_nested_entry(self, name, *, nested_prefix):  # noqa: ANN001
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(nested_delays[name])
            return original_nested_entry(self, name, nested_prefix=nested_prefix)
        finally:
            with lock:
                active -= 1

    def _fake_extract_supabase_from_text(self, text, source_file, extract_path):  # noqa: ANN001
        del self, text
        ref = Path(extract_path).stem.lower().replace("-supabase", "")
        return [
            SupabaseConfig(ref, f"https://{ref}.supabase.co", "anon", source_file, extract_path)
        ]

    def _fake_extract_nested(self, data, apk_path_arg, *, nested_prefix, depth):  # noqa: ANN001
        del self, data, apk_path_arg, depth
        ref = Path(nested_prefix).stem.lower()
        return [
            SupabaseConfig(ref, f"https://{ref}.supabase.co", "anon", str(apk_path), nested_prefix)
        ]

    monkeypatch.setattr(
        FirebaseExtractor, "_supabase_android_text_member_entry", _tracking_text_entry
    )
    monkeypatch.setattr(
        FirebaseExtractor, "_supabase_android_nested_bundle_entry", _tracking_nested_entry
    )
    monkeypatch.setattr(
        FirebaseExtractor, "_extract_supabase_from_text", _fake_extract_supabase_from_text
    )
    monkeypatch.setattr(
        FirebaseExtractor,
        "_extract_supabase_android_bundle_configs_from_bytes",
        _fake_extract_nested,
    )

    with zipfile.ZipFile(apk_path) as zf:
        configs = extractor._extract_supabase_android_bundle_configs_from_zip(
            zf,
            apk_path,
            nested_prefix="",
            depth=0,
        )

    assert peak == 4
    assert [config.project_ref for config in configs] == ["alpha", "bravo", "charlie", "client"]
    assert [config.extract_path for config in configs] == [
        "assets/alpha-supabase.js",
        "config/bravo.json",
        "scripts/charlie.ts",
        "nested/client.xapk",
    ]


