def test_artifact_queue_processor_parallelizes_nested_member_rebase_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    source_archive = tmp_path / "bundle.zip"
    member_name = "packages/client.apk"
    payload_delays = {
        "payload-1.txt": 0.05,
        "payload-2.txt": 0.01,
        "payload-3.txt": 0.03,
        "payload-4.txt": 0.02,
        "payload-5.txt": 0.04,
    }
    project_delays = {
        "firebase-1": 0.05,
        "firebase-2": 0.01,
        "firebase-3": 0.03,
        "firebase-4": 0.02,
        "firebase-5": 0.04,
    }
    config_delays = {
        "supabase-1": 0.05,
        "supabase-2": 0.01,
        "supabase-3": 0.03,
        "supabase-4": 0.02,
        "supabase-5": 0.04,
    }
    active_payload = 0
    entered_payload = 0
    peak_payload = 0
    active_project = 0
    entered_project = 0
    peak_project = 0
    active_config = 0
    entered_config = 0
    peak_config = 0
    lock = threading.Lock()
    payload_gate = threading.Event()
    project_gate = threading.Event()
    config_gate = threading.Event()
    original_payload_entry = ArtifactQueueProcessor._rebased_mobile_member_payload_entry
    original_project_entry = ArtifactQueueProcessor._rebased_mobile_member_project_entry
    original_config_entry = ArtifactQueueProcessor._rebased_mobile_member_config_entry

    def _tracking_payload_entry(payload, *, source_path, member_name):  # noqa: ANN001
        del source_path, member_name
        nonlocal active_payload, entered_payload, peak_payload
        with lock:
            active_payload += 1
            entered_payload += 1
            peak_payload = max(peak_payload, active_payload)
            if entered_payload >= 4:
                payload_gate.set()
        try:
            payload_gate.wait(timeout=1.0)
            time.sleep(payload_delays[payload[1]])
            return original_payload_entry(
                payload, source_path=source_archive, member_name="packages/client.apk"
            )
        finally:
            with lock:
                active_payload -= 1

    def _tracking_project_entry(project, *, source_path, member_name):  # noqa: ANN001
        del source_path, member_name
        nonlocal active_project, entered_project, peak_project
        with lock:
            active_project += 1
            entered_project += 1
            peak_project = max(peak_project, active_project)
            if entered_project >= 4:
                project_gate.set()
        try:
            project_gate.wait(timeout=1.0)
            time.sleep(project_delays[project.project_id])
            return original_project_entry(
                project, source_path=source_archive, member_name="packages/client.apk"
            )
        finally:
            with lock:
                active_project -= 1

    def _tracking_config_entry(config, *, source_path, member_name):  # noqa: ANN001
        del source_path, member_name
        nonlocal active_config, entered_config, peak_config
        with lock:
            active_config += 1
            entered_config += 1
            peak_config = max(peak_config, active_config)
            if entered_config >= 4:
                config_gate.set()
        try:
            config_gate.wait(timeout=1.0)
            time.sleep(config_delays[config.project_ref])
            return original_config_entry(
                config, source_path=source_archive, member_name="packages/client.apk"
            )
        finally:
            with lock:
                active_config -= 1

    def _fake_extract_mobile_bundle_family(
        _self,
        family: str,
        *,
        path: Path,
        artifact_type: str,
    ) -> list[tuple[str, str, str]] | list[FirebaseProject] | list[SupabaseConfig]:  # noqa: ANN001
        assert path.name == "client.apk"
        assert artifact_type == "apk"
        if family == "payloads":
            return [
                (str(path), "payload-1.txt", "one"),
                (str(path), "payload-2.txt", "two"),
                (str(path), "payload-3.txt", "three"),
                (str(path), "payload-4.txt", "four"),
                (str(path), "payload-5.txt", "five"),
            ]
        if family == "firebase":
            return [
                FirebaseProject(
                    "firebase-1", None, None, None, str(path), "google-services-1.json"
                ),
                FirebaseProject(
                    "firebase-2", None, None, None, str(path), "google-services-2.json"
                ),
                FirebaseProject(
                    "firebase-3", None, None, None, str(path), "google-services-3.json"
                ),
                FirebaseProject(
                    "firebase-4", None, None, None, str(path), "google-services-4.json"
                ),
                FirebaseProject(
                    "firebase-5", None, None, None, str(path), "google-services-5.json"
                ),
            ]
        return [
            SupabaseConfig(
                "supabase-1", "https://supabase-1.supabase.co", "anon", str(path), "supabase-1.js"
            ),
            SupabaseConfig(
                "supabase-2", "https://supabase-2.supabase.co", "anon", str(path), "supabase-2.js"
            ),
            SupabaseConfig(
                "supabase-3", "https://supabase-3.supabase.co", "anon", str(path), "supabase-3.js"
            ),
            SupabaseConfig(
                "supabase-4", "https://supabase-4.supabase.co", "anon", str(path), "supabase-4.js"
            ),
            SupabaseConfig(
                "supabase-5", "https://supabase-5.supabase.co", "anon", str(path), "supabase-5.js"
            ),
        ]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_rebased_mobile_member_payload_entry",
        staticmethod(_tracking_payload_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_rebased_mobile_member_project_entry",
        staticmethod(_tracking_project_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_rebased_mobile_member_config_entry",
        staticmethod(_tracking_config_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_mobile_bundle_family",
        _fake_extract_mobile_bundle_family,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=8)
    payloads, firebase_projects, supabase_configs = (
        processor._extract_mobile_configs_from_member_bytes(
            b"apk-binary",
            source_archive,
            member_name,
        )
    )

    assert peak_payload == 4
    assert peak_project == 4
    assert peak_config == 4
    assert payloads == [
        (str(source_archive), f"{member_name}!payload-1.txt", "one"),
        (str(source_archive), f"{member_name}!payload-2.txt", "two"),
        (str(source_archive), f"{member_name}!payload-3.txt", "three"),
        (str(source_archive), f"{member_name}!payload-4.txt", "four"),
        (str(source_archive), f"{member_name}!payload-5.txt", "five"),
    ]
    assert [project.project_id for project in firebase_projects] == [
        "firebase-1",
        "firebase-2",
        "firebase-3",
        "firebase-4",
        "firebase-5",
    ]
    assert [project.extract_path for project in firebase_projects] == [
        f"{member_name}!google-services-1.json",
        f"{member_name}!google-services-2.json",
        f"{member_name}!google-services-3.json",
        f"{member_name}!google-services-4.json",
        f"{member_name}!google-services-5.json",
    ]
    assert [config.project_ref for config in supabase_configs] == [
        "supabase-1",
        "supabase-2",
        "supabase-3",
        "supabase-4",
        "supabase-5",
    ]
    assert [config.extract_path for config in supabase_configs] == [
        f"{member_name}!supabase-1.js",
        f"{member_name}!supabase-2.js",
        f"{member_name}!supabase-3.js",
        f"{member_name}!supabase-4.js",
        f"{member_name}!supabase-5.js",
    ]


