def test_artifact_queue_processor_parallelizes_generic_text_discovery_job_planning_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    discovery_jobs = [
        (str(tmp_path / "artifact-one.txt"), "one-source", "one"),
        (str(tmp_path / "artifact-blank.txt"), "blank-source", "   "),
        (str(tmp_path / "artifact-two.txt"), "two-source", "two"),
        (str(tmp_path / "artifact-empty.txt"), "empty-source", ""),
        (str(tmp_path / "artifact-three.txt"), "three-source", "three"),
        (str(tmp_path / "artifact-four.txt"), "four-source", "four"),
        (str(tmp_path / "artifact-five.txt"), "five-source", "five"),
    ]
    delays = {
        str(tmp_path / "artifact-one.txt"): 0.05,
        str(tmp_path / "artifact-blank.txt"): 0.01,
        str(tmp_path / "artifact-two.txt"): 0.03,
        str(tmp_path / "artifact-empty.txt"): 0.02,
        str(tmp_path / "artifact-three.txt"): 0.04,
        str(tmp_path / "artifact-four.txt"): 0.01,
        str(tmp_path / "artifact-five.txt"): 0.02,
    }
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    original_entry = ArtifactQueueProcessor._generic_text_discovery_job

    def _tracking_entry(discovery_job):  # noqa: ANN001
        nonlocal active, peak, entered
        source_file, _source_hint, _text = discovery_job
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[source_file])
            return original_entry(discovery_job)
        finally:
            with lock:
                active -= 1

    def _fake_collect_generic_text_discoveries(
        _self,
        text: str,
        *,
        source_file: str,
        source_hint: str = "",
    ) -> ArtifactTextDiscoveryBatch:  # noqa: ANN001
        del source_hint
        assert text.strip()
        return ArtifactTextDiscoveryBatch(
            source_file=source_file,
            emails=[f"{text}@acme.example"],
        )

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_generic_text_discovery_job",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_collect_generic_text_discoveries",
        _fake_collect_generic_text_discoveries,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=8)
    batches = processor._collect_generic_text_discovery_batches(discovery_jobs)

    assert peak == 4
    assert [batch.source_file for batch in batches] == [
        str(tmp_path / "artifact-one.txt"),
        str(tmp_path / "artifact-two.txt"),
        str(tmp_path / "artifact-three.txt"),
        str(tmp_path / "artifact-four.txt"),
        str(tmp_path / "artifact-five.txt"),
    ]
    assert [batch.emails for batch in batches] == [
        ["one@acme.example"],
        ["two@acme.example"],
        ["three@acme.example"],
        ["four@acme.example"],
        ["five@acme.example"],
    ]


