def test_artifact_ip_seed_extraction_uses_bounded_workers_and_preserves_order(
    monkeypatch,
) -> None:
    delays = {
        "198.51.100.10": 0.05,
        "203.0.113.20": 0.01,
        "192.0.2.99": 0.03,
        "2001:db8::20": 0.02,
        "fe80::1": 0.04,
    }
    active = 0
    peak = 0
    lock = threading.Lock()

    def _fake_artifact_ip_seed_entry(candidate: str) -> tuple[str, str] | None:
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays.get(candidate, 0))
            if candidate == "192.0.2.99":
                return None
            if ":" in candidate:
                return (candidate, "ipv6")
            return (candidate, "ipv4")
        finally:
            with lock:
                active -= 1

    monkeypatch.setenv("FORGE_STATIC_ARTIFACT_MAX_WORKERS", "4")
    monkeypatch.setattr(
        "forge.engagement_orchestrator._artifact_ip_seed_entry",
        _fake_artifact_ip_seed_entry,
    )

    seeds = _extract_artifact_ip_seeds(
        """
        first_host=198.51.100.10
        duplicate_host=198.51.100.10
        second_host=203.0.113.20
        placeholder_host=192.0.2.99
        <span>[2001:db8::20]</span>
        (fe80::1),
        """
    )

    assert peak == 4
    assert seeds == [
        ("198.51.100.10", "ipv4"),
        ("203.0.113.20", "ipv4"),
        ("2001:db8::20", "ipv6"),
        ("fe80::1", "ipv6"),
    ]


