def test_artifact_queue_processor_parallelizes_per_payload_structured_extractors_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    source_file = str(tmp_path / "artifact.txt")
    expected_families = list(ArtifactQueueProcessor._STRUCTURED_DISCOVERY_FAMILIES)
    delays = {
        family: 0.01 + ((index % 7) * 0.003) for index, family in enumerate(expected_families)
    }
    active = 0
    peak = 0
    lock = threading.Lock()
    seen_families: list[str] = []

    def _fake_build_structured_discovery_payload_fragment(
        _self,
        family: str,
        *,
        text: str,
        extract_path: str,
        source_file: str = "",
    ) -> str:  # noqa: ANN001
        assert text == "payload-text"
        assert extract_path == "payload.txt"
        assert source_file == str(tmp_path / "artifact.txt")
        nonlocal active, peak
        seen_families.append(family)
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[family])
            if family == "raw":
                return text
            return f"{family}:{extract_path}:{text}"
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_build_structured_discovery_payload_fragment",
        _fake_build_structured_discovery_payload_fragment,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=2)
    discovery_jobs = processor._structured_discovery_jobs_for_payload(
        (source_file, "payload.txt", "payload-text")
    )

    assert peak == 2
    assert seen_families == expected_families
    source_hint = f"{source_file}/payload.txt"
    assert discovery_jobs == [
        (source_file, source_hint, f"{family}:payload.txt:payload-text")
        for family in expected_families
        if family != "raw"
    ] + [(source_file, source_hint, "payload-text")]


def test_artifact_queue_processor_parallelizes_structured_discovery_payload_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    source_file = str(tmp_path / "payload.bin")
    active = 0
    peak = 0
    lock = threading.Lock()
    expected_families = list(ArtifactQueueProcessor._STRUCTURED_DISCOVERY_FAMILIES)
    original_entry = ArtifactQueueProcessor._structured_discovery_payload_entry

    def _tracking_entry(
        payload_batch, *, source_file: str, source_hint: str
    ):  # noqa: ANN001
        nonlocal active, peak
        payload_index, _structured_payload = payload_batch
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(0.01 + ((payload_index % 7) * 0.003))
            return original_entry(
                payload_batch,
                source_file=source_file,
                source_hint=source_hint,
            )
        finally:
            with lock:
                active -= 1

    def _fake_build_structured_discovery_payload_fragment(
        _self,
        family: str,
        *,
        text: str,
        extract_path: str,
        source_file: str = "",
    ) -> str:  # noqa: ANN001
        assert text == "payload-text"
        assert extract_path == "payload.txt"
        assert source_file == str(tmp_path / "payload.bin")
        if family == "key_value":
            return ""
        if family == "raw":
            return "payload-text"
        value = f"{family}:payload.txt:payload-text"
        return f" {value} " if family == "iac" else value

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_structured_discovery_payload_entry",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_build_structured_discovery_payload_fragment",
        _fake_build_structured_discovery_payload_fragment,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=8)
    discovery_jobs = processor._structured_discovery_jobs_for_payload(
        (source_file, "payload.txt", "payload-text")
    )

    assert peak == 4
    source_hint = f"{source_file}/payload.txt"
    assert discovery_jobs == [
        (source_file, source_hint, f"{family}:payload.txt:payload-text")
        for family in expected_families
        if family not in {"key_value", "raw"}
    ] + [(source_file, source_hint, "payload-text")]


def test_artifact_queue_processor_parallelizes_terraform_state_structured_and_text_families_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    tfstate_text = json.dumps(
        {
            "resources": [],
            "outputs": {
                "console_url": {"value": "https://tfstate.acme.example/console"},
            },
        }
    )
    source_file = str(tmp_path / "terraform.tfstate")
    active = 0
    peak = 0
    lock = threading.Lock()
    delays = {
        "structured": 0.05,
        "text": 0.01,
    }

    def _track_family(family: str) -> None:
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[family])
        finally:
            with lock:
                active -= 1

    def _fake_extract_terraform_state_structured_payloads(
        _self,
        text: str,
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        assert "tfstate.acme.example" in text
        _track_family("structured")
        return [(source_file, f"{member_name}#tfstate-structured", "structured")]

    def _fake_extract_terraform_state_text_payloads(
        _self,
        text: str,
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        assert "tfstate.acme.example" in text
        _track_family("text")
        return [(source_file, member_name, "raw-text")]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_terraform_state_structured_payloads",
        _fake_extract_terraform_state_structured_payloads,
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_terraform_state_text_payloads",
        _fake_extract_terraform_state_text_payloads,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=2)
    payloads = processor._extract_terraform_state_bytes_payloads(
        tfstate_text.encode("utf-8"),
        source_file,
        "terraform.tfstate",
    )

    assert peak == 2
    assert payloads == [
        (source_file, "terraform.tfstate#tfstate-structured", "structured"),
        (source_file, "terraform.tfstate", "raw-text"),
    ]


