    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    seen_families: list[list[str]] = []
    delays = {
        0: 0.05,
        1: 0.01,
        2: 0.03,
        3: 0.02,
    }
    original_entry = ArtifactQueueProcessor._key_value_structured_candidate_family_entries

    def _tracking_entry(candidate_family):  # noqa: ANN001
        nonlocal active, peak, entered
        family_index, _family = candidate_family
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[family_index])
            result = original_entry(candidate_family)
            seen_families.append(list(result))
            return result
        finally:
            with lock:
                active -= 1

    def _fake_key_value_structured_candidate_batch(
        _self,
        job,
    ) -> list[str]:  # noqa: ANN001
        family, section_path, mapping = job
        assert isinstance(mapping, dict)
        label = "env" if family == "env" else section_path[0]
        return [f"{label}-candidate"]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_key_value_structured_candidate_family_entries",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_key_value_structured_candidate_batch",
        _fake_key_value_structured_candidate_batch,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=4)
    payload = processor._key_value_structured_payload_text(
        dedent(
            """
            contact_email = "ops@acme.example"

            [firebase]
            project_id = "alpha"

            [supabase]
            project_ref = "beta"
            portal_url = "https://portal.acme.example"
            """
        ).strip(),
        source_hint="config.ini",
    )

    assert peak == 4
    assert payload.splitlines() == [
        "env-candidate",
        "firebase-candidate",
        "supabase-candidate",
        "ops@acme.example",
        "https://portal.acme.example",
    ], {"lines": payload.splitlines(), "families": seen_families}


