def test_artifact_queue_processor_parallelizes_yaml_env_list_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    active = 0
    peak = 0
    lock = threading.Lock()
    delays = {
        "ALPHA": 0.05,
        "BETA-VALUE": 0.01,
        "ALPHA-OVERRIDE": 0.03,
    }

    def _fake_yaml_env_entry(
        _self,
        item: Any,
    ) -> list[tuple[str, str]]:
        if isinstance(item, str):
            label = "ALPHA"
            result = [("ALPHA", "one")]
        elif isinstance(item, dict) and "name" in item:
            label = "BETA-VALUE"
            result = [("BETA-VALUE", "two")]
        else:
            label = "ALPHA-OVERRIDE"
            result = [("ALPHA", "three")]
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[label])
            return result
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_yaml_env_entry",
        _fake_yaml_env_entry,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=4)
    env_map = processor._yaml_env_map(
        [
            "alpha=one",
            {"name": "beta-value", "value": "two"},
            {"alpha": "three"},
        ]
    )

    assert peak == 3
    assert env_map == {
        "ALPHA": "three",
        "BETA-VALUE": "two",
        "BETA_VALUE": "two",
    }


