    con = sqlite3.connect(f"file:{sqlite_path.as_posix()}?mode=ro", uri=True)
    try:
        payloads = processor._extract_sqlite_object_payloads_from_connection(
            con,
            source_file=str(sqlite_path),
            member_name=sqlite_path.name,
            object_name="credentials",
            object_sql="CREATE TABLE credentials (email TEXT, token TEXT)",
        )
    finally:
        con.close()

    assert peak == 3
    assert payloads == [
        (str(sqlite_path), f"{sqlite_path.name}#sqlite-schema-credentials", "schema"),
        (str(sqlite_path), f"{sqlite_path.name}#sqlite-columns-credentials", "columns"),
        (str(sqlite_path), f"{sqlite_path.name}#sqlite-row-credentials-1", "row"),
    ]


