def test_calendar_contact_parser_unfolds_folded_ics_lines(tmp_path: Path) -> None:
    db_path = tmp_path / "engagement.db"
    processor = ArtifactQueueProcessor(db_path, 1001)
    payload = (
        "BEGIN:VCALENDAR\r\n"
        "VERSION:2.0\r\n"
        "BEGIN:VEVENT\r\n"
        "SUMMARY:Acme review\r\n"
        "ORGANIZER;CN=Acme Ops:mailto:calendar-owner@acme.example\r\n"
        "ATTENDEE;CN=Analyst:mailto:analyst@acme.example\r\n"
        "URL:https://calendar.acme.example/reports/\r\n"
        " continuation\r\n"
        "END:VEVENT\r\n"
        "END:VCALENDAR\r\n"
    ).encode()

    payloads = processor._extract_calendar_contact_bytes_payloads(
        payload,
        "calendar.ics",
        "calendar.ics",
    )
    payload_by_member = {member_name: text for _, member_name, text in payloads}

    summary = payload_by_member["calendar.ics#calendar-contact-summary"]
    raw = payload_by_member["calendar.ics"]
    assert "organizer=calendar-owner@acme.example" in summary
    assert "attendee=analyst@acme.example" in summary
    assert "url=https://calendar.acme.example/reports/continuation" in summary
    assert "https://calendar.acme.example/reports/continuation" in raw
    assert "\r\n continuation" not in raw


