def test_artifact_queue_processor_extracts_folded_calendar_contact_seed_pivots(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    _bootstrap_engagement(db_path)
    artifact_root = tmp_path / "artifacts"
    artifact_root.mkdir()
    (artifact_root / "review.ics").write_text(
        dedent(
            """
            BEGIN:VCALENDAR
            VERSION:2.0
            BEGIN:VEVENT
            ORGANIZER;CN=Acme Ops:mailto:calendar-owner@acme.example
            URL:https://calendar.acme.example/reports/
             continuation
            END:VEVENT
            END:VCALENDAR
            """
        ).strip(),
        encoding="utf-8",
    )
    (artifact_root / "team.vcard").write_text(
        dedent(
            """
            BEGIN:VCARD
            VERSION:4.0
            FN:Acme Response
            EMAIL;TYPE=work:vcard-owner@acme.example
            URL:https://vcard.acme.example/profile/
             continued
            END:VCARD
            """
        ).strip(),
        encoding="utf-8",
    )

    processor = ArtifactQueueProcessor(db_path, 1001)
    queued = processor.ingest_local_artifacts([artifact_root])
    summary = processor.process()

    assert queued == 2
    assert summary.processed == 2
    assert summary.discovered_seeds >= 4

    con = sqlite3.connect(db_path)
    try:
        emails = {
            row[0]
            for row in con.execute("SELECT email FROM emails WHERE engagement_id=1001").fetchall()
        }
        seeds = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
    finally:
        con.close()

    assert "calendar-owner@acme.example" in emails
    assert "vcard-owner@acme.example" in emails
    assert ("calendar-owner@acme.example", "email") in seeds
    assert ("vcard-owner@acme.example", "email") in seeds
    assert ("https://calendar.acme.example/reports/continuation", "url") in seeds
    assert ("https://vcard.acme.example/profile/continued", "url") in seeds


def test_artifact_queue_processor_parallelizes_ole_metadata_lines_and_preserves_order(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    delays = {
        "title": 0.05,
        "subject": 0.01,
        "author": 0.03,
        "last_saved_by": 0.02,
        "comments": 0.04,
        "keywords": 0.01,
        "company": 0.03,
        "manager": 0.02,
    }
    values = {
        "title": "Parallel dossier",
        "subject": "Internal review",
        "author": "Analyst",
        "last_saved_by": "Operator",
        "comments": "Reviewed",
        "keywords": "acme,security",
        "company": "Acme",
        "manager": "Director",
    }
    active = 0
    peak = 0
    lock = threading.Lock()

    class _FakeMetadata:
        def __getattribute__(self, key: str):  # noqa: ANN001
            if key in values:
                nonlocal active, peak
                with lock:
                    active += 1
                    peak = max(peak, active)
                try:
                    time.sleep(delays[key])
                    return values[key]
                finally:
                    with lock:
                        active -= 1
            return super().__getattribute__(key)

    class _FakeOle:
        def get_metadata(self) -> _FakeMetadata:
            return _FakeMetadata()

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=8)
    lines = processor._ole_metadata_lines(_FakeOle())

    assert peak == 4
    assert lines == [
        "title=Parallel dossier",
        "subject=Internal review",
        "author=Analyst",
        "last_saved_by=Operator",
        "comments=Reviewed",
        "keywords=acme,security",
        "company=Acme",
        "manager=Director",
    ]


