def test_artifact_queue_processor_parallelizes_binary_string_value_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {
        0: 0.05,
        1: 0.01,
        2: 0.03,
        3: 0.02,
        4: 0.04,
    }
    original_entry = ArtifactQueueProcessor._binary_string_value_entry

    def _tracking_entry(candidate_entry):  # noqa: ANN001
        nonlocal active, peak, entered
        candidate_index, _candidate = candidate_entry
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[candidate_index])
            return original_entry(candidate_entry)
        finally:
            with lock:
                active -= 1

    def _fake_binary_string_ascii_candidates(
        _self,
        data: bytes,
    ) -> list[str]:  # noqa: ANN001
        assert data == b"parallel-binary-value-entries"
        return ["owner@acme.example", "https://portal.acme.example", "support@acme.example"]

    def _fake_binary_string_utf16_candidates(
        _self,
        data: bytes,
    ) -> list[str]:  # noqa: ANN001
        assert data == b"parallel-binary-value-entries"
        return ["https://portal.acme.example", "support@acme.example"]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_binary_string_value_entry",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_binary_string_ascii_candidates",
        _fake_binary_string_ascii_candidates,
    )
