def test_artifact_queue_processor_parallelizes_har_summary_page_line_batch_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {
        0: 0.05,
        1: 0.01,
        2: 0.03,
        3: 0.02,
    }
    original_entry = ArtifactQueueProcessor._ordered_line_batch_entries

    def _tracking_entry(line_batch):  # noqa: ANN001
        nonlocal active, peak, entered
        batch_index, _batch = line_batch
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[batch_index])
            return original_entry(line_batch)
        finally:
            with lock:
                active -= 1

    def _fake_har_summary_page_line_batch(
        _self,
        page_job,
    ) -> list[str]:  # noqa: ANN001
        page_index, page = page_job
        assert page["id"] == f"page-{page_index}"
        return ["", f"page[{page_index}]={page['id']}"]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_ordered_line_batch_entries",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_har_summary_page_line_batch",
        _fake_har_summary_page_line_batch,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=4)
    lines = processor._har_summary_page_lines(
        {
            "pages": [
                {"id": "page-1"},
                {"id": "page-2"},
                {"id": "page-3"},
                {"id": "page-4"},
            ],
        }
    )

    assert peak == 4
    assert lines == [
        "pages=4",
        "page[1]=page-1",
        "page[2]=page-2",
        "page[3]=page-3",
        "page[4]=page-4",
    ]


