def test_artifact_queue_processor_parallelizes_ole_payload_family_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    source_file = str(tmp_path / "parallel-family-entries.doc")
    stream_order = [("StreamOne",), ("StreamTwo",)]
    stream_payloads = {("StreamOne",): b"one", ("StreamTwo",): b"two"}
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {0: 0.05, 1: 0.01}
    original_entry = ArtifactQueueProcessor._artifact_payload_tuple_batch_entries

    class _FakeOleMetadata:
        subject = "Parallel OLE"

    class _FakeOleFamilyEntryFile:
        def __init__(self, fileobj) -> None:  # noqa: ANN001
            del fileobj

        def __enter__(self) -> "_FakeOleFamilyEntryFile":
            return self

        def __exit__(self, exc_type, exc, tb) -> None:  # noqa: ANN001
            del exc_type, exc, tb

        def get_metadata(self) -> _FakeOleMetadata:
            return _FakeOleMetadata()

        def listdir(self, streams: bool = True, storages: bool = False) -> list[tuple[str, ...]]:
            del streams, storages
            return list(stream_order)

        def openstream(self, stream_parts: tuple[str, ...]) -> BytesIO:
            return BytesIO(stream_payloads[tuple(stream_parts)])

    def _tracking_entry(payload_batch):  # noqa: ANN001
        nonlocal active, peak, entered
        batch_index, _batch = payload_batch
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 2:
                gate.set()
        try:
            if current_entered <= 2:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[batch_index])
            return original_entry(payload_batch)
        finally:
            with lock:
                active -= 1

    def _fake_extract_ole_metadata_payloads(
        _self,
        metadata_lines,
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        assert list(metadata_lines) == ["subject=Parallel OLE"]
        return [
            (source_file, f"{member_name}#ole-metadata", "summary"),
            ("", "ignored", "ignored"),
        ]

    def _fake_extract_ole_stream_job_payloads(
        _self,
        stream_jobs,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        assert [job.stream_name for job in stream_jobs] == ["StreamOne", "StreamTwo"]
        return [
            (source_file, "parallel-family-entries.doc#ole-stream:StreamOne", "one"),
            (source_file, "parallel-family-entries.doc#ole-stream:StreamTwo", "two"),
            (source_file, "parallel-family-entries.doc#ole-stream-empty", ""),
        ]

    monkeypatch.setitem(
        sys.modules,
        "olefile",
        types.SimpleNamespace(OleFileIO=_FakeOleFamilyEntryFile),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_artifact_payload_tuple_batch_entries",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_ole_metadata_payloads",
        _fake_extract_ole_metadata_payloads,
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_ole_stream_job_payloads",
        _fake_extract_ole_stream_job_payloads,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=4)
    payloads = processor._extract_ole_payloads(
        b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1parallel-ole-family-entries",
        source_file,
        "parallel-family-entries.doc",
        depth=0,
    )

    assert peak == 2
    assert payloads == [
        (source_file, "parallel-family-entries.doc#ole-metadata", "summary"),
        (source_file, "parallel-family-entries.doc#ole-stream:StreamOne", "one"),
        (source_file, "parallel-family-entries.doc#ole-stream:StreamTwo", "two"),
    ]


