def test_artifact_queue_processor_parallelizes_xml_member_payload_family_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    source_file = str(tmp_path / "document-family-entries.xml")
    xml_bytes = (
        b"<document><title>Executive Brief</title><owner>xml-owner@acme.example</owner></document>"
    )
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {0: 0.05, 1: 0.01}
    original_entry = ArtifactQueueProcessor._artifact_payload_tuple_batch_entries

    def _tracking_entry(payload_batch):  # noqa: ANN001
        nonlocal active, peak, entered
        batch_index, _batch = payload_batch
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 2:
                gate.set()
        try:
            if current_entered <= 2:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[batch_index])
            return original_entry(payload_batch)
        finally:
            with lock:
                active -= 1

    def _fake_extract_member_payload_family(
        _self,
        family: str,
        *,
        source_file: str,
        member_name: str,
        lowered: str,
        text: str,
    ) -> list[tuple[str, str, str]]:
        assert lowered == "docprops/core.xml"
        assert "Executive Brief" in text
        if family == "text":
            return [
                (source_file, member_name, "xml-text"),
                ("", "ignored", "ignored"),
            ]
        if family == "meta":
            return [
                (source_file, f"{member_name}#meta", "xml-meta"),
                (source_file, f"{member_name}#empty", ""),
            ]
        return []

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_artifact_payload_tuple_batch_entries",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_member_payload_family",
        _fake_extract_member_payload_family,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=4)
    payloads = processor._member_payloads(
        source_file,
        "docProps/core.xml",
        xml_bytes,
    )

    assert peak == 2
    assert payloads == [
        (source_file, "docProps/core.xml", "xml-text"),
        (source_file, "docProps/core.xml#meta", "xml-meta"),
    ]


