def test_artifact_queue_processor_parallelizes_msg_property_stream_processing_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    msg_path = tmp_path / "parallel.msg"
    msg_path.write_bytes(b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1parallel-msg")
    stream_order = [
        ("__substg1.0_0037001F",),
        ("__substg1.0_1000001F",),
        ("__substg1.0_10130102",),
    ]
    stream_payloads = {
        ("__substg1.0_0037001F",): b"subject",
        ("__substg1.0_1000001F",): b"body",
        ("__substg1.0_10130102",): b"html",
    }
    delays = {
        "0037": 0.05,
        "1000": 0.01,
        "1013": 0.03,
    }
    active = 0
    peak = 0
    lock = threading.Lock()

    class _FakeMsgOlePropertyFile:
        def __enter__(self) -> "_FakeMsgOlePropertyFile":
            return self

        def __exit__(self, exc_type, exc, tb) -> None:  # noqa: ANN001
            del exc_type, exc, tb

        def get_metadata(self):  # noqa: ANN201
            class _EmptyMetadata:
                pass

            return _EmptyMetadata()

        def listdir(self, streams: bool = True, storages: bool = False) -> list[tuple[str, ...]]:
            del streams, storages
            return list(stream_order)

        def openstream(self, stream_parts: tuple[str, ...]) -> BytesIO:
            return BytesIO(stream_payloads[tuple(stream_parts)])

    def _fake_extract_msg_ole_property_job(
        _self,
        job,
    ):  # noqa: ANN001, ANN201
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[job.prop_id])
            if job.prop_id == "0037":
                return types.SimpleNamespace(
                    payloads=[],
                    summary_lines=["subject=Parallel MSG"],
                    attachment_storage="",
                    attachment_updates=[],
                )
            if job.prop_id == "1000":
                return types.SimpleNamespace(
                    payloads=[(job.source_file, f"{job.member_name}#msg-body.txt", "body-payload")],
                    summary_lines=[],
                    attachment_storage="",
                    attachment_updates=[],
                )
            return types.SimpleNamespace(
                payloads=[
                    (job.source_file, f"{job.member_name}#msg-html_body.html", "html-payload")
                ],
                summary_lines=[],
                attachment_storage="",
                attachment_updates=[],
            )
        finally:
            with lock:
                active -= 1

    monkeypatch.setitem(
        sys.modules,
        "olefile",
        types.SimpleNamespace(OleFileIO=lambda _handle: _FakeMsgOlePropertyFile()),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_msg_ole_property_job",
        _fake_extract_msg_ole_property_job,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=2)
    payloads = processor._extract_msg_payloads(msg_path, depth=0)

    assert peak == 2
    assert payloads == [
        (str(msg_path), "parallel.msg#msg-meta", "subject=Parallel MSG"),
        (str(msg_path), "parallel.msg#msg-body.txt", "body-payload"),
        (str(msg_path), "parallel.msg#msg-html_body.html", "html-payload"),
    ]


def test_artifact_queue_processor_parallelizes_msg_property_job_planning_and_preserves_order(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    source_file = str(tmp_path / "parallel-property-jobs.msg")
    member_name = "parallel-property-jobs.msg"
    stream_order = [
        ("__substg1.0_0037001F",),
        ("__substg1.0_1000001F",),
        ("__attach_version1.0_#00000000", "__substg1.0_37010102"),
        ("__substg1.0_10130102",),
        ("__substg1.0_0C1F001F",),
    ]
    stream_payloads = {
        ("__substg1.0_0037001F",): b"subject",
        ("__substg1.0_1000001F",): b"body",
        ("__attach_version1.0_#00000000", "__substg1.0_37010102"): b"attachment-bytes",
        ("__substg1.0_10130102",): b"html",
        ("__substg1.0_0C1F001F",): b"sender",
    }
    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=8)
    seen_jobs: list[tuple[str, str, str, bytes]] = []

    class _FakeMsgOlePlanningFile:
        def __enter__(self) -> "_FakeMsgOlePlanningFile":
            return self

        def __exit__(self, exc_type, exc, tb) -> None:  # noqa: ANN001
            del exc_type, exc, tb

        def get_metadata(self):  # noqa: ANN201
            class _EmptyMetadata:
                pass

            return _EmptyMetadata()

        def listdir(self, streams: bool = True, storages: bool = False) -> list[tuple[str, ...]]:
            del streams, storages
            return list(stream_order)

        def openstream(self, stream_parts: tuple[str, ...]) -> BytesIO:
            return BytesIO(stream_payloads[tuple(stream_parts)])

    def _fake_extract_msg_ole_property_job(
        _self,
        job,
    ):  # noqa: ANN001, ANN201
        seen_jobs.append((job.prop_id, job.label, job.attachment_storage, job.stream_data))
        if job.prop_id == "0037":
            assert job.label == "subject"
            assert job.attachment_storage == ""
            return types.SimpleNamespace(
                payloads=[],
                summary_lines=["subject=Parallel MSG"],
                attachment_storage="",
                attachment_updates=[],
            )
        if job.prop_id == "1000":
            assert job.label == "body"
            return types.SimpleNamespace(
                payloads=[(job.source_file, f"{job.member_name}#msg-body.txt", "body-payload")],
                summary_lines=[],
                attachment_storage="",
                attachment_updates=[],
            )
        if job.prop_id == "3701":
            assert job.label == "prop_3701"
            assert job.attachment_storage == "__attach_version1.0_#00000000"
            return types.SimpleNamespace(
                payloads=[],
                summary_lines=[],
                attachment_storage=job.attachment_storage,
                attachment_updates=[("data", job.stream_data)],
            )
        if job.prop_id == "1013":
            assert job.label == "html_body"
            return types.SimpleNamespace(
                payloads=[
                    (job.source_file, f"{job.member_name}#msg-html_body.html", "html-payload")
                ],
                summary_lines=[],
                attachment_storage="",
                attachment_updates=[],
            )
        assert job.prop_id == "0C1F"
        assert job.label == "sender_email"
        return types.SimpleNamespace(
            payloads=[],
            summary_lines=["sender-email=sender@acme.example"],
            attachment_storage="",
            attachment_updates=[],
        )

    processor._extract_msg_ole_property_job = types.MethodType(
        _fake_extract_msg_ole_property_job,
        processor,
    )

    payloads = processor._extract_msg_ole_payloads(
        _FakeMsgOlePlanningFile(),
        source_file,
        member_name,
        depth=0,
    )

    assert seen_jobs == [
        ("0037", "subject", "", b"subject"),
        ("1000", "body", "", b"body"),
        ("3701", "prop_3701", "__attach_version1.0_#00000000", b"attachment-bytes"),
        ("1013", "html_body", "", b"html"),
        ("0C1F", "sender_email", "", b"sender"),
    ]
    assert payloads == [
        (
            source_file,
            "parallel-property-jobs.msg#msg-meta",
            "subject=Parallel MSG\nsender-email=sender@acme.example",
        ),
        (source_file, "parallel-property-jobs.msg#msg-body.txt", "body-payload"),
        (source_file, "parallel-property-jobs.msg#msg-html_body.html", "html-payload"),
    ]


