    stream_order = [
        ("__attach_version1.0_#00000000", "__substg1.0_3707001F"),
        ("__attach_version1.0_#00000000", "__substg1.0_37010102"),
        ("__attach_version1.0_#00000001", "__substg1.0_3707001F"),
        ("__attach_version1.0_#00000001", "__substg1.0_37010102"),
    ]
    stream_payloads = {
        ("__attach_version1.0_#00000000", "__substg1.0_3707001F"): _msg_utf16("alpha.bin"),
        ("__attach_version1.0_#00000000", "__substg1.0_37010102"): b"alpha-bytes",
        ("__attach_version1.0_#00000001", "__substg1.0_3707001F"): _msg_utf16("beta.bin"),
        ("__attach_version1.0_#00000001", "__substg1.0_37010102"): b"beta-bytes",
    }
    delays = {
        "alpha.bin": 0.05,
        "beta.bin": 0.01,
    }
    active = 0
    peak = 0
    lock = threading.Lock()

    class _FakeMsgOleAttachmentFile:
        def __enter__(self) -> "_FakeMsgOleAttachmentFile":
            return self

        def __exit__(self, exc_type, exc, tb) -> None:  # noqa: ANN001
            del exc_type, exc, tb

        def get_metadata(self):  # noqa: ANN201
            class _EmptyMetadata:
                pass

            return _EmptyMetadata()

        def listdir(self, streams: bool = True, storages: bool = False) -> list[tuple[str, ...]]:
            del streams, storages
            return list(stream_order)

        def openstream(self, stream_parts: tuple[str, ...]) -> BytesIO:
            return BytesIO(stream_payloads[tuple(stream_parts)])

    def _fake_extract_msg_attachment_payloads(
        _self,
        job,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[job.attachment_name])
            return [
                (
                    job.source_file,
                    f"{job.member_name}/{job.attachment_name}",
                    f"{job.attachment_name}-payload",
                )
            ]
        finally:
            with lock:
                active -= 1

