def test_artifact_queue_processor_parallelizes_msg_attachment_job_builds_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    msg_path = tmp_path / "parallel-attachment-jobs.msg"
    msg_path.write_bytes(b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1fake-msg-jobs")
    stream_order = [
        ("__attach_version1.0_#00000000", "__substg1.0_37010102"),
        ("__attach_version1.0_#00000000", "__substg1.0_3704001F"),
        ("__attach_version1.0_#00000001", "__substg1.0_37010102"),
        ("__attach_version1.0_#00000001", "__substg1.0_3704001F"),
    ]
    stream_payloads = {
        ("__attach_version1.0_#00000000", "__substg1.0_37010102"): b"alpha-bytes",
        ("__attach_version1.0_#00000000", "__substg1.0_3704001F"): "alpha.bin".encode("utf-16-le"),
        ("__attach_version1.0_#00000001", "__substg1.0_37010102"): b"beta-bytes",
        ("__attach_version1.0_#00000001", "__substg1.0_3704001F"): "beta.bin".encode("utf-16-le"),
    }
    delays = {
        1: 0.05,
        2: 0.01,
    }
    active = 0
    peak = 0
    lock = threading.Lock()

    class _EmptyMetadata:
        pass

    class _FakeMsgAttachmentJobOle:
        def __enter__(self) -> "_FakeMsgAttachmentJobOle":
            return self

        def __exit__(self, exc_type, exc, tb) -> None:  # noqa: ANN001
            del exc_type, exc, tb

        def get_metadata(self) -> _EmptyMetadata:
            return _EmptyMetadata()

        def listdir(self, streams: bool = True, storages: bool = False) -> list[tuple[str, ...]]:
            del streams, storages
            return list(stream_order)

        def openstream(self, stream_parts: tuple[str, ...]) -> BytesIO:
            return BytesIO(stream_payloads[tuple(stream_parts)])

    def _fake_build_msg_attachment_job(
        _self,
        attachment_job,
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ):  # noqa: ANN001
        index, attachment = attachment_job
        assert source_file == str(msg_path)
        assert member_name == msg_path.name
        assert depth == 0
        assert attachment["attachment_filename"] in {"alpha.bin", "beta.bin"}
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[index])
            return MsgAttachmentExtractionJob(
                source_file=source_file,
                member_name=member_name,
                attachment_name=str(attachment["attachment_filename"]),
                attachment_data=bytes(attachment["data"]),
                depth=depth + 1,
            )
        finally:
            with lock:
                active -= 1

    def _fake_extract_msg_attachment_job_payloads(
        _self,
        attachment_jobs,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        assert [job.attachment_name for job in attachment_jobs] == ["alpha.bin", "beta.bin"]
        return []

    monkeypatch.setitem(
        sys.modules,
        "olefile",
        types.SimpleNamespace(OleFileIO=lambda _handle: _FakeMsgAttachmentJobOle()),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_build_msg_attachment_job",
        _fake_build_msg_attachment_job,
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_msg_attachment_job_payloads",
        _fake_extract_msg_attachment_job_payloads,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=2)
    processor._extract_msg_payloads(msg_path, depth=0)

    assert peak == 2


