def test_artifact_queue_processor_parallelizes_pdf_ocr_pages_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    pdf_path = tmp_path / "scanned-briefing.pdf"
    pdf_path.write_bytes(b"%PDF-1.4\nscanned pdf placeholder\n%%EOF\n")

    rendered_pages = [
        tmp_path / "rendered-page-1.png",
        tmp_path / "rendered-page-2.png",
        tmp_path / "rendered-page-3.png",
    ]
    for page in rendered_pages:
        page.write_bytes(b"\x89PNG\r\n\x1a\nrendered-page")

    def _fake_render_pdf(_self, path: Path) -> list[Path]:  # noqa: ANN001
        assert path == pdf_path
        return list(rendered_pages)

    delays = {
        rendered_pages[0].name: 0.05,
        rendered_pages[1].name: 0.01,
        rendered_pages[2].name: 0.03,
    }
    ocr_texts = {
        rendered_pages[0].name: "page-one@acme.example",
        rendered_pages[1].name: "page-two@acme.example",
        rendered_pages[2].name: "page-three@acme.example",
    }
    active = 0
    peak = 0
    lock = threading.Lock()

    def _fake_ocr_path(_self, path: Path) -> str:  # noqa: ANN001
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[path.name])
            return ocr_texts[path.name]
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(ArtifactQueueProcessor, "_render_pdf_pages_for_ocr", _fake_render_pdf)
    monkeypatch.setattr(ArtifactQueueProcessor, "_ocr_image_path", _fake_ocr_path)

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=2)
    processor._ocr_binary = "tesseract"
    processor._pdf_raster_binary = "pdftoppm"

    payloads = processor._extract_pdf_ocr_payloads(pdf_path)

    assert peak == 2
    assert payloads == [
        (str(pdf_path), f"{pdf_path.name}#ocr-page-1", "page-one@acme.example"),
        (str(pdf_path), f"{pdf_path.name}#ocr-page-2", "page-two@acme.example"),
        (str(pdf_path), f"{pdf_path.name}#ocr-page-3", "page-three@acme.example"),
    ]
    for page in rendered_pages:
        assert not page.exists()


def test_artifact_queue_processor_routes_pdf_ocr_page_payloads_through_ordered_worker_pool(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    pdf_path = tmp_path / "scanned-worker-pool-briefing.pdf"
    pdf_path.write_bytes(b"%PDF-1.4\nscanned pdf worker-pool placeholder\n%%EOF\n")

    rendered_pages = [
        tmp_path / "worker-pool-page-1.png",
        tmp_path / "worker-pool-page-2.png",
        tmp_path / "worker-pool-page-3.png",
    ]
    for page in rendered_pages:
        page.write_bytes(b"\x89PNG\r\n\x1a\nrendered-page")

    def _fake_render_pdf(_self, path: Path) -> list[Path]:  # noqa: ANN001
        assert path == pdf_path
        return list(rendered_pages)

    def _fake_ocr_path(_self, path: Path) -> str:  # noqa: ANN001
        return f"{path.stem}@acme.example"

    original_batch = ArtifactQueueProcessor._run_ordered_local_batch
    observed_page_payload_batch = False

    def _tracking_batch(self, items, worker, *, default_factory):  # noqa: ANN001
        nonlocal observed_page_payload_batch
        materialized = list(items)
        if (
            materialized == list(enumerate(rendered_pages, start=1))
            and getattr(worker, "__name__", "") != "_pdf_ocr_page_job"
        ):
            observed_page_payload_batch = True
        return original_batch(self, materialized, worker, default_factory=default_factory)

    monkeypatch.setattr(ArtifactQueueProcessor, "_render_pdf_pages_for_ocr", _fake_render_pdf)
    monkeypatch.setattr(ArtifactQueueProcessor, "_ocr_image_path", _fake_ocr_path)
    monkeypatch.setattr(ArtifactQueueProcessor, "_run_ordered_local_batch", _tracking_batch)

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=2)
    processor._ocr_binary = "tesseract"
    processor._pdf_raster_binary = "pdftoppm"

    payloads = processor._extract_pdf_ocr_payloads(pdf_path)

    assert observed_page_payload_batch
    assert payloads == [
        (str(pdf_path), f"{pdf_path.name}#ocr-page-1", "worker-pool-page-1@acme.example"),
        (str(pdf_path), f"{pdf_path.name}#ocr-page-2", "worker-pool-page-2@acme.example"),
        (str(pdf_path), f"{pdf_path.name}#ocr-page-3", "worker-pool-page-3@acme.example"),
    ]
    for page in rendered_pages:
        assert not page.exists()


def test_artifact_queue_processor_parallelizes_pdf_ocr_page_payload_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    pdf_path = tmp_path / "scanned-entry-briefing.pdf"
