def test_artifact_queue_processor_parallelizes_pdf_ocr_page_retention_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    pdf_path = tmp_path / "scanned-retention-briefing.pdf"
    pdf_path.write_bytes(b"%PDF-1.4\nscanned pdf retention placeholder\n%%EOF\n")

    rendered_pages = [
        tmp_path / "page-1.png",
        tmp_path / "page-2.png",
        tmp_path / "page-3.png",
    ]
    rendered_payloads = {
        rendered_pages[0].name: b"rendered-page-one",
        rendered_pages[1].name: b"rendered-page-two",
        rendered_pages[2].name: b"rendered-page-three",
    }
    delays = {
        rendered_pages[0].name: 0.05,
        rendered_pages[1].name: 0.01,
        rendered_pages[2].name: 0.03,
    }
    active = 0
    peak = 0
    lock = threading.Lock()
    original_entry = ArtifactQueueProcessor._retained_pdf_ocr_image_path

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        assert argv[0] == "pdftoppm"
        assert argv[-2] == str(pdf_path)
        output_prefix = Path(argv[-1])
        for page in rendered_pages:
            rendered_path = output_prefix.parent / page.name
            rendered_path.write_bytes(rendered_payloads[page.name])
        return subprocess.CompletedProcess(argv, 0, stdout="", stderr="")

    def _tracking_entry(image_path):  # noqa: ANN001
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[Path(image_path).name])
            return original_entry(image_path)
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_retained_pdf_ocr_image_path",
        staticmethod(_tracking_entry),
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=8)
    processor._pdf_raster_binary = "pdftoppm"

    retained_pages = processor._render_pdf_pages_for_ocr(pdf_path)

    assert peak == 3
    assert len(retained_pages) == 3
    assert [page.suffix for page in retained_pages] == [".png", ".png", ".png"]
    assert [page.read_bytes() for page in retained_pages] == [
        rendered_payloads[rendered_pages[0].name],
        rendered_payloads[rendered_pages[1].name],
        rendered_payloads[rendered_pages[2].name],
    ]
    for page in retained_pages:
        page.unlink(missing_ok=True)


