def test_artifact_queue_processor_parallelizes_embedded_archive_carving_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    payload_bytes = b"legacy-prefix" + b"archive-markers"
    offsets = [("zip", 11), ("gz", 23), ("xz", 37)]
    delays = {
        11: 0.05,
        23: 0.01,
        37: 0.03,
    }
    active = 0
    peak = 0
    lock = threading.Lock()

    def _fake_embedded_archive_offsets(_data: bytes) -> list[tuple[str, int]]:  # noqa: ANN001
        return list(offsets)

    def _fake_extract_embedded_archive_job(
        _self,
        job,
    ) -> list[tuple[str, str, str]]:  # noqa: ANN001
        nonlocal active, peak
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[job.offset])
            return [
                (
                    job.source_file,
                    f"{job.member_name}#carved-{job.archive_kind}-{job.offset}",
                    f"{job.archive_kind}-{job.offset}-payload",
                )
            ]
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_embedded_archive_offsets",
        staticmethod(_fake_embedded_archive_offsets),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_embedded_archive_job",
        _fake_extract_embedded_archive_job,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=2)
    payloads = processor._extract_embedded_archive_payloads(
        payload_bytes,
        str(tmp_path / "embedded.doc"),
        "embedded.doc",
        depth=0,
    )

    assert peak == 2
    assert payloads == [
        (str(tmp_path / "embedded.doc"), "embedded.doc#carved-zip-11", "zip-11-payload"),
        (str(tmp_path / "embedded.doc"), "embedded.doc#carved-gz-23", "gz-23-payload"),
        (str(tmp_path / "embedded.doc"), "embedded.doc#carved-xz-37", "xz-37-payload"),
    ]


def test_artifact_queue_processor_parallelizes_embedded_archive_payload_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    source_file = str(tmp_path / "embedded-payload-entries.doc")
    member_name = "embedded-payload-entries.doc"
    payload_bytes = b"legacy-prefix" + b"archive-markers"
    offsets = [("zip", 11), ("gz", 23), ("xz", 37)]
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {0: 0.05, 1: 0.01, 2: 0.03}
    original_entry = ArtifactQueueProcessor._artifact_payload_tuple_batch_entries

    def _tracking_entry(payload_batch):  # noqa: ANN001
        nonlocal active, peak, entered
        batch_index, _batch = payload_batch
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 3:
                gate.set()
        try:
            if current_entered <= 3:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[batch_index])
            return original_entry(payload_batch)
        finally:
            with lock:
                active -= 1

    def _fake_embedded_archive_offsets(_data: bytes) -> list[tuple[str, int]]:  # noqa: ANN001
        return list(offsets)

    def _fake_extract_embedded_archive_job(
        _self,
        job: EmbeddedArchiveExtractionJob,
    ) -> list[tuple[str, str, str]]:
        return [
            (
                job.source_file,
                f"{job.member_name}#carved-{job.archive_kind}-{job.offset}",
                f"{job.archive_kind}-{job.offset}-payload",
            ),
            (job.source_file, f"{job.member_name}#carved-empty-{job.offset}", ""),
            ("", "ignored", "ignored"),
        ]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_artifact_payload_tuple_batch_entries",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_embedded_archive_offsets",
        staticmethod(_fake_embedded_archive_offsets),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_extract_embedded_archive_job",
        _fake_extract_embedded_archive_job,
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=4)
    payloads = processor._extract_embedded_archive_payloads(
        payload_bytes,
        source_file,
        member_name,
        depth=0,
    )

    assert peak == 3
    assert payloads == [
        (source_file, "embedded-payload-entries.doc#carved-zip-11", "zip-11-payload"),
        (source_file, "embedded-payload-entries.doc#carved-gz-23", "gz-23-payload"),
        (source_file, "embedded-payload-entries.doc#carved-xz-37", "xz-37-payload"),
    ]


def test_artifact_queue_processor_parallelizes_embedded_archive_offset_signature_scans_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    data = bytearray(b"x" * 96)
    data[11:15] = b"PK\x03\x04"
    data[23:26] = b"\x1f\x8b\x08"
    data[37:40] = b"BZh"
    data[49:55] = b"\xfd7zXZ\x00"
    payload_bytes = bytes(data)
    delays = {
        "zip": 0.05,
        "gz": 0.01,
        "bz2": 0.03,
        "xz": 0.02,
    }
    active = 0
    peak = 0
    lock = threading.Lock()
    original_entry = ArtifactQueueProcessor._embedded_archive_signature_matches

    def _tracking_entry(signature_job, *, data: bytes, max_scan: int):  # noqa: ANN001
        nonlocal active, peak
        archive_kind, _signature = signature_job
        with lock:
            active += 1
            peak = max(peak, active)
        try:
            time.sleep(delays[archive_kind])
            return original_entry(signature_job, data=data, max_scan=max_scan)
        finally:
            with lock:
                active -= 1

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_embedded_archive_signature_matches",
        staticmethod(_tracking_entry),
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=8)
    offsets = processor._embedded_archive_offsets(payload_bytes)

    assert peak == 4
    assert offsets == [
        ("zip", 11),
        ("gz", 23),
        ("bz2", 37),
        ("xz", 49),
    ]


def test_artifact_queue_processor_parallelizes_embedded_archive_match_entries_and_preserves_order(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    data = bytearray(b"x" * 96)
    data[11:15] = b"PK\x03\x04"
    data[23:26] = b"\x1f\x8b\x08"
    data[37:40] = b"BZh"
    data[49:55] = b"\xfd7zXZ\x00"
    payload_bytes = bytes(data)
    active = 0
    peak = 0
    entered = 0
    lock = threading.Lock()
    gate = threading.Event()
    delays = {
        0: 0.05,
        1: 0.01,
        2: 0.03,
        3: 0.02,
        4: 0.04,
    }
    original_entry = ArtifactQueueProcessor._embedded_archive_match_entry

    def _tracking_entry(match_entry):  # noqa: ANN001
        nonlocal active, peak, entered
        match_index, _entry = match_entry
        with lock:
            active += 1
            peak = max(peak, active)
            entered += 1
            current_entered = entered
            if entered >= 4:
                gate.set()
        try:
            if current_entered <= 4:
                assert gate.wait(timeout=1.0)
            time.sleep(delays[match_index])
            return original_entry(match_entry)
        finally:
            with lock:
                active -= 1

    def _fake_signature_matches(signature_job, *, data: bytes, max_scan: int):  # noqa: ANN001
        del data, max_scan
        archive_kind, _signature = signature_job
        return {
            "zip": [("zip", 11), ("zip", 11)],
            "gz": [("gz", 23)],
            "bz2": [("bz2", 37)],
            "xz": [("xz", 49)],
        }[archive_kind]

    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_embedded_archive_match_entry",
        staticmethod(_tracking_entry),
    )
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_embedded_archive_signature_matches",
        staticmethod(_fake_signature_matches),
    )

    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=8)
