def test_artifact_queue_processor_carves_buried_archives_from_legacy_binary_artifacts(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifact_carved"
    artifact_root.mkdir()
    _bootstrap_engagement(db_path)

    buried_zip_doc = artifact_root / "buried-archive.doc"
    nested_zip_bytes = BytesIO()
    with zipfile.ZipFile(nested_zip_bytes, "w") as zf:
        zf.writestr(
            "config/secrets.txt",
            """
            EMBEDDED_EMAIL=buried-owner@acme.example
            EMBEDDED_URL=https://buried.acme.example/export
            EMBEDDED_GCS=https://storage.googleapis.com/acme-buried-gcs/reports/final.json
            """.strip(),
        )
    buried_zip_doc.write_bytes(
        b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1legacy-prefix"
        + nested_zip_bytes.getvalue()
        + b"archive-suffix"
    )

    buried_gzip_doc = artifact_root / "buried-gzip.doc"
    buried_gzip_doc.write_bytes(
        b"legacy-prefix"
        + gzip.compress(
            b"buried-gzip@acme.example https://gzip.acme.example/brief "
            b"gs://acme-gzip-gcs/backups/latest.tar.gz"
        )
        + b"gzip-suffix"
    )

    processor = ArtifactQueueProcessor(db_path, 1001)
    queued = processor.ingest_local_artifacts([artifact_root])
    summary = processor.process()

    assert queued >= 2
    assert summary.processed >= 2
    assert summary.discovered_seeds >= 6

    con = sqlite3.connect(db_path)
    try:
        emails = {
            row[0]
            for row in con.execute("SELECT email FROM emails WHERE engagement_id=1001").fetchall()
        }
        assert "buried-owner@acme.example" in emails
        assert "buried-gzip@acme.example" in emails

        seeds = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("https://buried.acme.example/export", "url") in seeds
        assert ("https://gzip.acme.example/brief", "url") in seeds
        assert ("buried-owner@acme.example", "email") in seeds
        assert ("buried-gzip@acme.example", "email") in seeds

        cloud_assets = con.execute(
            """
            SELECT asset_type, identifier
            FROM cloud_assets
            WHERE engagement_id=1001
            ORDER BY asset_type, identifier
            """
        ).fetchall()
        assert ("gcs", "acme-buried-gcs") in cloud_assets
        assert ("gcs", "acme-gzip-gcs") in cloud_assets

        artifact_meta = {
            row[0]: json.loads(str(row[1] or "{}"))
            for row in con.execute(
                """
                SELECT source_url, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert artifact_meta[buried_zip_doc.resolve().as_posix()]["metadata_payload_count"] >= 1
        assert artifact_meta[buried_gzip_doc.resolve().as_posix()]["metadata_payload_count"] >= 1
    finally:
        con.close()


