def test_artifact_browser_state_structured_payload_extracts_cookie_origins_and_storage_values(
    tmp_path: Path,
    monkeypatch,
) -> None:
    db_path = tmp_path / "engagement.db"
    processor = ArtifactQueueProcessor(db_path, 1001, max_workers=4)
    decoded_storage = {
        "support": "state-owner@acme.example",
        "firebase": "https://state-firebase.firebaseio.com",
        "bucket": "s3://acme-state-bucket/reports/latest.json",
    }
    payload = json.dumps(
        {
            "cookies": [
                {
                    "name": "sid",
                    "value": "secret-do-not-promote",
                    "domain": ".cookie.acme.example",
                    "path": "/",
                },
                {"name": "local", "value": "ignored", "domain": "localhost", "path": "/"},
            ],
            "origins": [
                {
                    "origin": "https://app.acme.example",
                    "localStorage": [
                        {"name": "apiBase", "value": "state-api.acme.example/v1"},
                        {"name": "decodedConfig", "value": json.dumps(decoded_storage)},
                    ],
                    "sessionStorage": [
                        {"name": "portalUrl", "value": "https://state-session.acme.example/app"},
                    ],
                }
            ],
        },
    )
    observed_candidate_batches: list[list[str]] = []
    original_batch = ArtifactQueueProcessor._run_ordered_local_batch

    def _tracking_batch(self, items, worker, *, default_factory):  # noqa: ANN001
        materialized = list(items)
        if getattr(worker, "__name__", "") == "_browser_state_candidate_entry":
            observed_candidate_batches.append([str(item) for item in materialized])
        return original_batch(self, materialized, worker, default_factory=default_factory)

    monkeypatch.setattr(ArtifactQueueProcessor, "_run_ordered_local_batch", _tracking_batch)

    result = processor._browser_state_structured_payload_text(
        payload,
        source_hint="playwright/.auth/storage-state.json",
    )

    assert observed_candidate_batches == [
        [
            ".cookie.acme.example",
            "localhost",
            "https://app.acme.example",
            "state-api.acme.example/v1",
            "state-owner@acme.example",
            "https://state-firebase.firebaseio.com",
            "s3://acme-state-bucket/reports/latest.json",
            "https://state-session.acme.example/app",
        ]
    ]
    assert result.splitlines() == [
        "https://cookie.acme.example",
        "https://app.acme.example",
        "https://state-api.acme.example/v1",
        "state-owner@acme.example",
        "https://state-firebase.firebaseio.com",
        "s3://acme-state-bucket/reports/latest.json",
        "https://state-session.acme.example/app",
    ]
    assert "secret-do-not-promote" not in result


