def test_artifact_queue_processor_extracts_bzip2_txz_and_buried_xz_artifacts(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    artifact_root = tmp_path / "artifact_compressed"
    artifact_root.mkdir()
    _bootstrap_engagement(db_path)

    bz2_path = artifact_root / "compressed-config.bz2"
    bz2_path.write_bytes(
        bz2.compress(
            b"compressed-owner@acme.example "
            b"https://compressed.acme.example/export "
            b"s3://acme-bz2-bucket/backups/latest.tar.gz"
        )
    )

    txz_path = artifact_root / "nested-config.txz"
    with tarfile.open(txz_path, "w:xz") as tf:
        payload = (
            b"nested-owner@acme.example "
            b"https://nested.acme.example/report "
            b"gs://acme-txz-gcs/backups/latest.tar.gz"
        )
        info = tarfile.TarInfo("env/app.env")
        info.size = len(payload)
        tf.addfile(info, BytesIO(payload))

    buried_xz_doc = artifact_root / "buried-xz.doc"
    buried_xz_doc.write_bytes(
        b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1legacy-prefix"
        + lzma.compress(
            b"buried-xz@acme.example "
            b"https://buried-xz.acme.example/brief "
            b"gs://acme-buried-xz-gcs/archive/latest.tgz"
        )
        + b"archive-suffix"
    )

    processor = ArtifactQueueProcessor(db_path, 1001)
    queued = processor.ingest_local_artifacts([artifact_root])
    summary = processor.process()

    assert queued >= 3
    assert summary.processed >= 3
    assert summary.discovered_seeds >= 8

    con = sqlite3.connect(db_path)
    try:
        emails = {
            row[0]
            for row in con.execute("SELECT email FROM emails WHERE engagement_id=1001").fetchall()
        }
        assert "compressed-owner@acme.example" in emails
        assert "nested-owner@acme.example" in emails
        assert "buried-xz@acme.example" in emails

        seeds = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("https://compressed.acme.example/export", "url") in seeds
        assert ("https://nested.acme.example/report", "url") in seeds
        assert ("https://buried-xz.acme.example/brief", "url") in seeds
        assert ("compressed-owner@acme.example", "email") in seeds
        assert ("nested-owner@acme.example", "email") in seeds
        assert ("buried-xz@acme.example", "email") in seeds

        cloud_assets = con.execute(
            """
            SELECT asset_type, identifier
            FROM cloud_assets
            WHERE engagement_id=1001
            ORDER BY asset_type, identifier
            """
        ).fetchall()
        assert ("aws_s3", "acme-bz2-bucket") in cloud_assets
        assert ("gcs", "acme-txz-gcs") in cloud_assets
        assert ("gcs", "acme-buried-xz-gcs") in cloud_assets

        artifact_meta = {
            row[0]: json.loads(str(row[1] or "{}"))
            for row in con.execute(
                """
                SELECT source_url, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert artifact_meta[bz2_path.resolve().as_posix()]["format"] == "bz2"
        assert artifact_meta[txz_path.resolve().as_posix()]["format"] == "txz"
        assert artifact_meta[buried_xz_doc.resolve().as_posix()]["format"] == "doc"
        assert artifact_meta[buried_xz_doc.resolve().as_posix()]["metadata_payload_count"] >= 1
    finally:
        con.close()


