def test_engagement_run_tracker_update_run_skips_locked_progress_flush_quickly(
    tmp_path: Path,
) -> None:
    db_path = tmp_path / "engagement.db"
    _bootstrap_engagement(db_path)

    tracker = EngagementRunTracker(db_path, 1001)
    handle = tracker.start_run(
        run_kind="kill_chain",
        seed_value="Alice Example",
        seed_type="name",
        seed_count=1,
        max_iterations=2,
        resume_enabled=False,
        dry_run=False,
        attack_mode=False,
        metadata={"phase": "preflight"},
    )

    locker = sqlite3.connect(db_path, timeout=5.0, isolation_level=None)
    try:
        locker.execute("BEGIN EXCLUSIVE")
        started = time.monotonic()
        tracker.update_run(
            handle,
            current_iteration=1,
            metadata={"phase": "iteration_1"},
        )
        elapsed = time.monotonic() - started
        assert elapsed < 2.0
    finally:
        locker.rollback()
        locker.close()

    con = sqlite3.connect(db_path)
    try:
        row = con.execute(
            """
            SELECT current_iteration, metadata_json
            FROM engagement_runs
            WHERE id=? AND engagement_id=1001
            """,
            (handle.run_id,),
        ).fetchone()
        assert row is not None
        assert int(row[0]) == 0
        assert json.loads(str(row[1] or "{}"))["phase"] == "preflight"
    finally:
        con.close()


