def test_kill_chain_resume_marks_stale_running_seed_runs_failed_before_retry(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")
    monkeypatch.delenv("FORGE_ROE_ID", raising=False)

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    db_path.parent.mkdir(parents=True, exist_ok=True)
    _bootstrap_engagement(db_path)

    tracker = SeedRunTracker(db_path, 1001)
    stale_run = tracker.start_run(
        "acme.example",
        "domain",
        "fanout_a_subdomains",
        source="operator",
        metadata={"iteration": 0, "fixture": "stale"},
    )
    completed_run = tracker.start_run(
        "beta.example",
        "domain",
        "fanout_a_subdomains",
        source="operator",
        metadata={"iteration": 0, "fixture": "completed"},
    )
    tracker.finish_run(
        completed_run,
        status="completed",
        output_count=2,
        metadata={"iteration": 0, "fixture": "completed"},
    )
    skipped_run = tracker.start_run(
        "gamma.example",
        "domain",
        "fanout_a_subdomains",
        source="operator",
        metadata={"iteration": 0, "fixture": "skipped"},
    )
    tracker.finish_run(
        skipped_run,
        status="skipped",
        metadata={"iteration": 0, "fixture": "skipped"},
    )

    from forge.cli import kill_chain

    kill_chain(
        seed="acme.example",
        related_seed=["beta.example", "gamma.example"],
        engagement="1001",
        resume=True,
        max_iter=1,
        tor=False,
        dry_run=True,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
    )

    con = sqlite3.connect(db_path)
    try:
        rows = con.execute(
            """
            SELECT es.seed_value, sr.id, sr.status, sr.error, sr.completed_at
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND sr.loop_name='fanout_a_subdomains'
            ORDER BY es.seed_value, sr.id
            """
        ).fetchall()
        grouped: dict[str, list[tuple[int, str, str, str]]] = {}
        for seed_value, run_id, status, error, completed_at in rows:
            grouped.setdefault(str(seed_value), []).append(
                (
                    int(run_id),
                    str(status),
                    str(error or ""),
                    str(completed_at or ""),
                )
            )

        assert [row[1] for row in grouped["acme.example"]] == ["failed", "skipped"]
        assert grouped["acme.example"][0][0] == stale_run.run_id
        assert "abandoned before explicit completion" in grouped["acme.example"][0][2]
        assert grouped["acme.example"][0][3]
        assert grouped["acme.example"][1][3]
        assert [row[1] for row in grouped["beta.example"]] == ["completed"]
        assert [row[1] for row in grouped["gamma.example"]] == ["skipped"]

        running_count = con.execute(
            """
            SELECT COUNT(*)
            FROM seed_runs
            WHERE engagement_id=1001 AND status='running'
            """
        ).fetchone()[0]
        assert int(running_count or 0) == 0
    finally:
        con.close()


def test_kill_chain_dry_run_records_d3_d4_provider_skips_without_dispatch(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")
    monkeypatch.delenv("FORGE_ROE_ID", raising=False)

    def _provider_dispatch_must_not_run(
        specs, run_module, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del run_module, max_workers, progress_label, progress_callback
        provider_specs = [
            spec
            for spec in specs
            if tuple(str(arg) for arg in spec.cmd_argv[:2])
            in {
                ("osint", "shodan"),
                ("osint", "urlscan"),
            }
        ]
        assert provider_specs == []
        return [0] * len(specs)

    monkeypatch.setattr("forge.cli._run_module_batch", _provider_dispatch_must_not_run)

    from forge.cli import kill_chain

    kill_chain(
        seed="acme.example",
        related_seed=[],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=True,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
    )

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    con = sqlite3.connect(db_path)
    try:
        rows = con.execute(
            """
            SELECT es.seed_value, sr.loop_name, sr.status, sr.metadata_json
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND sr.loop_name IN ('fanout_d3_shodan', 'fanout_d4_urlscan')
            ORDER BY sr.loop_name, es.seed_value
            """
        ).fetchall()
    finally:
        con.close()

    run_map = {
        (str(row[0]), str(row[1])): (str(row[2]), json.loads(str(row[3] or "{}"))) for row in rows
    }
    assert set(run_map) == {
        ("acme.example", "fanout_d3_shodan"),
        ("acme.example", "fanout_d4_urlscan"),
    }
    for status, metadata in run_map.values():
        assert status == "skipped"
        assert metadata["mode"] == "dry_run"
        assert metadata["iteration"] == 1


def test_kill_chain_canonicalizes_duplicate_initial_domain_and_email_seeds(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")
    monkeypatch.delenv("FORGE_ROE_ID", raising=False)

    from forge.cli import kill_chain

    kill_chain(
        seed="ACME.EXAMPLE",
        related_seed=[
            "acme.example",
            "SECURITY@ACME.EXAMPLE",
            "security@acme.example",
        ],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=True,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
        parallel_fanout=4,
    )

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    con = sqlite3.connect(db_path)
    try:
        seed_rows = con.execute(
            """
            SELECT seed_value, seed_type
            FROM engagement_seeds
            WHERE engagement_id=1001
              AND seed_type IN ('domain', 'email')
            ORDER BY seed_type, seed_value
            """
        ).fetchall()
        assert ("acme.example", "domain") in seed_rows
        assert ("ACME.EXAMPLE", "domain") not in seed_rows
        assert ("security@acme.example", "email") in seed_rows
        assert ("SECURITY@ACME.EXAMPLE", "email") not in seed_rows

        run_counts = {
            (str(row[0]), str(row[1])): int(row[2])
            for row in con.execute(
                """
                SELECT es.seed_value, sr.loop_name, COUNT(*)
                FROM seed_runs sr
                JOIN engagement_seeds es ON es.id=sr.seed_id
                WHERE sr.engagement_id=1001
                  AND sr.loop_name IN (
                    'fanout_a_subdomains',
                    'fanout_b_harvest',
                    'fanout_g_dns',
                    'fanout_h_rdap',
                    'fanout_i_wayback',
                    'fanout_e_chain'
                  )
                GROUP BY es.seed_value, sr.loop_name
                """
            ).fetchall()
        }
        for loop_name in (
            "fanout_a_subdomains",
            "fanout_b_harvest",
            "fanout_g_dns",
            "fanout_h_rdap",
            "fanout_i_wayback",
        ):
            assert run_counts[("acme.example", loop_name)] == 1
        assert run_counts[("security@acme.example", "fanout_e_chain")] == 1
    finally:
        con.close()


