def test_kill_chain_active_port_child_receives_scope_manifest(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")
    monkeypatch.setenv("FORGE_ROE_ID", "ROE-ACME-2026-07")
    manifest_path = tmp_path / "roe-scope.json"
    manifest_path.write_text(
        json.dumps(
            {
                "roe_id": "ROE-ACME-2026-07",
                "authorized_seeds": ["@rootuser"],
            }
        ),
        encoding="utf-8",
    )
    module_invocations: list[list[str]] = []

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        forge_index = argv.index("forge.cli")
        module_argv = [item for item in argv[forge_index + 1 :] if item != "--no-tor"]
        module_invocations.append(module_argv)
        if module_argv[:2] == ["report", "generate"] and "--output" in module_argv:
            report_path = tmp_path / module_argv[module_argv.index("--output") + 1]
            report_path.parent.mkdir(parents=True, exist_ok=True)
            report_path.write_text("# Final report\n", encoding="utf-8")
        return subprocess.CompletedProcess(argv, 0, stdout="ok\n", stderr="")

    def _fake_inprocess_batch(
        items, worker, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del max_workers, progress_label, progress_callback
        return [worker(item) for item in items]

    def _fake_module_batch(
        specs, run_module, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del specs, run_module, max_workers, progress_label, progress_callback
        return []

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    monkeypatch.setattr("forge.cli._run_inprocess_batch", _fake_inprocess_batch)
    monkeypatch.setattr("forge.cli._run_module_batch", _fake_module_batch)

    from forge.cli import kill_chain

    kill_chain(
        seed="@rootuser",
        related_seed=[],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=False,
        attack_mode=True,
        scope_manifest=str(manifest_path),
        skip_cloud=True,
        skip_keyscan=True,
        report_provider="template",
    )

    port_commands = [argv for argv in module_invocations if argv[:2] == ["recon", "ports"]]
    assert len(port_commands) == 1
    assert "--scope-manifest" in port_commands[0]
    assert port_commands[0][port_commands[0].index("--scope-manifest") + 1] == str(manifest_path)


def test_kill_chain_scope_manifest_denies_out_of_scope_recursive_url_without_fetch(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")
    monkeypatch.setenv("FORGE_ROE_ID", "ROE-ACME-2026-07")

    manifest_path = tmp_path / "roe-scope.json"
    manifest_path.write_text(
        json.dumps(
            {
                "roe_id": "ROE-ACME-2026-07",
                "domains": ["acme.example"],
                "urls": ["https://acme.example/app/"],
            }
        ),
        encoding="utf-8",
    )

    fetched_by_label: list[tuple[str, str]] = []
    root_html = (
        "<html><body>"
        '<a href="/app/dashboard">Allowed app</a>'
        '<a href="/admin">Out of scope admin</a>'
        "</body></html>"
    )

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        return subprocess.CompletedProcess([str(item) for item in cmd], 0, stdout="ok\n", stderr="")

    def _fake_html_batch(specs, *_args, progress_label=None, **_kwargs):  # noqa: ANN001
        label = str(progress_label or "")
        urls = [str(spec.url) for spec in specs]
        fetched_by_label.extend((label, url) for url in urls)
        if label == "1.D cloud+HTML fetch":
            return [root_html if url == "https://acme.example" else "" for url in urls]
        if label == "1.D2 passive text fetch":
            return ["" for _ in urls]
        if label == "1.D5 URL surface fetch":
            assert "https://acme.example/admin" not in urls
            return ["<html><body>app ok</body></html>" for _ in urls]
        raise AssertionError(f"unexpected html batch label: {progress_label}")

    def _fake_callable_batch(
        items, worker, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del worker, max_workers
        if progress_callback is not None and progress_label:
            progress_callback(
                progress_label,
                {
                    "total": len(items),
                    "workers": min(1, len(items)) if items else 0,
                    "running": 0,
                    "pending": 0,
                    "queue_depth": 0,
                    "completed": len(items),
                    "failed": 0,
                    "eta_seconds": 0.0,
                },
            )
        if progress_label and progress_label.endswith("G DNS enrichment"):
            return [
                {
                    "root_domain": str(item),
                    "queried_hosts": [str(item)],
                    "cname_targets": [],
                    "signals": [],
                }
                for item in items
            ]
        if progress_label and progress_label.endswith("H whois/RDAP"):
            return [{"root_domain": str(item), "rdap": {}} for item in items]
        if progress_label and progress_label.endswith("I Wayback CDX"):
            return [{"root_domain": str(item), "urls": []} for item in items]
        return []

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    monkeypatch.setattr("forge.cli._run_html_fetch_batch", _fake_html_batch)
    monkeypatch.setattr("forge.cli._run_callable_batch", _fake_callable_batch)

    from forge.cli import kill_chain

    kill_chain(
        seed="acme.example",
        related_seed=[],
        engagement="1001",
        resume=True,
        max_iter=1,
        tor=False,
        dry_run=False,
        attack_mode=False,
        scope_manifest=str(manifest_path),
        skip_cloud=True,
        skip_keyscan=True,
        parallel_fanout=2,
        report_provider="template",
    )

    kill_chain(
        seed="acme.example",
        related_seed=[],
        engagement="1001",
        resume=True,
        max_iter=1,
        tor=False,
        dry_run=False,
        attack_mode=False,
        roe_id="ROE-ACME-2026-07",
        scope_manifest=str(manifest_path),
        skip_cloud=True,
        skip_keyscan=True,
        parallel_fanout=2,
        report_provider="template",
    )

    d5_fetch_urls = [url for label, url in fetched_by_label if label == "1.D5 URL surface fetch"]
    assert "https://acme.example/app/dashboard" in d5_fetch_urls
    assert "https://acme.example/admin" not in d5_fetch_urls

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    con = sqlite3.connect(db_path)
    try:
        seeds = {
            (str(row[0]), str(row[1]))
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("https://acme.example/app/dashboard", "url") in seeds
        assert ("https://acme.example/admin", "url") in seeds

        denied_seed_runs = con.execute(
            """
            SELECT sr.status, sr.output_count, sr.error, sr.metadata_json
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND es.seed_value='https://acme.example/admin'
              AND sr.loop_name='fanout_d5_url_seed_html'
            ORDER BY sr.id
            """
        ).fetchall()
        assert len(denied_seed_runs) == 1
        denied_status, denied_output_count, denied_error, denied_metadata_json = denied_seed_runs[0]
        denied_metadata = json.loads(str(denied_metadata_json or "{}"))
        assert denied_status == "skipped"
        assert int(denied_output_count or 0) == 0
        assert denied_error == "scope_manifest_denied"
        assert denied_metadata["denied_before_fetch"] is True
        assert denied_metadata["deny_hostname"] == "acme.example"
        assert denied_metadata["deny_reason"] == "scope_manifest_denied"
        assert denied_metadata["scope_manifest_source"] == manifest_path.resolve().as_posix()

        audit_rows = con.execute(
            """
            SELECT phase, module, action, target, result
            FROM audit_log
            WHERE engagement_id=1001
              AND action='recursive_seed_scope_denied'
            """
        ).fetchall()
        assert audit_rows
        assert any(str(row[3]) == "https://acme.example/admin" for row in audit_rows)
        assert any("reason=scope_manifest_denied" in str(row[4]) for row in audit_rows)
        assert any(manifest_path.resolve().as_posix() in str(row[4]) for row in audit_rows)
    finally:
        con.close()


def test_kill_chain_scope_manifest_denies_out_of_scope_remote_artifact_download(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")
    monkeypatch.setenv("FORGE_ROE_ID", "ROE-ACME-2026-07")

    manifest_path = tmp_path / "roe-scope.json"
    manifest_path.write_text(
        json.dumps(
            {
                "roe_id": "ROE-ACME-2026-07",
                "domains": ["acme.example"],
                "urls": ["https://acme.example/app/"],
            }
        ),
        encoding="utf-8",
    )

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    db_path.parent.mkdir(parents=True, exist_ok=True)
    _bootstrap_engagement(db_path)
    con = sqlite3.connect(db_path)
    try:
        con.execute(
            """
            INSERT INTO artifact_queue
                (engagement_id, source_url, artifact_type, discovered_from, status, metadata_json)
            VALUES
                (1001, 'https://evil.example/bootstrap.apk', 'apk', 'preexisting_fixture', 'queued', '{}')
            """
        )
        con.commit()
    finally:
        con.close()

    downloaded_urls: list[str] = []
    root_html = (
        "<html><body>"
        '<a href="/app/config.json">Allowed config</a>'
        '<a href="/admin/secrets.json">Out of scope config</a>'
        "</body></html>"
    )

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        return subprocess.CompletedProcess([str(item) for item in cmd], 0, stdout="ok\n", stderr="")

    def _fake_html_batch(specs, *_args, progress_label=None, **_kwargs):  # noqa: ANN001
        urls = [str(spec.url) for spec in specs]
        if progress_label == "1.D cloud+HTML fetch":
            return [root_html if url == "https://acme.example" else "" for url in urls]
        if progress_label in {"1.D2 passive text fetch", "1.D5 URL surface fetch"}:
            return ["" for _ in urls]
        raise AssertionError(f"unexpected html batch label: {progress_label}")

    def _fake_callable_batch(
        items, worker, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del worker, max_workers
        if progress_callback is not None and progress_label:
            progress_callback(
                progress_label,
                {
                    "total": len(items),
                    "workers": min(1, len(items)) if items else 0,
                    "running": 0,
                    "pending": 0,
                    "queue_depth": 0,
                    "completed": len(items),
                    "failed": 0,
                    "eta_seconds": 0.0,
                },
            )
        if progress_label and progress_label.endswith("G DNS enrichment"):
            return [
                {
                    "root_domain": str(item),
                    "queried_hosts": [str(item)],
                    "cname_targets": [],
                    "signals": [],
                }
                for item in items
            ]
        if progress_label and progress_label.endswith("H whois/RDAP"):
            return [{"root_domain": str(item), "rdap": {}} for item in items]
        if progress_label and progress_label.endswith("I Wayback CDX"):
            return [{"root_domain": str(item), "urls": []} for item in items]
        return []

    def _fake_download_remote_artifact_request(self, request):  # noqa: ANN001
        del self
        downloaded_urls.append(request.source_url)
        if request.source_url in {
            "https://evil.example/bootstrap.apk",
            "https://acme.example/admin/secrets.json",
        }:
            raise AssertionError("out-of-scope remote artifact was downloaded")
        assert request.source_url == "https://acme.example/app/config.json"
        download_path = tmp_path / "allowed-config.json"
        download_path.write_text('{"contact":"artifact-owner@acme.example"}', encoding="utf-8")
        return ArtifactDownloadResult(
            artifact_id=request.artifact_id,
            source_url=request.source_url,
            artifact_type=request.artifact_type,
            path=download_path,
            metadata_extra={"download_filename": download_path.name},
        )

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    monkeypatch.setattr("forge.cli._run_html_fetch_batch", _fake_html_batch)
    monkeypatch.setattr("forge.cli._run_callable_batch", _fake_callable_batch)
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_download_remote_artifact_request",
        _fake_download_remote_artifact_request,
    )

    from forge.cli import kill_chain

    kill_chain(
        seed="acme.example",
        related_seed=[],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=False,
        attack_mode=False,
        scope_manifest=str(manifest_path),
        skip_cloud=True,
        skip_keyscan=True,
        parallel_fanout=2,
        report_provider="template",
    )

    assert downloaded_urls == ["https://acme.example/app/config.json"]

    con = sqlite3.connect(db_path)
    try:
        artifact_rows = {
            str(row[0]): (str(row[1]), str(row[2] or ""))
            for row in con.execute(
                """
                SELECT source_url, status, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert artifact_rows["https://acme.example/app/config.json"][0] == "parsed"
        assert artifact_rows["https://evil.example/bootstrap.apk"][0] == "skipped"
        assert (
            "scope_manifest_denied_remote_artifact"
            in artifact_rows["https://evil.example/bootstrap.apk"][1]
        )
        assert artifact_rows["https://acme.example/admin/secrets.json"][0] == "skipped"
        assert (
            "scope_manifest_denied_remote_artifact"
            in artifact_rows["https://acme.example/admin/secrets.json"][1]
        )

        audit_rows = con.execute(
            """
            SELECT phase, module, action, target, result
            FROM audit_log
            WHERE engagement_id=1001
              AND action='remote_artifact_scope_denied'
            """
        ).fetchall()
        assert audit_rows
        assert any(str(row[3]) == "https://evil.example/bootstrap.apk" for row in audit_rows)
        assert any(str(row[3]) == "https://acme.example/admin/secrets.json" for row in audit_rows)
        assert any("reason=scope_manifest_denied" in str(row[4]) for row in audit_rows)
        assert any(manifest_path.resolve().as_posix() in str(row[4]) for row in audit_rows)
    finally:
        con.close()


