def test_kill_chain_routes_related_url_seed_through_initial_domain_and_host_fanouts(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")
    monkeypatch.setenv("FORGE_ROE_ID", "ROE-ACME-2026-07")
    manifest_path = tmp_path / "roe-scope.json"
    manifest_path.write_text(
        json.dumps(
            {
                "roe_id": "ROE-ACME-2026-07",
                "domains": [
                    "acme.example",
                    "*.acme.example",
                    "nyc3.digitaloceanspaces.com",
                    "*.nyc3.digitaloceanspaces.com",
                ],
                "authorized_seeds": ["+15559876543"],
            }
        ),
        encoding="utf-8",
    )

    fetched_urls: list[str] = []
    html_blob = (
        "<html><body>"
        "https://acme-space-public.nyc3.digitaloceanspaces.com/archive/final.json"
        "</body></html>"
    )

    class _DOSpacesClient:
        def __init__(self, *args, **kwargs) -> None:  # noqa: ANN002, ANN003
            del args, kwargs

        def __enter__(self) -> "_DOSpacesClient":
            return self

        def __exit__(self, exc_type, exc, tb) -> None:  # noqa: ANN001
            del exc_type, exc, tb

        def close(self) -> None:
            return None

        def head(self, url: str, **kwargs):  # noqa: ANN003
            del kwargs
            if "acme-space-public.nyc3.digitaloceanspaces.com" in url:
                return type(
                    "_Resp",
                    (),
                    {
                        "status_code": 200,
                        "text": "",
                        "headers": {"content-type": "application/xml"},
                    },
                )()
            return type(
                "_Resp",
                (),
                {
                    "status_code": 404,
                    "text": "missing",
                    "headers": {"content-type": "application/xml"},
                },
            )()

        def get(self, url: str, **kwargs):  # noqa: ANN003
            del kwargs
            if "acme-space-public.nyc3.digitaloceanspaces.com" in url:
                return type(
                    "_Resp",
                    (),
                    {
                        "status_code": 200,
                        "text": (
                            "<?xml version='1.0' encoding='UTF-8'?>"
                            "<ListBucketResult>"
                            "<Contents><Key>reports/engagement-summary.pdf</Key></Contents>"
                            "</ListBucketResult>"
                        ),
                        "headers": {"content-type": "application/xml"},
                    },
                )()
            return type(
                "_Resp",
                (),
                {
                    "status_code": 404,
                    "text": "missing",
                    "headers": {"content-type": "application/xml"},
                },
            )()

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        forge_index = argv.index("forge.cli")
        module_argv = [item for item in argv[forge_index + 1 :] if item != "--no-tor"]
        graph_index = next(
            (
                index
                for index in range(0, max(0, len(module_argv) - 1))
                if module_argv[index : index + 2] == ["graph", "build"]
            ),
            -1,
        )
        report_index = next(
            (
                index
                for index in range(0, max(0, len(module_argv) - 1))
                if module_argv[index : index + 2] == ["report", "generate"]
            ),
            -1,
        )
        command_argv = (
            module_argv[min(index for index in (graph_index, report_index) if index >= 0) :]
            if (graph_index >= 0 or report_index >= 0)
            else module_argv
        )

        def _flag_value(flag: str) -> str | None:
            prefix = f"{flag}="
            for value in command_argv:
                if value.startswith(prefix):
                    return value[len(prefix) :]
            if flag not in command_argv:
                return None
            index = command_argv.index(flag)
            if index + 1 >= len(command_argv):
                return None
            return command_argv[index + 1]

        if graph_index >= 0:
            from forge.cli import graph_build  # noqa: PLC0415

            graph_build(
                engagement=str(_flag_value("--engagement") or ""),
                fmt=str(_flag_value("--format") or "json"),
                output_dir=_flag_value("--output-dir"),
                min_severity=str(_flag_value("--min-severity") or "LOW"),
                critical_path_only="--critical-path-only" in command_argv,
                snapshot="--snapshot" in command_argv,
                max_nodes=int(_flag_value("--max-nodes") or "150"),
            )
            return subprocess.CompletedProcess(argv, 0, stdout="graph built\n", stderr="")

        if report_index >= 0:
            from forge.cli import report_generate  # noqa: PLC0415

            max_loops = _flag_value("--max-loops")
            report_generate(
                engagement=str(_flag_value("--engagement") or ""),
                output=_flag_value("--output"),
                yes=("--yes" in command_argv or "-y" in command_argv),
                provider=_flag_value("--provider") or "template",
                max_loops=int(max_loops) if max_loops is not None else None,
            )
            return subprocess.CompletedProcess(argv, 0, stdout="report generated\n", stderr="")

        return subprocess.CompletedProcess(argv, 0, stdout="ok\n", stderr="")

    def _fake_html_batch(specs, *_args, **_kwargs):  # noqa: ANN001
        fetched_urls.extend(spec.url for spec in specs)
        return [html_blob for _ in specs]

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    from forge.phase4 import cloud_validate

    monkeypatch.setattr(cloud_validate.httpx, "Client", _DOSpacesClient)

    from forge.cli import kill_chain

    monkeypatch.setattr("forge.cli._run_html_fetch_batch", _fake_html_batch)

    kill_chain(
        seed="+15559876543",
        related_seed=["https://portal.acme.example/login"],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=False,
        attack_mode=False,
        roe_id="ROE-ACME-2026-07",
        scope_manifest=str(manifest_path),
        skip_cloud=False,
        skip_keyscan=True,
        parallel_fanout=3,
    )

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    con = sqlite3.connect(db_path)
    try:
        rows = con.execute(
            """
            SELECT es.seed_value, sr.loop_name, sr.status
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND sr.loop_name IN ('fanout_a_subdomains', 'fanout_g_dns', 'fanout_l_seed_phone')
            ORDER BY sr.loop_name, es.seed_value
            """
        ).fetchall()
        run_map = {(row[0], row[1]): row[2] for row in rows}
        assert run_map[("+15559876543", "fanout_l_seed_phone")] == "completed"
        assert run_map[("acme.example", "fanout_a_subdomains")] == "completed"
        assert run_map[("acme.example", "fanout_g_dns")] == "completed"

        metadata_row = con.execute(
            """
            SELECT metadata_json
            FROM engagement_runs
            WHERE engagement_id=1001
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
        assert metadata_row is not None
        metadata = json.loads(str(metadata_row[0] or "{}"))
        assert "acme.example" in list(metadata.get("root_domains") or [])
        assert metadata["live_probing_allowed"] is True
        assert metadata["tool_execution_allowed"] is True
        assert metadata["roe_id"] == "ROE-ACME-2026-07"
        live_policy = metadata["live_execution_policy"]
        assert live_policy["scope_gate"] == "engagement_scope_json_root_domains"
        assert live_policy["roe_id"] == "ROE-ACME-2026-07"
        assert live_policy["roe_present"] is True
        assert live_policy["live_probing_allowed"] is True
        assert live_policy["tool_execution_allowed"] is True
        assert live_policy["active_recon_allowed"] is False
        assert live_policy["credential_validation_allowed"] is False
        assert live_policy["destructive_actions_allowed"] is False
        assert live_policy["post_exploitation_allowed"] is False
        assert live_policy["requires_explicit_roe"] is True
        assert live_policy["roe_missing"] is False

        start_audit = con.execute(
            """
            SELECT result
            FROM audit_log
            WHERE engagement_id=1001 AND action='kill_chain_start'
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
        assert start_audit is not None
        assert "live_probe=True" in str(start_audit[0] or "")
        assert "roe_id=ROE-ACME-2026-07" in str(start_audit[0] or "")

    finally:
        con.close()

    assert "https://portal.acme.example" in fetched_urls
    assert "http://portal.acme.example" in fetched_urls


