    try:
        metadata_row = con.execute(
            """
            SELECT metadata_json
            FROM engagement_runs
            WHERE engagement_id=1001
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
        assert metadata_row is not None
        metadata = json.loads(str(metadata_row[0] or "{}"))
        assert "amazonaws.com" not in list(metadata.get("root_domains") or [])
        assert "storage.cloud.google.com" not in list(metadata.get("root_domains") or [])
        assert "firebasestorage.googleapis.com" not in list(metadata.get("root_domains") or [])
        assert "vercel.app" not in list(metadata.get("root_domains") or [])
        assert "netlify.com" not in list(metadata.get("root_domains") or [])
        assert "amplifyapp.com" not in list(metadata.get("root_domains") or [])
        assert "appspot.com" not in list(metadata.get("root_domains") or [])
        assert "cloudfunctions.net" not in list(metadata.get("root_domains") or [])
        assert "pages.dev" not in list(metadata.get("root_domains") or [])
        assert "workers.dev" not in list(metadata.get("root_domains") or [])
        assert "r2.dev" not in list(metadata.get("root_domains") or [])
        assert "r2.cloudflarestorage.com" not in list(metadata.get("root_domains") or [])
        assert "github.io" not in list(metadata.get("root_domains") or [])
        assert "gitlab.io" not in list(metadata.get("root_domains") or [])
        validation_batch_metrics = metadata.get("queue_metrics", {}).get("validation_batch", {})
        assert int(validation_batch_metrics.get("completed", 0)) >= 13
        assert metadata.get("active_validation_stage_label")
        assert float(metadata.get("active_validation_eta_seconds") or 0.0) >= 0.0

        cloud_assets = {
            (row[0], row[1])
            for row in con.execute(
                """
                SELECT asset_type, identifier
                FROM cloud_assets
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("aws_s3", "acme-site-bucket") in cloud_assets
        assert ("gcs", "acme-browser-bucket") in cloud_assets
        assert ("gcs", "acme-firestorage.appspot.com") in cloud_assets
        assert ("vercel", "acme-preview") in cloud_assets
        assert ("netlify", "acme-legacy") in cloud_assets
        assert ("amplify", "acme-amplify") in cloud_assets
        assert ("gcp_appspot", "acmeportal") in cloud_assets
        assert (
            "gcp_cloudfunctions",
            "https://us-central1-acmehub.cloudfunctions.net/ping",
        ) in cloud_assets
        assert ("cloudflare_pages", "acme-pages") in cloud_assets
        assert ("cloudflare_worker", "worker.acme.workers.dev") in cloud_assets
        assert ("cloudflare_r2", "pub-direct.r2.dev") in cloud_assets
        assert ("cloudflare_r2", "accountid.r2.cloudflarestorage.com") in cloud_assets
        assert ("github_pages", "acme.github.io") in cloud_assets
        assert ("gitlab_pages", "security.gitlab.io") in cloud_assets

        validation_rows = {
            (row[0], row[1], row[2])
            for row in con.execute(
                """
                SELECT asset_type, identifier, validation_status
                FROM cloud_validation_results
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("aws_s3", "acme-site-bucket", "VALIDATED") in validation_rows
        assert ("gcs", "acme-browser-bucket", "VALIDATED") in validation_rows
        assert ("gcs", "acme-firestorage.appspot.com", "VALIDATED") in validation_rows
        assert ("vercel", "acme-preview", "ACCESSIBLE_BUT_NO_DATA") in validation_rows
        assert any(
            asset_type == "netlify"
            and identifier.startswith("acme-legacy")
            and status == "ACCESSIBLE_BUT_NO_DATA"
            for asset_type, identifier, status in validation_rows
        )
        assert ("amplify", "acme-amplify", "ACCESSIBLE_BUT_NO_DATA") in validation_rows
        assert ("gcp_appspot", "acmeportal", "ACCESSIBLE_BUT_NO_DATA") in validation_rows
        assert (
            "gcp_cloudfunctions",
            "https://us-central1-acmehub.cloudfunctions.net/ping",
            "ACCESSIBLE_BUT_NO_DATA",
        ) in validation_rows
        assert ("cloudflare_pages", "acme-pages", "ACCESSIBLE_BUT_NO_DATA") in validation_rows
        assert (
            "cloudflare_worker",
            "worker.acme.workers.dev",
            "ACCESSIBLE_BUT_NO_DATA",
        ) in validation_rows
        assert ("cloudflare_r2", "pub-direct.r2.dev", "ACCESSIBLE_BUT_NO_DATA") in validation_rows
        assert (
            "cloudflare_r2",
            "accountid.r2.cloudflarestorage.com",
            "ACCESSIBLE_BUT_NO_DATA",
        ) in validation_rows
        assert ("github_pages", "acme.github.io", "ACCESSIBLE_BUT_NO_DATA") in validation_rows
        assert ("gitlab_pages", "security.gitlab.io", "ACCESSIBLE_BUT_NO_DATA") in validation_rows
    finally:
        con.close()

    assert fetched_urls == []


