    nodes_csv_path = reports_dir / "1001_attack_graph_nodes.csv"
    graph_json_path = reports_dir / "1001_attack_graph.json"
    dashboard_path = reports_dir / "dashboard.html"

    assert graphml_path.is_file()
    assert mtgx_path.is_file()
    assert edges_csv_path.is_file()
    assert nodes_csv_path.is_file()
    assert graph_json_path.is_file()
    assert dashboard_path.is_file()

    edge_csv_lines = [
        line.strip()
        for line in edges_csv_path.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    assert edge_csv_lines[0] == "Source,Target,Weight,Relation,MetadataJSON"
    assert any(line.rsplit(",", 1)[-1].strip() for line in edge_csv_lines[1:])

    report_files = sorted(reports_dir.glob("engagement_1001_kill_chain_*.md"))
    assert report_files
    report_path = report_files[-1]
    report_text = report_path.read_text(encoding="utf-8")
    assert "Validated Firebase data exposure" in report_text
    assert "template mode, no LLM" in report_text
    assert report_path.with_suffix(".json").is_file()
    assert report_path.with_suffix(".pdf").is_file()

    assert "https://acme.example" in fetched_urls
    assert "https://acme.example/careers" in fetched_urls


