    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        forge_index = argv.index("forge.cli")
        module_argv = [item for item in argv[forge_index + 1 :] if item != "--no-tor"]
        if module_argv[:2] == ["report", "generate"] and "--output" in module_argv:
            report_path = tmp_path / module_argv[module_argv.index("--output") + 1]
            report_path.parent.mkdir(parents=True, exist_ok=True)
            report_path.write_text("# Final report\n", encoding="utf-8")
        return subprocess.CompletedProcess(argv, 0, stdout="ok\n", stderr="")

    def _fake_html_batch(specs, *_args, progress_label=None, **_kwargs):  # noqa: ANN001
        fetched_urls.extend(spec.url for spec in specs)
        if progress_label == "1.D cloud+HTML fetch":
            return [html_blob for _ in specs]
        if progress_label == "1.D2 passive text fetch":
            return ["" for _ in specs]
        if progress_label == "1.D5 URL surface fetch":
            return ["" for _ in specs]
        raise AssertionError(f"unexpected html batch label: {progress_label}")

    def _fake_callable_batch(
        items, worker, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del worker, max_workers

        def _emit(completed: int) -> None:
            if progress_callback is None or not progress_label:
                return
            progress_callback(
                progress_label,
                {
                    "total": len(items),
                    "workers": min(1, len(items)) if items else 0,
                    "running": 0,
                    "pending": max(0, len(items) - completed),
                    "queue_depth": max(0, len(items) - completed),
                    "completed": completed,
                    "failed": 0,
                    "eta_seconds": 0.0,
                },
            )

        _emit(0)
        if progress_label == "1.G DNS enrichment":
            results = [
                {
                    "root_domain": str(item),
                    "queried_hosts": [str(item)],
                    "cname_targets": [],
                    "signals": [],
                }
                for item in items
            ]
        elif progress_label == "1.H whois/RDAP":
            results = [{"root_domain": str(item), "rdap": {}} for item in items]
        elif progress_label == "1.I Wayback CDX":
            results = [{"root_domain": str(item), "urls": []} for item in items]
        else:
            raise AssertionError(f"unexpected callable batch label: {progress_label}")
        _emit(len(items))
        return results

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    monkeypatch.setattr("forge.cli._run_html_fetch_batch", _fake_html_batch)
    monkeypatch.setattr("forge.cli._run_callable_batch", _fake_callable_batch)

