def test_kill_chain_html_phone_pivots_feed_recursive_phone_fanout(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")

    fetched_urls: list[str] = []
    html_blob = (
        "<html><body>"
        "Hotline +1 (555) 987-6543 "
        "Call us at tel:+1-555-222-3333 "
        "https://wa.me/15550004444 "
        "https://api.whatsapp.com/send?phone=15550005555"
        "</body></html>"
    )

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        forge_index = argv.index("forge.cli")
        module_argv = [item for item in argv[forge_index + 1 :] if item != "--no-tor"]
        if module_argv[:2] == ["report", "generate"] and "--output" in module_argv:
            report_path = tmp_path / module_argv[module_argv.index("--output") + 1]
            report_path.parent.mkdir(parents=True, exist_ok=True)
            report_path.write_text("# Final report\n", encoding="utf-8")
        return subprocess.CompletedProcess(argv, 0, stdout="ok\n", stderr="")

    def _fake_html_batch(specs, *_args, progress_label=None, **_kwargs):  # noqa: ANN001
        fetched_urls.extend(spec.url for spec in specs)
        if progress_label == "1.D cloud+HTML fetch":
            return [html_blob for _ in specs]
        if progress_label == "1.D2 passive text fetch":
            return ["" for _ in specs]
        if progress_label == "1.D5 URL surface fetch":
            return ["" for _ in specs]
        raise AssertionError(f"unexpected html batch label: {progress_label}")

    def _fake_callable_batch(
        items, worker, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del worker, max_workers

        def _emit(completed: int) -> None:
            if progress_callback is None or not progress_label:
                return
            progress_callback(
                progress_label,
                {
                    "total": len(items),
                    "workers": min(1, len(items)) if items else 0,
                    "running": 0,
                    "pending": max(0, len(items) - completed),
                    "queue_depth": max(0, len(items) - completed),
                    "completed": completed,
                    "failed": 0,
                    "eta_seconds": 0.0,
                },
            )

        _emit(0)
        if progress_label == "1.G DNS enrichment":
            results = [
                {
                    "root_domain": str(item),
                    "queried_hosts": [str(item)],
                    "cname_targets": [],
                    "signals": [],
                }
                for item in items
            ]
        elif progress_label == "1.H whois/RDAP":
            results = [{"root_domain": str(item), "rdap": {}} for item in items]
        elif progress_label == "1.I Wayback CDX":
            results = [{"root_domain": str(item), "urls": []} for item in items]
        else:
            raise AssertionError(f"unexpected callable batch label: {progress_label}")
        _emit(len(items))
        return results

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    monkeypatch.setattr("forge.cli._run_html_fetch_batch", _fake_html_batch)
    monkeypatch.setattr("forge.cli._run_callable_batch", _fake_callable_batch)

    from forge.cli import kill_chain

    kill_chain(
        seed="acme.example",
        related_seed=[],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=False,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
        parallel_fanout=2,
    )

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        seed_rows = {
            (str(row["seed_value"]), str(row["seed_type"]), str(row["source"]))
            for row in con.execute(
                """
                SELECT seed_value, seed_type, source
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("+15559876543", "phone", "discovered") in seed_rows
        assert ("+15552223333", "phone", "discovered") in seed_rows
        assert ("+15550004444", "phone", "discovered") in seed_rows
        assert ("+15550005555", "phone", "discovered") in seed_rows

        run_rows = con.execute(
            """
            SELECT es.seed_value, sr.loop_name, sr.status
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND sr.loop_name='fanout_l_seed_phone'
            """
        ).fetchall()
        run_map = {(str(row[0]), str(row[1])): str(row[2]) for row in run_rows}
        assert run_map[("+15559876543", "fanout_l_seed_phone")] == "completed"
        assert run_map[("+15552223333", "fanout_l_seed_phone")] == "completed"
        assert run_map[("+15550004444", "fanout_l_seed_phone")] == "completed"
        assert run_map[("+15550005555", "fanout_l_seed_phone")] == "completed"
    finally:
        con.close()

    assert "https://acme.example" in fetched_urls
    assert "http://acme.example" in fetched_urls


