def test_artifact_queue_processor_keeps_redacted_key_rows_when_engagement_key_missing(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.delenv("FORGE_ENGAGEMENT_KEY", raising=False)
    monkeypatch.setattr(
        "forge.engagement_orchestrator._encrypt_secret_material",
        lambda _value: (_ for _ in ()).throw(RuntimeError("missing engagement key")),
    )
    db_path = tmp_path / "engagement.db"
    _bootstrap_engagement(db_path)

    artifact_root = tmp_path / "artifacts"
    artifact_root.mkdir()
    slack_token = "xoxb-12345678901-12345678901-AbCdEfGhIjKlMnOpQrStUvWx"
    google_key = "AIza" + "G" * 35
    (artifact_root / "operator-keys.env").write_text(
        dedent(
            f"""
            CONTACT_EMAIL=operator@acme.example
            PORTAL_URL=https://keys.acme.example/portal
            SLACK_BOT_TOKEN={slack_token}
            GOOGLE_API_KEY={google_key}
            """
        ).strip(),
        encoding="utf-8",
    )

    processor = ArtifactQueueProcessor(db_path, 1001)
    assert processor.ingest_local_artifacts([artifact_root]) == 1
    summary = processor.process()
    assert summary.processed == 1

    con = sqlite3.connect(db_path)
    try:
        rows = con.execute(
            """
            SELECT service, pattern_name, key_enc, key_redacted, validation_state, validation_detail, source_url
            FROM key_scanner_findings
            WHERE engagement_id=1001
            ORDER BY service, pattern_name
            """
        ).fetchall()
    finally:
        con.close()

    key_map = {(str(row[0]), str(row[1])): row for row in rows}
    assert ("google", "google_api_key") in key_map
    assert ("slack", "slack_bot_token") in key_map
    for row in key_map.values():
        assert row[2] is None
        assert str(row[4]) == "UNCONFIRMED"
        assert "FORGE_ENGAGEMENT_KEY" in str(row[5])
        assert str(row[6]).endswith("operator-keys.env")
        assert slack_token not in str(row[5])
        assert google_key not in str(row[5])


