    def _graphml_node_block(graphml: str, node_id: str) -> str:
        match = re.search(
            rf'<node id="{re.escape(node_id)}">(.*?)</node>',
            graphml,
            flags=re.DOTALL,
        )
        assert match is not None
        return match.group(1)

    def _assert_json_graph_seed_provenance(label: str, seed_type: str) -> dict[str, object]:
        node = graph_nodes_by_label.get(label)
        assert node is not None
        assert node["source_table"] == "engagement_seeds"
        assert int(node["source_id"]) > 0
        metadata = node.get("metadata")
        assert isinstance(metadata, dict)
        assert metadata["seed_type"] == seed_type
        assert metadata["source"]
        assert int(metadata["depth"]) >= 1
        return node

