@pytest.mark.slow
def test_kill_chain_local_long_tail_key_artifacts_feed_validation_and_auto_template_fallback(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")

    artifact_root = tmp_path / "data" / "artifacts"
    artifact_root.mkdir(parents=True, exist_ok=True)
    longtail_artifact_path = artifact_root / "operator-longtail.env"
    longtail_artifact_path.write_text(
        dedent(
            """
            CONTACT_EMAIL=longtail-owner@acme.example
            PORTAL_URL=https://longtail.acme.example/portal
            GITHUB_PAT=ghp_ABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890
            STRIPE_SECRET_KEY=sk_live_AbCdEfGhIjKlMnOpQrStUvWxYz1234567890ABCD
            SENDGRID_API_KEY=SG.ABCDEFGHIJKLMNOPQRSTUV.ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcdefg
            TWILIO_ACCOUNT_SID=AC6f8a2c9d4e1b73f5a0c8d2e9f4a6b1c3
            TWILIO_AUTH_TOKEN=abcdef1234567890abcdef1234567890
            """
        ).strip(),
        encoding="utf-8",
    )

    fetched_urls: list[str] = []

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        forge_index = argv.index("forge.cli")
        module_argv = [item for item in argv[forge_index + 1 :] if item != "--no-tor"]

        def _flag_value(flag: str) -> str | None:
            if flag not in module_argv:
                return None
            index = module_argv.index(flag)
            if index + 1 >= len(module_argv):
                return None
            return module_argv[index + 1]

        if module_argv[:2] == ["graph", "build"]:
            output_dir = Path(_flag_value("--output-dir") or "reports")
            output_dir.mkdir(parents=True, exist_ok=True)
            engagement_id = str(_flag_value("--engagement") or "1001")
            (output_dir / f"{engagement_id}_attack_graph.json").write_text(
                '{"nodes":[],"edges":[]}',
                encoding="utf-8",
            )
            (output_dir / f"{engagement_id}_attack_graph.graphml").write_text(
                "<?xml version='1.0'?><graphml></graphml>",
                encoding="utf-8",
            )
            (output_dir / f"{engagement_id}_attack_graph.mtgx").write_bytes(b"mtgx")
            return subprocess.CompletedProcess(argv, 0, stdout="graph built\n", stderr="")

        if module_argv[:2] == ["report", "generate"]:
            from forge.cli import report_generate  # noqa: PLC0415

            max_loops = _flag_value("--max-loops")
            report_generate(
                engagement=str(_flag_value("--engagement") or ""),
                output=_flag_value("--output"),
                yes=("--yes" in module_argv or "-y" in module_argv),
                provider=_flag_value("--provider") or "auto",
                max_loops=int(max_loops) if max_loops is not None else None,
            )
            return subprocess.CompletedProcess(argv, 0, stdout="report generated\n", stderr="")

        return subprocess.CompletedProcess(argv, 0, stdout="ok\n", stderr="")

    def _fake_html_batch(specs, *_args, **_kwargs):  # noqa: ANN001
        fetched_urls.extend(spec.url for spec in specs)
        return ["" for _ in specs]

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    monkeypatch.setattr("forge.cli._run_html_fetch_batch", _fake_html_batch)

    from forge.core.errors import ProviderUnavailableError  # noqa: PLC0415
    from forge.opsec.crypto import decrypt_string  # noqa: PLC0415
    from forge.phase4 import cloud_validate
    from forge.phase6.report_synthesizer import ReportSynthesizer  # noqa: PLC0415
    from forge.utils.intel.secret_finder import (  # noqa: PLC0415
        GithubPatValidator,
        SendgridKeyValidator,
        StripeKeyValidator,
        TwilioKeyValidator,
        ValidationResult,
        ValidationState,
    )

    def _safe_decrypt_secret(value: str | None) -> str | None:
        if not value:
            return None
        try:
            return decrypt_string(str(value))
        except Exception:  # noqa: BLE001
            return str(value).strip() or None

    monkeypatch.setattr(cloud_validate, "_decrypt_secret", _safe_decrypt_secret)
    monkeypatch.setattr(
        cloud_validate,
        "_resolve_twilio_auth_token",
        lambda db_path, row: "abcdef1234567890abcdef1234567890",  # noqa: ARG005
    )
    monkeypatch.setattr(ReportSynthesizer, "_ensure_provider_loaded", lambda self: None)
    monkeypatch.setattr(
        ReportSynthesizer,
        "_infer",
        lambda self, _prompt: (_ for _ in ()).throw(ProviderUnavailableError("rate limit")),
    )
    monkeypatch.setattr(
        GithubPatValidator,
        "validate",
        lambda self, key, proxy=None, **kwargs: ValidationResult(  # noqa: ARG005
            state=ValidationState.ACTIVE,
            detail=(
                "GitHub user ok: user_id=738251 login=acmebot user_profile_present=true "
                "profile_url_matches_login=true"
            ),
        ),
    )
    monkeypatch.setattr(
        StripeKeyValidator,
        "validate",
        lambda self, key, proxy=None, **kwargs: ValidationResult(  # noqa: ARG005
            state=ValidationState.ACTIVE,
            detail=(
                "Stripe balance accessible: mode=live currencies=sgd,usd "
                "balances=available:1,pending:1"
            ),
        ),
    )
    monkeypatch.setattr(
        SendgridKeyValidator,
        "validate",
        lambda self, key, proxy=None, **kwargs: ValidationResult(  # noqa: ARG005
            state=ValidationState.ACTIVE,
            detail=(
                "SendGrid profile ok: proof=profile profile_hash=0123456789abcdef "
                "email_present=true"
            ),
        ),
    )

    def _fake_twilio_validate(self, key, auth_token=None, proxy=None, **kwargs):  # noqa: ANN001, ARG001
        if (
            key == "AC6f8a2c9d4e1b73f5a0c8d2e9f4a6b1c3"
            and auth_token == "abcdef1234567890abcdef1234567890"
        ):
            return ValidationResult(
                state=ValidationState.ACTIVE,
                detail=(
                    "Twilio account accessible: sid=AC6f8a2c9d4e1b73f5a0c8d2e9f4a6b1c3 "
                    "status=active type=Full"
                ),
            )
        return ValidationResult(
            state=ValidationState.UNCONFIRMED,
            detail="Twilio auth token not co-located",
        )

    monkeypatch.setattr(TwilioKeyValidator, "validate", _fake_twilio_validate)

    from forge.cli import kill_chain

    kill_chain(
        seed="+15553334444",
        related_seed=[],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=False,
        attack_mode=False,
        skip_cloud=False,
        skip_keyscan=True,
        parallel_fanout=2,
        report_provider="auto",
        report_max_loops=0,
    )

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        emails = {
            str(row[0])
            for row in con.execute(
                """
                SELECT email
                FROM emails
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert "longtail-owner@acme.example" in emails

        key_rows = con.execute(
            """
            SELECT service, pattern_name, validation_state, validation_detail, source_url
            FROM key_scanner_findings
            WHERE engagement_id=1001
            ORDER BY service, pattern_name
            """
        ).fetchall()
        key_map = {(str(row[0]), str(row[1])): row for row in key_rows}
        assert key_map[("github", "github_pat_classic")]["validation_state"] == "ACTIVE"
        assert key_map[("stripe", "stripe_live_secret_key")]["validation_state"] == "ACTIVE"
        assert key_map[("sendgrid", "sendgrid_api_key")]["validation_state"] == "ACTIVE"
        assert key_map[("twilio", "twilio_account_sid")]["validation_state"] == "ACTIVE"
        assert key_map[("twilio", "twilio_auth_token")]["validation_state"] == "UNCONFIRMED"
        assert str(key_map[("github", "github_pat_classic")]["source_url"]).endswith(
            "operator-longtail.env"
        )

        validation_rows = con.execute(
            """
            SELECT asset_type, identifier, validation_status, validation_method
            FROM cloud_validation_results
            WHERE engagement_id=1001
            ORDER BY asset_type, identifier
            """
        ).fetchall()
        validation_map = {
            (str(row[0]), str(row[3]), str(row[2])): str(row[1]) for row in validation_rows
        }
        assert validation_map[("github", "github_user_api", "VALIDATED")] == "acmebot"
        assert (
            validation_map[("sendgrid", "sendgrid_profile_api", "VALIDATED")]
            == "profile/0123456789abcdef"
        )
        assert validation_map[("twilio", "twilio_account_api", "VALIDATED")] == (
            "AC6f8a2c9d4e1b73f5a0c8d2e9f4a6b1c3"
        )
        assert validation_map[("stripe", "stripe_balance_api", "VALIDATED")] == "live/sgd,usd"

        findings = {
            (str(row[0]), str(row[1]), str(row[2]))
            for row in con.execute(
                """
                SELECT vuln_type, severity, title
                FROM vulnerability_findings
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert (
            "DETERMINISTIC_KEY_EXPOSURE",
            "HIGH",
            "Validated exposed github credential reference",
        ) in findings
        assert (
            "DETERMINISTIC_KEY_EXPOSURE",
            "HIGH",
            "Validated exposed stripe credential reference",
        ) in findings
        assert (
            "DETERMINISTIC_KEY_EXPOSURE",
            "HIGH",
            "Validated exposed sendgrid credential reference",
        ) in findings
        assert (
            "DETERMINISTIC_KEY_EXPOSURE",
            "HIGH",
            "Validated exposed twilio credential reference",
        ) in findings
        assert all(row[0] != "DETERMINISTIC_CLOUD_EXPOSURE" for row in findings)

        email_run_row = con.execute(
            """
            SELECT sr.status
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND sr.loop_name='fanout_e_chain'
              AND es.seed_value='longtail-owner@acme.example'
            """
        ).fetchone()
        assert email_run_row is not None
        assert str(email_run_row[0]) == "completed"

        metadata_row = con.execute(
            """
            SELECT metadata_json
            FROM engagement_runs
            WHERE engagement_id=1001
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
        assert metadata_row is not None
        metadata = json.loads(str(metadata_row[0] or "{}"))
        assert (
            int(metadata.get("queue_metrics", {}).get("cloud_validation", {}).get("VALIDATED", 0))
            >= 4
        )
    finally:
        con.close()

    reports_dir = tmp_path / "reports"
    graphml_path = reports_dir / "1001_attack_graph.graphml"
    mtgx_path = reports_dir / "1001_attack_graph.mtgx"
    report_files = sorted(reports_dir.glob("engagement_1001_kill_chain_*.md"))

    assert graphml_path.is_file()
    assert mtgx_path.is_file()
    assert report_files

    report_path = report_files[-1]
    report_text = report_path.read_text(encoding="utf-8")
    report_json = report_path.with_suffix(".json").read_text(encoding="utf-8")

    assert "Validated exposed github credential reference" in report_text
    assert "Validated exposed stripe credential reference" in report_text
    assert "Validated exposed sendgrid credential reference" in report_text
    assert "Validated exposed twilio credential reference" in report_text
    assert "LLM fallback engaged: rate limit" in report_text
    assert '"provider": "template"' in report_json
    assert '"requested_provider": "auto"' in report_json
    assert '"fallback_reason": "rate limit"' in report_json
    assert report_path.with_suffix(".pdf").is_file()
    assert any("longtail.acme.example" in url for url in fetched_urls)


