    from forge.cli import kill_chain

    kill_chain(
        seed="+15550001111",
        related_seed=[],
        engagement="1001",
        max_iter=2,
        tor=False,
        dry_run=False,
        attack_mode=False,
        skip_cloud=False,
        skip_keyscan=True,
        parallel_fanout=2,
        report_provider="template",
    )

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        emails = {
            str(row[0])
            for row in con.execute(
                """
                SELECT email
                FROM emails
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert "yaml-owner@acme.example" in emails
        assert "rtf-owner@acme.example" in emails
        assert "nested-xapk-owner@acme.example" in emails
        assert "generic-owner@acme.example" in emails

        seeds = {
            (str(row[0]), str(row[1]))
            for row in con.execute(
                """
                SELECT seed_value, seed_type
                FROM engagement_seeds
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("yaml-owner@acme.example", "email") in seeds
        assert ("rtf-owner@acme.example", "email") in seeds
        assert ("nested-xapk-owner@acme.example", "email") in seeds
        assert ("generic-owner@acme.example", "email") in seeds
        assert ("https://yaml.acme.example/console", "url") in seeds
        assert ("https://rtf.acme.example/portal", "url") in seeds
        assert ("https://nestedxapk.acme.example/mobile", "url") in seeds
        assert ("https://keys.acme.example/portal", "url") in seeds
        assert ("https://dev.to/rtfblue/latest-post", "url") in seeds
        assert ("rtfblue", "username") in seeds

        cloud_assets = {
            (str(row[0]), str(row[1]))
            for row in con.execute(
                """
                SELECT asset_type, identifier
                FROM cloud_assets
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert ("firebase", "local-yaml-firebase") in cloud_assets
        assert ("firebase", "nested-xapk-firebase") in cloud_assets
        assert ("supabase", "localyamlref") in cloud_assets
        assert ("supabase", "nestedxapk") in cloud_assets
        assert ("gcs", "local-yaml-gcs") in cloud_assets
        assert ("azure_blob", "localyamlblob/public") in cloud_assets

        key_rows = con.execute(
            """
            SELECT service, pattern_name, validation_state, source_url
            FROM key_scanner_findings
            WHERE engagement_id=1001
            ORDER BY service, pattern_name
            """
        ).fetchall()
        key_map = {(str(row[0]), str(row[1])): row for row in key_rows}
        assert str(key_map[("aws", "aws_access_key_id")][2]) == "ACTIVE"
        assert str(key_map[("slack", "slack_bot_token")][2]) == "ACTIVE"
        assert str(key_map[("mailchimp", "mailchimp_api_key")][2]) == "UNCONFIRMED"
        assert str(key_map[("azure", "azure_storage_key")][2]) == "ACTIVE"
        assert str(key_map[("github", "github_pat_classic")][2]) == "ACTIVE"
        assert str(key_map[("stripe", "stripe_live_secret_key")][2]) == "ACTIVE"
        assert str(key_map[("sendgrid", "sendgrid_api_key")][2]) == "ACTIVE"
        assert str(key_map[("twilio", "twilio_account_sid")][2]) == "ACTIVE"
        assert str(key_map[("twilio", "twilio_auth_token")][2]) == "UNCONFIRMED"
        assert str(key_map[("sendgrid", "sendgrid_api_key")][3]).endswith("operator-keys.env")

        validation_rows = {
            (str(row[0]), str(row[1]), str(row[2]), str(row[3]))
            for row in con.execute(
                """
                SELECT asset_type, identifier, validation_status, validation_method
                FROM cloud_validation_results
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert (
            "firebase",
            "local-yaml-firebase",
            "VALIDATED",
            "firebase_database_shallow_read",
        ) in validation_rows
        assert (
            "firebase",
            "nested-xapk-firebase",
            "VALIDATED",
            "firebase_database_shallow_read",
        ) in validation_rows
        assert (
            "supabase",
            "localyamlref",
            "VALIDATED",
            "supabase_rest_root",
        ) in validation_rows
        assert (
            "supabase",
            "nestedxapk",
            "VALIDATED",
            "supabase_rest_root",
        ) in validation_rows
        assert (
            "gcs",
            "local-yaml-gcs",
            "VALIDATED",
            "gcs_list_bucket",
        ) in validation_rows
        assert (
            "azure_blob",
            "localyamlblob/public",
            "VALIDATED",
            "azure_blob_list_container",
        ) in validation_rows
        assert any(
            asset_type == "aws"
            and validation_status == "VALIDATED"
            and validation_method == "aws_sts_get_caller_identity"
            for asset_type, _identifier, validation_status, validation_method in validation_rows
        )
        assert any(
            asset_type == "slack"
            and validation_status == "VALIDATED"
            and validation_method == "slack_auth_test"
            for asset_type, _identifier, validation_status, validation_method in validation_rows
        )
        assert (
            "mailchimp",
            "us1",
            "UNVERIFIED",
            "mailchimp_ping_api",
        ) in validation_rows
        assert (
            "azure",
            "localkeyblob",
            "VALIDATED",
            "azure_blob_list_containers_shared_key",
        ) in validation_rows

        findings = {
            (str(row[0]), str(row[1]), str(row[2]))
            for row in con.execute(
                """
                SELECT vuln_type, severity, title
                FROM vulnerability_findings
                WHERE engagement_id=1001
                """
            ).fetchall()
        }
        assert (
            "DETERMINISTIC_CLOUD_EXPOSURE",
            "HIGH",
            "Validated Firebase data exposure",
        ) in findings
        assert (
            "DETERMINISTIC_CLOUD_EXPOSURE",
            "HIGH",
            "Validated Supabase data exposure",
        ) in findings
        assert (
            "DETERMINISTIC_CLOUD_EXPOSURE",
            "HIGH",
            "Validated public Google Cloud Storage bucket listing exposure",
        ) in findings
        assert (
            "DETERMINISTIC_KEY_EXPOSURE",
            "HIGH",
            "Validated exposed aws credential reference",
        ) in findings
        assert (
            "DETERMINISTIC_KEY_EXPOSURE",
            "HIGH",
            "Validated exposed slack credential reference",
        ) in findings
        assert (
            "DETERMINISTIC_KEY_EXPOSURE",
            "HIGH",
            "Validated exposed mailchimp credential reference",
        ) not in findings
        assert (
            "DETERMINISTIC_KEY_EXPOSURE",
            "HIGH",
            "Validated exposed azure credential reference",
        ) in findings

        run_rows = con.execute(
            """
            SELECT es.seed_value, sr.loop_name, sr.status
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND sr.loop_name='fanout_e_chain'
            """
        ).fetchall()
        run_map = {(str(row[0]), str(row[1])): str(row[2]) for row in run_rows}
        assert run_map[("yaml-owner@acme.example", "fanout_e_chain")] == "completed"
        assert run_map[("nested-xapk-owner@acme.example", "fanout_e_chain")] == "completed"

        metadata_row = con.execute(
            """
            SELECT metadata_json
            FROM engagement_runs
            WHERE engagement_id=1001
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
        assert metadata_row is not None
        metadata = json.loads(str(metadata_row[0] or "{}"))
        assert (
            int(metadata.get("queue_metrics", {}).get("cloud_validation", {}).get("VALIDATED", 0))
            >= 8
        )
    finally:
        con.close()

    reports_dir = tmp_path / "reports"
    report_files = sorted(reports_dir.glob("engagement_*.md"))
    assert report_files
    report_path = report_files[-1]
    report_text = report_path.read_text(encoding="utf-8")
    assert report_text.count("Validated Firebase data exposure") >= 2
    assert report_text.count("Validated Supabase data exposure") >= 2
    assert "Validated public Google Cloud Storage bucket listing exposure" in report_text
    assert "Validated public Azure Blob container listing exposure" in report_text
    assert "Validated exposed aws credential reference" in report_text
    assert "Validated exposed slack credential reference" in report_text
    assert "Validated exposed mailchimp credential reference" not in report_text
    assert "Validated exposed azure credential reference" in report_text
    assert "### 5.2 Finding details" in report_text
    assert "- **Provider**: firebase" in report_text
    assert "- **Provider**: azure" in report_text
    assert "- **Asset**: firebase://local-yaml-firebase" in report_text
    assert "- **Asset**: azure_blob://localyamlblob/public" in report_text
    assert "template mode, no LLM" in report_text
    assert report_path.with_suffix(".json").is_file()
    assert report_path.with_suffix(".pdf").is_file()

    graph_json_files = sorted(reports_dir.glob("*_attack_graph.json"))
    graph_mtgx_files = sorted(reports_dir.glob("*_attack_graph.mtgx"))
    assert graph_json_files
    assert graph_mtgx_files

    assert "https://yaml.acme.example" in fetched_urls
    assert "http://yaml.acme.example" in fetched_urls
    assert "https://rtf.acme.example" in fetched_urls
    assert "https://nestedxapk.acme.example" in fetched_urls
    assert "https://keys.acme.example" in fetched_urls


