    class _FakeResponse:
        def __init__(
            self, status_code: int, text: str, content_type: str = "application/json"
        ) -> None:
            self.status_code = status_code
            self.text = text
            self.headers = {"content-type": content_type}

    class _BroaderMixedCloudClient:
        def __init__(self, *args, **kwargs) -> None:  # noqa: ANN002, ANN003
            del args, kwargs

        def __enter__(self) -> "_BroaderMixedCloudClient":
            return self

        def __exit__(self, exc_type, exc, tb) -> None:  # noqa: ANN001
            del exc_type, exc, tb

        def close(self) -> None:
            return None

        def get(self, url: str, **kwargs):  # noqa: ANN003
            del kwargs
            if url == "https://local-yaml-firebase.firebaseio.com/.json":
                return _FakeResponse(200, '{"records":[{"id":1,"record":"yaml-db"}]}')
            if url == "https://nested-xapk-firebase.firebaseio.com/.json":
                return _FakeResponse(200, '{"users":[{"id":2,"record":"nested-xapk-db"}]}')
            if url == "https://localyamlref.supabase.co/auth/v1/settings":
                return _FakeResponse(
                    200,
                    '{"site_url":"https://portal.acme.io","external_email_enabled":true,"mailer_autoconfirm":false}',
                )
            if url == "https://localyamlref.supabase.co/rest/v1/":
                return _FakeResponse(200, '[{"id":1,"record":"yaml-supabase"}]')
            if url == "https://nestedxapk.supabase.co/auth/v1/settings":
                return _FakeResponse(
                    200,
                    '{"site_url":"https://mobile.acme.io","external_email_enabled":true,"mailer_autoconfirm":false}',
                )
            if url == "https://nestedxapk.supabase.co/rest/v1/":
                return _FakeResponse(200, '[{"id":2,"record":"nested-supabase"}]')
            if url == "https://storage.googleapis.com/local-yaml-gcs":
                return _FakeResponse(
                    200,
                    (
                        "<?xml version='1.0' encoding='UTF-8'?>"
                        "<ListBucketResult><Contents><Key>exports/final.csv</Key></Contents></ListBucketResult>"
                    ),
                    "application/xml",
                )
            if url == "https://localyamlblob.blob.core.windows.net/public":
                return _FakeResponse(
                    200,
                    (
                        "<?xml version='1.0' encoding='utf-8'?>"
                        "<EnumerationResults><Blobs><Blob><Name>reports/final.pdf</Name></Blob></Blobs></EnumerationResults>"
                    ),
                    "application/xml",
                )
            if url == "https://api.stripe.com/v1/balance":
                return _FakeResponse(
                    200,
                    '{"object":"balance","livemode":true,'
                    '"available":[{"currency":"sgd"}],'
                    '"pending":[{"currency":"usd"}]}',
                )
            return _FakeResponse(404, "missing")

        def head(self, url: str, **kwargs):  # noqa: ANN003
            return self.get(url, **kwargs)

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        try:
            forge_index = argv.index("forge.cli")
        except ValueError:
            forge_index = -1
        module_argv = argv[forge_index + 1 :] if forge_index >= 0 else argv
        module_argv = [item for item in module_argv if item != "--no-tor"]

        if "--engagement" in module_argv:
            engagement = module_argv[module_argv.index("--engagement") + 1]
            target_db = tmp_path / ".forge_data" / "engagements" / f"{engagement}.db"
        else:
            target_db = db_path

        def _flag_value(flag: str) -> str | None:
            if flag not in module_argv:
                return None
            index = module_argv.index(flag)
            if index + 1 >= len(module_argv):
                return None
            return module_argv[index + 1]

        if module_argv[:2] == ["osint", "usernames"] and "--usernames" in module_argv:
            usernames = {
                item.strip().lstrip("@").lower()
                for item in module_argv[module_argv.index("--usernames") + 1].split(",")
                if item.strip()
            }
            if "rtfblue" in usernames:
                con = sqlite3.connect(target_db)
                try:
                    _ensure_social_profiles(con)
                    con.execute(
                        """
                        INSERT OR IGNORE INTO social_profiles (engagement_id, email, source, profile_data)
                        VALUES (?, ?, ?, ?)
                        """,
                        (
                            1001,
                            "username:rtfblue",
                            "sherlock",
                            json.dumps(
                                {
                                    "source": "sherlock",
                                    "platform": "github",
                                    "handle": "ops-root",
                                    "phone": "+15550001111",
                                    "display_name": "Alice Example",
                                }
                            ),
                        ),
                    )
                    con.execute(
                        """
                        INSERT OR IGNORE INTO social_profiles (engagement_id, email, source, profile_data)
                        VALUES (?, ?, ?, ?)
                        """,
                        (
                            1001,
                            "username:rtfblue",
                            "linkedin",
                            json.dumps(
                                {
                                    "source": "linkedin",
                                    "platform": "linkedin",
                                    "company": "Acme Corp",
                                    "profile_url": "https://www.threads.net/@threadblue",
                                }
                            ),
                        ),
                    )
                    con.commit()
                finally:
                    con.close()
            if "alicebucket" in usernames:
                con = sqlite3.connect(target_db)
                try:
                    _ensure_social_profiles(con)
                    con.execute(
                        """
                        INSERT OR IGNORE INTO social_profiles (engagement_id, email, source, profile_data)
                        VALUES (?, ?, ?, ?)
                        """,
                        (
                            1001,
                            "username:alicebucket",
                            "sherlock",
                            json.dumps(
                                {
                                    "source": "sherlock",
                                    "platform": "github",
                                    "handle": "relayblue",
                                    "display_name": "Relay Example",
                                    "company": "Blue Relay LLC",
                                }
                            ),
                        ),
                    )
                    con.commit()
                finally:
                    con.close()

        if module_argv[:2] == ["osint", "name"] and "--name" in module_argv:
            searched_name = module_argv[module_argv.index("--name") + 1]
            if searched_name == "Alice Example":
                con = sqlite3.connect(target_db)
                try:
                    _ensure_social_profiles(con)
                    con.execute(
                        """
                        INSERT OR IGNORE INTO social_profiles (engagement_id, email, source, profile_data)
                        VALUES (?, ?, ?, ?)
                        """,
                        (
                            1001,
                            "name:Alice Example",
                            "name_search:bitbucket:alicebucket",
                            json.dumps(
                                {
                                    "source": "name_search",
                                    "platform": "bitbucket",
                                    "handle": "alicebucket",
                                    "name": "Alice Example",
                                }
                            ),
                        ),
                    )
                    con.commit()
                finally:
                    con.close()

        if module_argv[:2] == ["graph", "build"]:
            from forge.cli import graph_build  # noqa: PLC0415

            graph_build(
                engagement=str(_flag_value("--engagement") or ""),
                fmt=str(_flag_value("--format") or "json"),
                output_dir=_flag_value("--output-dir"),
                min_severity=str(_flag_value("--min-severity") or "LOW"),
                critical_path_only="--critical-path-only" in module_argv,
                snapshot="--snapshot" in module_argv,
                max_nodes=int(_flag_value("--max-nodes") or "150"),
            )
            return subprocess.CompletedProcess(argv, 0, stdout="graph built\n", stderr="")

        if module_argv[:2] == ["report", "generate"]:
            from forge.cli import report_generate  # noqa: PLC0415

            max_loops = _flag_value("--max-loops")
            report_generate(
                engagement=str(_flag_value("--engagement") or ""),
                output=_flag_value("--output"),
                yes=("--yes" in module_argv or "-y" in module_argv),
                provider=_flag_value("--provider") or "auto",
                max_loops=int(max_loops) if max_loops is not None else None,
            )
            return subprocess.CompletedProcess(argv, 0, stdout="report generated\n", stderr="")

        return subprocess.CompletedProcess(argv, 0, stdout="ok\n", stderr="")

    def _fake_html_batch(specs, *_args, **_kwargs):  # noqa: ANN001
        fetched_urls.extend(spec.url for spec in specs)
        payloads: list[str] = []
        for spec in specs:
            if spec.url == "https://yaml.acme.example/console":
                payloads.append(
                    "<html><a href='mailto:html-owner@acme.example'>mail</a>"
                    "<a href='https://www.threads.net/@threadblue'>thread</a></html>"
                )
            else:
                payloads.append("")
        return payloads

    def _fake_callable_batch(
        items, worker, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del worker, max_workers

        def _emit(completed: int) -> None:
            if progress_callback is None or not progress_label:
                return
            progress_callback(
                progress_label,
                {
                    "total": len(items),
                    "workers": min(1, len(items)) if items else 0,
                    "running": 0,
                    "pending": max(0, len(items) - completed),
                    "queue_depth": max(0, len(items) - completed),
                    "completed": completed,
                    "failed": 0,
                    "eta_seconds": 0.0,
                },
            )

        _emit(0)
        if progress_label in {
            "1.G DNS enrichment",
            "2.G DNS enrichment",
            "3.G DNS enrichment",
            "4.G DNS enrichment",
        }:
            results = [
                {
                    "root_domain": str(item),
                    "queried_hosts": [str(item)],
                    "cname_targets": [],
                    "signals": [],
                }
                for item in items
            ]
        elif progress_label in {
            "1.H whois/RDAP",
            "2.H whois/RDAP",
            "3.H whois/RDAP",
            "4.H whois/RDAP",
        }:
            results = [{"root_domain": str(item), "rdap": {}} for item in items]
        elif progress_label in {
            "1.I Wayback CDX",
            "2.I Wayback CDX",
            "3.I Wayback CDX",
            "4.I Wayback CDX",
        }:
            results = [{"root_domain": str(item), "urls": []} for item in items]
        else:
            raise AssertionError(f"unexpected callable batch label: {progress_label}")
        _emit(len(items))
        return results

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    monkeypatch.setattr("forge.cli._run_html_fetch_batch", _fake_html_batch)
    monkeypatch.setattr("forge.cli._run_callable_batch", _fake_callable_batch)

