    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        forge_index = argv.index("forge.cli")
        module_argv = [item for item in argv[forge_index + 1 :] if item != "--no-tor"]

        def _flag_value(flag: str) -> str | None:
            if flag not in module_argv:
                return None
            index = module_argv.index(flag)
            if index + 1 >= len(module_argv):
                return None
            return module_argv[index + 1]

        if module_argv[:2] == ["graph", "build"]:
            from forge.cli import graph_build  # noqa: PLC0415

            graph_build(
                engagement=str(_flag_value("--engagement") or ""),
                fmt=str(_flag_value("--format") or "json"),
                output_dir=_flag_value("--output-dir"),
                min_severity=str(_flag_value("--min-severity") or "LOW"),
                critical_path_only="--critical-path-only" in module_argv,
                snapshot="--snapshot" in module_argv,
                max_nodes=int(_flag_value("--max-nodes") or "150"),
            )
            return subprocess.CompletedProcess(argv, 0, stdout="graph built\n", stderr="")

        if module_argv[:2] == ["report", "generate"]:
            from forge.cli import report_generate  # noqa: PLC0415

            max_loops = _flag_value("--max-loops")
            report_generate(
                engagement=str(_flag_value("--engagement") or ""),
                output=_flag_value("--output"),
                yes=("--yes" in module_argv or "-y" in module_argv),
                provider=_flag_value("--provider") or "auto",
                max_loops=int(max_loops) if max_loops is not None else None,
            )
            return subprocess.CompletedProcess(argv, 0, stdout="report generated\n", stderr="")

        return subprocess.CompletedProcess(argv, 0, stdout="ok\n", stderr="")

    def _fake_html_batch(specs, *_args, progress_label=None, **_kwargs):  # noqa: ANN001
        fetched_urls.extend(spec.url for spec in specs)
        if progress_label == "1.D cloud+HTML fetch":
            return [root_html if spec.url == "https://acme.example" else "" for spec in specs]
        if progress_label == "1.D2 passive text fetch":
            return ["" for _ in specs]
        if progress_label == "1.D5 URL surface fetch":
            page_map = {
                careers_url: careers_html,
                downloads_url: downloads_html,
            }
            return [page_map.get(spec.url, "") for spec in specs]
        if progress_label == "2.D cloud+HTML fetch":
            return ["" for _ in specs]
        if progress_label == "2.D2 passive text fetch":
            return ["" for _ in specs]
        if progress_label == "2.D5 URL surface fetch":
            page_map = {
                mobile_hub_url: mobile_hub_html,
                archive_hub_url: archive_hub_html,
            }
            return [page_map.get(spec.url, "") for spec in specs]
        if progress_label in {
            "3.D cloud+HTML fetch",
            "3.D2 passive text fetch",
            "3.D5 URL surface fetch",
        }:
            return ["" for _ in specs]
        raise AssertionError(f"unexpected html batch label: {progress_label}")

    def _fake_callable_batch(
        items, worker, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del worker, max_workers

        def _emit(completed: int) -> None:
            if progress_callback is None or not progress_label:
                return
            progress_callback(
                progress_label,
                {
                    "total": len(items),
                    "workers": min(1, len(items)) if items else 0,
                    "running": 0,
                    "pending": max(0, len(items) - completed),
                    "queue_depth": max(0, len(items) - completed),
                    "completed": completed,
                    "failed": 0,
                    "eta_seconds": 0.0,
                },
            )

        _emit(0)
        if progress_label in {"1.G DNS enrichment", "2.G DNS enrichment", "3.G DNS enrichment"}:
            results = [
                {
                    "root_domain": str(item),
                    "queried_hosts": [str(item)],
                    "cname_targets": [],
                    "signals": [],
                }
                for item in items
            ]
        elif progress_label in {"1.H whois/RDAP", "2.H whois/RDAP", "3.H whois/RDAP"}:
            results = [{"root_domain": str(item), "rdap": {}} for item in items]
        elif progress_label in {"1.I Wayback CDX", "2.I Wayback CDX", "3.I Wayback CDX"}:
            results = [{"root_domain": str(item), "urls": []} for item in items]
        else:
            raise AssertionError(f"unexpected callable batch label: {progress_label}")
        _emit(len(items))
        return results

    def _write_remote_mobile_artifact(
        path: Path,
        *,
        firebase_project: str,
        supabase_ref: str,
        owner_email: str,
        portal_url: str,
    ) -> None:
        with zipfile.ZipFile(path, "w") as zf:
            zf.writestr(
                "google-services.json",
                json.dumps(
                    {
                        "project_info": {
                            "project_id": firebase_project,
                            "firebase_url": f"https://{firebase_project}.firebaseio.com",
                        }
                    }
                ),
            )
            zf.writestr(
                "assets/runtime.env",
                "\n".join(
                    [
                        f"SUPABASE_URL=https://{supabase_ref}.supabase.co",
                        (
                            "SUPABASE_ANON_KEY="
                            "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9."
                            f"eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Ii{supabase_ref}Iiwicm9sZSI6ImFub24ifQ."
                            "signaturechain"
                        ),
                        f"CONTACT_EMAIL={owner_email}",
                        f"PORTAL_URL={portal_url}",
                    ]
                ),
            )

    def _fake_download_request(_self, request: ArtifactDownloadResult | object):  # noqa: ANN001
        cache_dir = tmp_path / "remote-artifacts"
        cache_dir.mkdir(parents=True, exist_ok=True)
        if request.source_url == artifact_url_one:
            apk_path = cache_dir / "chain-one.apk"
            if not apk_path.exists():
                _write_remote_mobile_artifact(
                    apk_path,
                    firebase_project="chain-one-firebase",
                    supabase_ref="chainone",
                    owner_email="chain-one-owner@acme.example",
                    portal_url="https://chain-one-portal.acme.io/mobile",
                )
            return ArtifactDownloadResult(
                artifact_id=request.artifact_id,
                source_url=request.source_url,
                artifact_type=request.artifact_type,
                path=apk_path,
                metadata_extra={
                    "content_type": "application/vnd.android.package-archive",
                    "download_filename": apk_path.name,
                },
            )
        if request.source_url == artifact_url_two:
            apk_path = cache_dir / "chain-two.apk"
            if not apk_path.exists():
                _write_remote_mobile_artifact(
                    apk_path,
                    firebase_project="chain-two-firebase",
                    supabase_ref="chaintwo",
                    owner_email="chain-two-owner@acme.example",
                    portal_url="https://chain-two-portal.acme.io/mobile",
                )
            return ArtifactDownloadResult(
                artifact_id=request.artifact_id,
                source_url=request.source_url,
                artifact_type=request.artifact_type,
                path=apk_path,
                metadata_extra={
                    "content_type": "application/vnd.android.package-archive",
                    "download_filename": apk_path.name,
                },
            )
        raise AssertionError(f"unexpected remote artifact request: {request.source_url}")

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)
    monkeypatch.setattr("forge.cli._run_html_fetch_batch", _fake_html_batch)
    monkeypatch.setattr("forge.cli._run_callable_batch", _fake_callable_batch)
    monkeypatch.setattr(
        ArtifactQueueProcessor,
        "_download_remote_artifact_request",
        _fake_download_request,
    )

    from forge.core.errors import ProviderUnavailableError  # noqa: PLC0415
    from forge.phase4 import cloud_validate
    from forge.phase4.mobile_config_parse import FirebaseExtractor  # noqa: PLC0415
    from forge.phase6.report_synthesizer import ReportSynthesizer  # noqa: PLC0415

