def test_kill_chain_continues_when_synthesis_only_grows_seed_graph(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    call_state = {"count": 0}

    def _synthesis_with_seed_graph_growth(self) -> SynthesisSummary:  # noqa: ANN001
        call_state["count"] += 1
        if call_state["count"] != 2:
            return SynthesisSummary()

        con = sqlite3.connect(db_path)
        try:
            phone_seed_id = con.execute(
                """
                SELECT id
                FROM engagement_seeds
                WHERE engagement_id=1001 AND seed_type='phone' AND seed_value='+15559876543'
                """
            ).fetchone()
            assert phone_seed_id is not None

            con.execute(
                """
                INSERT OR IGNORE INTO engagement_seeds
                    (engagement_id, seed_value, seed_type, source, status, depth, confidence, metadata_json)
                VALUES
                    (1001, '@ghostops', 'username', 'cross_reference', 'pending', 2, 0.83, '{}')
                """
            )
            username_seed_id = con.execute(
                """
                SELECT id
                FROM engagement_seeds
                WHERE engagement_id=1001 AND seed_type='username' AND seed_value='@ghostops'
                """
            ).fetchone()
            assert username_seed_id is not None

            con.execute(
                """
                INSERT OR IGNORE INTO seed_relations
                    (engagement_id, source_seed_id, target_seed_id, relation_type, confidence, evidence_json)
                VALUES
                    (1001, ?, ?, 'same_entity', 0.74, '{"rule":"synthetic_test"}')
                """,
                (int(phone_seed_id[0]), int(username_seed_id[0])),
            )
            con.commit()
        finally:
            con.close()
        return SynthesisSummary(seeds_inserted=1, relations_inserted=1)

    monkeypatch.setattr(
        "forge.engagement_orchestrator.EngagementSynthesisEngine.run",
        _synthesis_with_seed_graph_growth,
    )

    from forge.cli import kill_chain

    kill_chain(
        seed="+15559876543",
        related_seed=[],
        engagement="1001",
        max_iter=2,
        tor=False,
        dry_run=True,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
    )

    con = sqlite3.connect(db_path)
    try:
        rows = con.execute(
            """
            SELECT es.seed_value, sr.loop_name, sr.status
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND sr.loop_name IN ('fanout_l_seed_phone', 'fanout_k_seed_username')
            ORDER BY sr.loop_name, es.seed_value
            """
        ).fetchall()
        run_map = {(row[0], row[1]): row[2] for row in rows}
        assert run_map[("+15559876543", "fanout_l_seed_phone")] == "skipped"
        assert run_map[("@ghostops", "fanout_k_seed_username")] == "skipped"

        run_row = con.execute(
            """
            SELECT current_iteration, max_iterations
            FROM engagement_runs
            WHERE engagement_id=1001
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
        assert run_row is not None
        assert int(run_row[0]) == 2
        assert int(run_row[1]) == 2
    finally:
        con.close()


def test_kill_chain_classifies_company_seed_and_routes_company_fanout(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")

    from forge.cli import kill_chain

    kill_chain(
        seed="Acme Corp",
        related_seed=[],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=True,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
    )

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    con = sqlite3.connect(db_path)
    try:
        run_row = con.execute(
            """
            SELECT seed_type
            FROM engagement_runs
            WHERE engagement_id=1001
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
        assert run_row is not None
        assert run_row[0] == "company"

        seed_run_row = con.execute(
            """
            SELECT es.seed_value, sr.status
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001 AND sr.loop_name='fanout_n_seed_company'
            ORDER BY sr.id DESC
            LIMIT 1
            """
        ).fetchone()
        assert seed_run_row == ("Acme Corp", "skipped")
    finally:
        con.close()


def test_kill_chain_parallel_batches_recursive_seed_and_instagram_fanouts(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    db_path.parent.mkdir(parents=True, exist_ok=True)
    _bootstrap_engagement(db_path)

    con = sqlite3.connect(db_path)
    try:
        con.execute(
            """
            CREATE TABLE IF NOT EXISTS social_profiles (
                id INTEGER PRIMARY KEY,
                engagement_id INTEGER NOT NULL,
                email TEXT NOT NULL,
                source TEXT NOT NULL DEFAULT 'instagram',
                profile_data TEXT,
                queried_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(engagement_id, email, source)
            )
            """
        )
        con.executemany(
            """
            INSERT INTO social_profiles (engagement_id, email, source, profile_data)
            VALUES (?, ?, ?, ?)
            """,
            [
                (
                    1001,
                    "alpha@acme.example",
                    "instagram",
                    json.dumps({"source": "instagram", "handle": "alphaig"}),
                ),
                (
                    1001,
                    "beta@acme.example",
                    "instagram",
                    json.dumps({"source": "instagram", "handle": "betaig"}),
                ),
            ],
        )
        con.commit()
    finally:
        con.close()

    batch_calls: list[tuple[tuple[str, ...], int]] = []
    parse_batch_calls: list[tuple[str, int, int]] = []

    def _fake_batch(specs, run_module, *, max_workers, progress_label=None, progress_callback=None):  # noqa: ANN001
        del run_module, progress_label, progress_callback
        batch_calls.append((tuple(spec.label for spec in specs), int(max_workers)))
        return [0] * len(specs)

    def _fake_inprocess_batch(
        items, worker, *, max_workers, progress_label=None, progress_callback=None
    ):  # noqa: ANN001
        del progress_callback
        parse_batch_calls.append((str(progress_label or ""), len(items), int(max_workers)))
        return [worker(item) for item in items]

    monkeypatch.setattr("forge.cli._run_inprocess_batch", _fake_inprocess_batch)
    monkeypatch.setattr("forge.cli._run_module_batch", _fake_batch)

    from forge.cli import kill_chain

    kill_chain(
        seed="@primeuser",
        related_seed=[
            "@sec-alt",
            "@betauser",
            "+15550000001",
            "+15550000002",
            "Alice Example",
            "Bob Example",
            "Acme Corp",
            "Orbit LLC",
        ],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=True,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
        parallel_fanout=3,
    )

    batch_label_sets = [labels for labels, _ in batch_calls]
    assert any(
        labels
        == (
            "1.E5 sherlock (@alphaig)",
            "1.E5 sherlock (@betaig)",
        )
        for labels in batch_label_sets
    )
    assert any(
        labels
        == (
            "1.E5.5 instagram (@alphaig)",
            "1.E5.5 instagram (@betaig)",
        )
        for labels in batch_label_sets
    )
    assert any(
        label == "1.E5 sherlock spec prep" and max_workers == 3 and item_count >= 2
        for label, item_count, max_workers in parse_batch_calls
    )
    assert any(
        label == "1.E5.5 instagram spec prep" and max_workers == 3 and item_count >= 2
        for label, item_count, max_workers in parse_batch_calls
    )
    assert any(
        {
            "1.K username fan-out (betauser)",
            "1.K username fan-out (primeuser)",
            "1.K username fan-out (sec-alt)",
        }
        == set(labels)
        for labels in batch_label_sets
    )
    assert any(
        {
            "1.L phone fan-out (+15550000001)",
            "1.L phone fan-out (+15550000002)",
        }.issubset(set(labels))
        for labels in batch_label_sets
    )
    assert any(
        labels
        == (
            "1.M name fan-out (Alice Example)",
            "1.M name fan-out (Bob Example)",
        )
        for labels in batch_label_sets
    )
    assert any(
        labels
        == (
            "1.N company fan-out (Acme Corp)",
            "1.N company fan-out (Orbit LLC)",
        )
        for labels in batch_label_sets
    )
    assert all(
        max_workers == 1
        if any(
            marker in label
            for label in labels
            for marker in ("emailrep", "instagram", "gravatar", "ghunt google")
        )
        else max_workers == 3
        for labels, max_workers in batch_calls
    )


