def test_kill_chain_persists_localpart_username_pivots_with_email_provenance(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    db_path.parent.mkdir(parents=True, exist_ok=True)
    _bootstrap_engagement(db_path)

    from forge.cli import kill_chain

    kill_chain(
        seed="alice.smith@acme.example",
        related_seed=[],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=True,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
        parallel_fanout=2,
    )

    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        seed_rows = con.execute(
            """
            SELECT seed_value, seed_type, source, depth
            FROM engagement_seeds
            WHERE engagement_id=1001
              AND seed_type IN ('email', 'username')
            ORDER BY seed_type, seed_value
            """
        ).fetchall()
        seed_map = {(str(row["seed_value"]), str(row["seed_type"])): row for row in seed_rows}

        assert ("alicesmith", "username") in seed_map
        assert str(seed_map[("alicesmith", "username")]["source"]) == "cross_reference"
        assert int(seed_map[("alicesmith", "username")]["depth"]) == 2

        relation_row = con.execute(
            """
            SELECT
                source.seed_value AS source_seed_value,
                target.seed_value AS target_seed_value,
                sr.relation_type AS relation_type,
                sr.evidence_json AS evidence_json
            FROM seed_relations sr
            JOIN engagement_seeds source ON source.id=sr.source_seed_id
            JOIN engagement_seeds target ON target.id=sr.target_seed_id
            WHERE sr.engagement_id=1001
              AND source.seed_value='alice.smith@acme.example'
              AND source.seed_type='email'
              AND target.seed_value='alicesmith'
              AND target.seed_type='username'
            """
        ).fetchone()
        assert relation_row is not None
        assert str(relation_row["relation_type"]) == "derived_from"
        assert (
            json.loads(str(relation_row["evidence_json"] or "{}"))["rule"]
            == "email_localpart_username"
        )

        run_rows = con.execute(
            """
            SELECT es.seed_value, sr.loop_name, sr.status
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND sr.loop_name='fanout_e_sherlock_localpart'
            """
        ).fetchall()
        run_map = {(str(row[0]), str(row[1])): str(row[2]) for row in run_rows}
        assert run_map[("alicesmith", "fanout_e_sherlock_localpart")] == "skipped"
    finally:
        con.close()


def test_kill_chain_multi_iteration_recurses_social_profile_seeds_without_live_network(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"

    def _ensure_social_profiles(con: sqlite3.Connection) -> None:
        con.execute(
            """
            CREATE TABLE IF NOT EXISTS social_profiles (
                id INTEGER PRIMARY KEY,
                engagement_id INTEGER NOT NULL,
                email TEXT NOT NULL,
                source TEXT NOT NULL DEFAULT 'instagram',
                profile_data TEXT,
                queried_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(engagement_id, email, source)
            )
            """
        )

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        try:
            forge_index = argv.index("forge.cli")
        except ValueError:
            forge_index = -1
        module_argv = argv[forge_index + 1 :] if forge_index >= 0 else argv
        module_argv = [item for item in module_argv if item != "--no-tor"]

        if "--engagement" in module_argv:
            engagement = module_argv[module_argv.index("--engagement") + 1]
            target_db = tmp_path / ".forge_data" / "engagements" / f"{engagement}.db"
        else:
            target_db = db_path

        if module_argv[:2] == ["osint", "usernames"] and "--usernames" in module_argv:
            usernames = {
                item.strip().lstrip("@").lower()
                for item in module_argv[module_argv.index("--usernames") + 1].split(",")
                if item.strip()
            }
            if "rootuser" in usernames:
                con = sqlite3.connect(target_db)
                try:
                    _ensure_social_profiles(con)
                    con.execute(
                        """
                        INSERT OR IGNORE INTO social_profiles (engagement_id, email, source, profile_data)
                        VALUES (?, ?, ?, ?)
                        """,
                        (
                            1001,
                            "username:rootuser",
                            "sherlock",
                            json.dumps(
                                {
                                    "source": "sherlock",
                                    "platform": "github",
                                    "handle": "ops-root",
                                    "phone": "+15550001111",
                                    "display_name": "Alice Example",
                                }
                            ),
                        ),
                    )
                    con.execute(
                        """
                        INSERT OR IGNORE INTO social_profiles (engagement_id, email, source, profile_data)
                        VALUES (?, ?, ?, ?)
                        """,
                        (
                            1001,
                            "username:rootuser",
                            "linkedin",
                            json.dumps(
                                {
                                    "source": "linkedin",
                                    "platform": "linkedin",
                                    "company": "Acme Corp",
                                }
                            ),
                        ),
                    )
                    con.commit()
                finally:
                    con.close()

        if module_argv[:2] == ["report", "generate"] and "--output" in module_argv:
            report_path = tmp_path / module_argv[module_argv.index("--output") + 1]
            report_path.parent.mkdir(parents=True, exist_ok=True)
            report_path.write_text("# Deterministic Test Report\n", encoding="utf-8")

        return subprocess.CompletedProcess(argv, 0, stdout="ok\n", stderr="")

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)

    from forge.cli import kill_chain

    kill_chain(
        seed="@rootuser",
        related_seed=[],
        engagement="1001",
        max_iter=2,
        tor=False,
        dry_run=False,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
        parallel_fanout=2,
    )

    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        rows = con.execute(
            """
            SELECT es.seed_value, es.seed_type, es.source, es.depth, sr.loop_name, sr.status, sr.metadata_json
            FROM seed_runs sr
            JOIN engagement_seeds es ON es.id=sr.seed_id
            WHERE sr.engagement_id=1001
              AND sr.loop_name IN (
                'fanout_k_seed_username',
                'fanout_e5_chain',
                'fanout_l_seed_phone',
                'fanout_m_seed_name',
                'fanout_n_seed_company'
              )
            ORDER BY sr.id ASC
            """
        ).fetchall()
        run_map = {(str(row["seed_value"]), str(row["loop_name"])): row for row in rows}

        assert str(run_map[("@rootuser", "fanout_k_seed_username")]["status"]) == "completed"
        assert str(run_map[("ops-root", "fanout_e5_chain")]["status"]) == "completed"
        assert str(run_map[("+15550001111", "fanout_l_seed_phone")]["status"]) == "completed"
        assert str(run_map[("Alice Example", "fanout_m_seed_name")]["status"]) == "completed"
        assert str(run_map[("Acme Corp", "fanout_n_seed_company")]["status"]) == "completed"

        for seed_value in ("ops-root", "+15550001111", "Alice Example", "Acme Corp"):
            row = next(item for item in rows if str(item["seed_value"]) == seed_value)
            assert str(row["source"]) == "cross_reference"
            assert int(row["depth"]) == 2

        e5_metadata = json.loads(
            str(run_map[("ops-root", "fanout_e5_chain")]["metadata_json"] or "{}")
        )
        assert e5_metadata["iteration"] == 2

        relation_rows = con.execute(
            """
            SELECT
                source.seed_value AS source_seed_value,
                target.seed_value AS target_seed_value,
                sr.relation_type AS relation_type
            FROM seed_relations sr
            JOIN engagement_seeds source ON source.id=sr.source_seed_id
            JOIN engagement_seeds target ON target.id=sr.target_seed_id
            WHERE sr.engagement_id=1001
              AND source.seed_type='username'
              AND source.seed_value='@rootuser'
            ORDER BY target.seed_value
            """
        ).fetchall()
        relation_map = {
            (str(row["source_seed_value"]), str(row["target_seed_value"])): str(
                row["relation_type"]
            )
            for row in relation_rows
        }
        assert relation_map[("@rootuser", "+15550001111")] == "same_entity"
        assert relation_map[("@rootuser", "Acme Corp")] == "same_entity"
        assert relation_map[("@rootuser", "Alice Example")] == "same_entity"
        assert relation_map[("@rootuser", "ops-root")] == "same_entity"

        run_row = con.execute(
            """
            SELECT status, current_iteration, max_iterations
            FROM engagement_runs
            WHERE engagement_id=1001
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
        assert run_row is not None
        assert run_row["status"] == "completed"
        assert int(run_row["current_iteration"]) == 2
        assert int(run_row["max_iterations"]) == 2

        domain_seed_runs = con.execute(
            """
            SELECT COUNT(*)
            FROM seed_runs
            WHERE engagement_id=1001
              AND loop_name IN ('fanout_a_subdomains', 'fanout_g_dns', 'fanout_h_rdap', 'fanout_i_wayback')
            """
        ).fetchone()
        assert domain_seed_runs is not None
        assert int(domain_seed_runs[0]) == 0
    finally:
        con.close()

    report_files = sorted((tmp_path / "reports").glob("engagement_1001_kill_chain_*.md"))
    assert report_files


