def test_kill_chain_passes_report_provider_and_loop_overrides_to_final_report_generation(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")
    monkeypatch.setenv("FORGE_KILL_CHAIN_SYNTHESIS_DEPTH", "4")
    monkeypatch.setenv("FORGE_KILL_CHAIN_VALIDATION_BATCH_LIMIT", "7")

    module_invocations: list[list[str]] = []

    def _fake_subprocess_run(cmd, **kwargs):  # noqa: ANN001
        del kwargs
        argv = [str(item) for item in cmd]
        forge_index = argv.index("forge.cli")
        module_argv = [item for item in argv[forge_index + 1 :] if item != "--no-tor"]
        module_invocations.append(module_argv)
        if module_argv[:2] == ["report", "generate"] and "--output" in module_argv:
            report_path = tmp_path / module_argv[module_argv.index("--output") + 1]
            report_path.parent.mkdir(parents=True, exist_ok=True)
            report_path.write_text("# Final report\n", encoding="utf-8")
        return subprocess.CompletedProcess(argv, 0, stdout="ok\n", stderr="")

    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)

    from forge.cli import kill_chain

    kill_chain(
        seed="@rootuser",
        related_seed=[],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=False,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
        report_provider="template",
        report_max_loops=0,
    )

    report_commands = [argv for argv in module_invocations if argv[:2] == ["report", "generate"]]
    assert len(report_commands) == 1
    report_command = report_commands[0]
    assert "--provider" in report_command
    assert report_command[report_command.index("--provider") + 1] == "template"
    assert "--max-loops" in report_command
    assert report_command[report_command.index("--max-loops") + 1] == "0"

    db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
    con = sqlite3.connect(db_path)
    try:
        row = con.execute(
            """
            SELECT metadata_json
            FROM engagement_runs
            WHERE engagement_id=1001
            ORDER BY id DESC
            LIMIT 1
            """
        ).fetchone()
        assert row is not None
        metadata = json.loads(str(row[0] or "{}"))
        assert metadata["report_provider"] == "template"
        assert metadata["report_max_loops"] == 0
        assert metadata["synthesis_depth_limit"] == 4
        assert metadata["pending_validation_batch_limit"] == 7
    finally:
        con.close()


