    monkeypatch.setattr(subprocess, "run", _fake_subprocess_run)

    from forge.cli import kill_chain

    kill_chain(
        seed="@rootuser",
        related_seed=[],
        engagement="1001",
        max_iter=1,
        tor=False,
        dry_run=False,
        attack_mode=False,
        skip_cloud=True,
        skip_keyscan=True,
    )

    graph_commands = [argv for argv in module_invocations if argv[:2] == ["graph", "build"]]
    assert len(graph_commands) == 1
    graph_command = graph_commands[0]
    assert "--format" in graph_command
    assert graph_command[graph_command.index("--format") + 1] == "all"
    assert "--output-dir" in graph_command
    assert graph_command[graph_command.index("--output-dir") + 1] == "reports"
    assert "--snapshot" in graph_command


