def test_kill_chain_dry_run_queues_seed_artifact_urls_and_processes_remote_apk(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")
    monkeypatch.setenv("FORGE_ARTIFACT_PROCESSOR_MAX_WORKERS", "1")

    served_root = tmp_path / "served"
    served_root.mkdir()
    remote_apk = served_root / "remote-client.apk"
    with zipfile.ZipFile(remote_apk, "w") as zf:
        zf.writestr(
            "google-services.json",
            """
            {
              "project_info": {
                "project_id": "acme-remote-firebase",
                "firebase_url": "https://acme-remote-firebase.firebaseio.com"
              }
            }
            """.strip(),
        )
        zf.writestr(
            "assets/supabase.js",
            """
            export const url = "https://remoteacme.supabase.co";
            export const anon = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJlbW90ZWFjbWUiLCJyb2xlIjoiYW5vbiJ9.signature123";
            """.strip(),
        )

    class _QuietHandler(SimpleHTTPRequestHandler):
        def log_message(self, format: str, *args) -> None:  # noqa: A003
            return None

    server = ThreadingHTTPServer(
        ("127.0.0.1", 0),
        partial(_QuietHandler, directory=str(served_root)),
    )
    thread = Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
        db_path.parent.mkdir(parents=True, exist_ok=True)
        _bootstrap_engagement(db_path)
        source_url = f"http://127.0.0.1:{server.server_address[1]}/{remote_apk.name}?download=1"

        con = sqlite3.connect(db_path)
        try:
            con.execute(
                """
                INSERT INTO engagement_seeds
                    (engagement_id, seed_value, seed_type, source, status, depth, confidence, metadata_json)
                VALUES
                    (1001, ?, 'apk_url', 'cross_reference', 'pending', 1, 0.82, '{}')
                """,
                (source_url,),
            )
            con.commit()
        finally:
            con.close()

        from forge.cli import kill_chain

        kill_chain(
            seed="acme.example",
            related_seed=["security@acme.example"],
            engagement="1001",
            max_iter=1,
            tor=False,
            dry_run=True,
            attack_mode=False,
            skip_cloud=True,
            skip_keyscan=True,
            parallel_fanout=4,
        )

        con = sqlite3.connect(db_path)
        try:
            artifact_row = con.execute(
                """
                SELECT status, local_path, discovered_from
                FROM artifact_queue
                WHERE engagement_id=1001 AND source_url=?
                """,
                (source_url,),
            ).fetchone()
            assert artifact_row is not None
            assert artifact_row[0] == "parsed"
            assert artifact_row[2] == "engagement_seed"
            assert artifact_row[1]
            assert Path(str(artifact_row[1])).exists()

            cloud_assets = {
                (row[0], row[1])
                for row in con.execute(
                    """
                    SELECT asset_type, identifier
                    FROM cloud_assets
                    WHERE engagement_id=1001
                    """
                ).fetchall()
            }
            assert ("firebase", "acme-remote-firebase") in cloud_assets
            assert ("supabase", "remoteacme") in cloud_assets

            relations = {
                (str(row[0]), str(row[1]), str(row[2]))
                for row in con.execute(
                    """
                    SELECT src.seed_value, dst.seed_value, sr.relation_type
                    FROM seed_relations sr
                    JOIN engagement_seeds src ON src.id=sr.source_seed_id
                    JOIN engagement_seeds dst ON dst.id=sr.target_seed_id
                    WHERE sr.engagement_id=1001
                    """
                ).fetchall()
            }
            assert (source_url, "acme-remote-firebase", "derived_from") in relations
            assert (source_url, "remoteacme", "derived_from") in relations

            run_row = con.execute(
                """
                SELECT metadata_json
                FROM engagement_runs
                WHERE engagement_id=1001
                ORDER BY id DESC
                LIMIT 1
                """
            ).fetchone()
            assert run_row is not None
            run_metadata = json.loads(str(run_row[0] or "{}"))
            assert run_metadata.get("parallel_fanout") == 4
            assert run_metadata.get("artifact_processor_worker_cap") == 1
            assert run_metadata.get("artifact_processor_max_workers") == 1
            artifact_queue_metrics = run_metadata.get("queue_metrics", {}).get("artifact_queue", {})
            artifact_stage_metrics = run_metadata.get("queue_metrics", {}).get(
                "artifact_processor", {}
            )
            assert int(artifact_queue_metrics.get("parsed", 0)) >= 1
            assert int(artifact_stage_metrics.get("completed", 0)) >= 1
            assert int(artifact_stage_metrics.get("workers", 0)) == 1
            assert run_metadata.get("active_artifact_stage_label")
            assert float(run_metadata.get("active_artifact_eta_seconds") or 0.0) >= 0.0
        finally:
            con.close()
    finally:
        server.shutdown()
        thread.join(timeout=5)
        server.server_close()


