def test_kill_chain_dry_run_queues_seed_debian_package_url_and_processes_remote_artifact(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")

    served_root = tmp_path / "served-debian-packages"
    served_root.mkdir()
    remote_deb = served_root / "acme-agent_1.0.0_all.deb"
    config_payload = (
        dedent(
            """
        OWNER=remote-deb-owner@acme.example
        API_BASE=https://remote-deb.acme.example/api
        FIREBASE_URL=https://remote-deb-firebase.firebaseio.com
        SUPABASE_URL=https://remotedeb.supabase.co
        RELEASE_BUCKET=s3://remote-deb-bucket/releases/acme-agent.deb
        """
        )
        .strip()
        .encode("utf-8")
    )
    _write_ar_archive(
        remote_deb,
        [
            ("debian-binary", b"2.0\n"),
            (
                "control.tar.gz",
                _tar_bytes(
                    "control",
                    b"Package: acme-agent\nMaintainer: remote-deb-maintainer@acme.example\n",
                ),
            ),
            ("data.tar.gz", _tar_bytes("etc/acme/agent.env", config_payload)),
        ],
    )

    class _QuietHandler(SimpleHTTPRequestHandler):
        def log_message(self, format: str, *args) -> None:  # noqa: A003
            return None

    server = ThreadingHTTPServer(
        ("127.0.0.1", 0),
        partial(_QuietHandler, directory=str(served_root)),
    )
    thread = Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
        db_path.parent.mkdir(parents=True, exist_ok=True)
        _bootstrap_engagement(db_path)
        source_url = f"http://127.0.0.1:{server.server_address[1]}/{remote_deb.name}?download=1"

        con = sqlite3.connect(db_path)
        try:
            con.execute(
                """
                INSERT INTO engagement_seeds
                    (engagement_id, seed_value, seed_type, source, status, depth, confidence, metadata_json)
                VALUES
                    (1001, ?, 'url', 'cross_reference', 'pending', 1, 0.82, '{}')
                """,
                (source_url,),
            )
            con.commit()
        finally:
            con.close()

        from forge.cli import kill_chain

        kill_chain(
            seed="acme.example",
            related_seed=["security@acme.example"],
            engagement="1001",
            max_iter=1,
            tor=False,
            dry_run=True,
            attack_mode=False,
            skip_cloud=True,
            skip_keyscan=True,
        )

        con = sqlite3.connect(db_path)
        try:
            artifact_row = con.execute(
                """
                SELECT status, local_path, discovered_from, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001 AND source_url=?
                """,
                (source_url,),
            ).fetchone()
            assert artifact_row is not None
            assert artifact_row[0] == "parsed"
            assert artifact_row[2] == "engagement_seed"
            assert artifact_row[1]
            assert Path(str(artifact_row[1])).exists()
            metadata = json.loads(str(artifact_row[3] or "{}"))
            assert metadata["format"] == "deb"
            assert metadata["payload_count"] >= 2

            emails = {
                str(row[0])
                for row in con.execute(
                    "SELECT email FROM emails WHERE engagement_id=1001"
                ).fetchall()
            }
            assert "remote-deb-owner@acme.example" in emails
            assert "remote-deb-maintainer@acme.example" in emails

            seeds = {
                (str(row[0]), str(row[1]))
                for row in con.execute(
                    """
                    SELECT seed_value, seed_type
                    FROM engagement_seeds
                    WHERE engagement_id=1001
                    """
                ).fetchall()
            }
            assert ("remote-deb-owner@acme.example", "email") in seeds
            assert ("https://remote-deb.acme.example/api", "url") in seeds
            assert ("https://remotedeb.supabase.co", "url") in seeds

            cloud_assets = {
                (row[0], row[1])
                for row in con.execute(
                    """
                    SELECT asset_type, identifier
                    FROM cloud_assets
                    WHERE engagement_id=1001
                    """
                ).fetchall()
            }
            assert ("aws_s3", "remote-deb-bucket") in cloud_assets
            assert ("firebase", "remote-deb-firebase") in cloud_assets
            assert ("supabase", "remotedeb") in cloud_assets
        finally:
            con.close()
    finally:
        server.shutdown()
        thread.join(timeout=5)
        server.server_close()


