def test_kill_chain_dry_run_queues_extensionless_rpm_seed_from_content_type_metadata(
    tmp_path: Path,
    monkeypatch,
) -> None:
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("FORGE_DATA_DIR", str(tmp_path / ".forge_data"))
    monkeypatch.setenv("FORGE_ENV", "test")

    served_root = tmp_path / "served-extensionless-rpm"
    served_root.mkdir()
    remote_rpm = served_root / "download"
    compressed_payload = gzip.compress(
        _cpio_newc_bytes(
            [
                (
                    "etc/acme/extensionless-rpm.env",
                    dedent(
                        """
                        OWNER=extensionless-rpm-owner@acme.example
                        API_BASE=https://extensionless-rpm.acme.example/api
                        FIREBASE_URL=https://extensionless-rpm-firebase.firebaseio.com
                        SUPABASE_URL=https://extensionlessrpm.supabase.co
                        RELEASE_BUCKET=s3://extensionless-rpm-bucket/releases/acme-agent.rpm
                        """
                    )
                    .strip()
                    .encode("utf-8"),
                )
            ]
        )
    )
    remote_rpm.write_bytes(
        b"\xed\xab\xee\xdb"
        b"extensionless-rpm-header-owner@acme.example\x00"
        b"payload follows\x00" + compressed_payload
    )

    class _RpmHandler(SimpleHTTPRequestHandler):
        def guess_type(self, path: str) -> str:
            if Path(path).name == "download":
                return "application/x-rpm"
            return super().guess_type(path)

        def log_message(self, format: str, *args) -> None:  # noqa: A003
            return None

    server = ThreadingHTTPServer(
        ("127.0.0.1", 0),
        partial(_RpmHandler, directory=str(served_root)),
    )
    thread = Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
        db_path.parent.mkdir(parents=True, exist_ok=True)
        _bootstrap_engagement(db_path)
        source_url = f"http://127.0.0.1:{server.server_address[1]}/download?artifact=agent"

        con = sqlite3.connect(db_path)
        try:
            con.execute(
                """
                INSERT INTO engagement_seeds
                    (engagement_id, seed_value, seed_type, source, status, depth, confidence, metadata_json)
                VALUES
                    (1001, ?, 'url', 'cross_reference', 'pending', 1, 0.82, ?)
                """,
                (
                    source_url,
                    json.dumps(
                        {
                            "Content-Type": "application/x-rpm",
                            "source": "operator_seed_metadata",
                        },
                        sort_keys=True,
                    ),
                ),
            )
            con.commit()
        finally:
            con.close()

        from forge.cli import kill_chain

        kill_chain(
            seed="acme.example",
            related_seed=["security@acme.example"],
            engagement="1001",
            max_iter=1,
            tor=False,
            dry_run=True,
            attack_mode=False,
            skip_cloud=True,
            skip_keyscan=True,
        )

        con = sqlite3.connect(db_path)
        try:
            artifact_row = con.execute(
                """
                SELECT status, local_path, discovered_from, artifact_type, metadata_json
                FROM artifact_queue
                WHERE engagement_id=1001 AND source_url=?
                """,
                (source_url,),
            ).fetchone()
            assert artifact_row is not None
            assert artifact_row[0] == "parsed"
            assert artifact_row[2] == "engagement_seed"
            assert artifact_row[3] == "document"
            assert artifact_row[1]
            assert Path(str(artifact_row[1])).exists()
            assert str(artifact_row[1]).endswith(".rpm")
            metadata = json.loads(str(artifact_row[4] or "{}"))
            assert metadata["content_type"] == "application/x-rpm"
            assert metadata["format"] == "rpm"
            assert metadata["payload_count"] >= 2
            assert metadata["metadata_payload_count"] >= 1

            emails = {
                str(row[0])
                for row in con.execute(
                    "SELECT email FROM emails WHERE engagement_id=1001"
                ).fetchall()
            }
            assert "extensionless-rpm-header-owner@acme.example" in emails
            assert "extensionless-rpm-owner@acme.example" in emails

            seeds = {
                (str(row[0]), str(row[1]))
                for row in con.execute(
                    """
                    SELECT seed_value, seed_type
                    FROM engagement_seeds
                    WHERE engagement_id=1001
                    """
                ).fetchall()
            }
            assert ("extensionless-rpm-header-owner@acme.example", "email") in seeds
            assert ("extensionless-rpm-owner@acme.example", "email") in seeds
            assert ("https://extensionless-rpm.acme.example/api", "url") in seeds
            assert ("https://extensionlessrpm.supabase.co", "url") in seeds

            cloud_assets = {
                (row[0], row[1])
                for row in con.execute(
                    """
                    SELECT asset_type, identifier
                    FROM cloud_assets
                    WHERE engagement_id=1001
                    """
                ).fetchall()
            }
            assert ("aws_s3", "extensionless-rpm-bucket") in cloud_assets
            assert ("firebase", "extensionless-rpm-firebase") in cloud_assets
            assert ("supabase", "extensionlessrpm") in cloud_assets
        finally:
            con.close()
    finally:
        server.shutdown()
        thread.join(timeout=5)
        server.server_close()


