    class _DownloadHandler(SimpleHTTPRequestHandler):
        def log_message(self, format: str, *args) -> None:  # noqa: A003
            return None

        def do_GET(self) -> None:  # noqa: N802
            body = bodies.get(self.path)
            if body is None:
                self.send_error(404)
                return
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

    server = ThreadingHTTPServer(("127.0.0.1", 0), _DownloadHandler)
    thread = Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        base_url = f"http://127.0.0.1:{server.server_address[1]}"
        resource_url = f"{base_url}/.well-known/oauth-protected-resource"
        federation_url = f"{base_url}/.well-known/openid-federation"
        uma_url = f"{base_url}/.well-known/uma2-configuration"

        from forge.cli import kill_chain

        kill_chain(
            seed="acme.example",
            related_seed=[resource_url, federation_url, uma_url],
            engagement="1001",
            max_iter=1,
            tor=False,
            dry_run=True,
            attack_mode=False,
            skip_cloud=True,
            skip_keyscan=True,
        )

        db_path = tmp_path / ".forge_data" / "engagements" / "1001.db"
        con = sqlite3.connect(db_path)
        try:
            artifact_rows = {
                row[0]: row
                for row in con.execute(
                    """
                    SELECT source_url, status, local_path, artifact_type, discovered_from, metadata_json
                    FROM artifact_queue
                    WHERE engagement_id=1001
                    """
                ).fetchall()
            }
            for source_url, expected_format in {
                resource_url: "oauth-protected-resource",
                federation_url: "openid-federation",
                uma_url: "uma2-configuration",
            }.items():
                artifact_row = artifact_rows.get(source_url)
                assert artifact_row is not None
                assert artifact_row[1] == "parsed"
                assert artifact_row[3] == "config"
                assert artifact_row[4] == "engagement_seed"
                local_path = Path(str(artifact_row[2]))
                assert local_path.exists()
                assert local_path.suffix == ""
                metadata = json.loads(str(artifact_row[5] or "{}"))
                assert metadata["format"] == expected_format
                assert metadata["download_filename"].endswith(expected_format)
                assert metadata["payload_count"] >= 1

            emails = {
                row[0]
                for row in con.execute(
                    "SELECT email FROM emails WHERE engagement_id=1001"
                ).fetchall()
            }
            assert "resource-owner@acme.example" in emails
            assert "federation-owner@acme.example" in emails
            assert "uma-owner@acme.example" in emails

            seeds = {
                (row[0], row[1])
                for row in con.execute(
                    """
                    SELECT seed_value, seed_type
                    FROM engagement_seeds
                    WHERE engagement_id=1001
                    """
                ).fetchall()
            }
            assert ("https://api.acme.example/", "url") in seeds
            assert (
                "https://auth.acme.example/.well-known/oauth-authorization-server",
                "url",
            ) in seeds
            assert ("https://api.acme.example/.well-known/jwks.json", "url") in seeds
            assert ("https://docs.acme.example/oauth-resource", "url") in seeds
            assert ("resource-owner@acme.example", "email") in seeds
            assert ("https://federation.acme.example/.well-known/jwks.json", "url") in seeds
            assert ("https://login.acme.example/oauth/authorize", "url") in seeds
            assert ("https://trust.acme.example/marks/security", "url") in seeds
            assert ("federation-owner@acme.example", "email") in seeds
            assert ("https://uma.acme.example/uma/authorize", "url") in seeds
            assert ("https://uma-api.acme.example/uma/token", "url") in seeds
            assert ("https://uma-api.acme.example/uma/resource_set", "url") in seeds
            assert ("https://uma.acme.example/.well-known/jwks.json", "url") in seeds
            assert ("uma-owner@acme.example", "email") in seeds

            cloud_assets = {
                (row[0], row[1])
                for row in con.execute(
                    """
                    SELECT asset_type, identifier
                    FROM cloud_assets
                    WHERE engagement_id=1001
                    """
                ).fetchall()
            }
            assert ("supabase", "resourcevault") in cloud_assets
            assert ("firebase", "federationvault") in cloud_assets
            assert ("supabase", "umavault") in cloud_assets

            relations = {
                (str(row[0]), str(row[1]), str(row[2]))
                for row in con.execute(
                    """
                    SELECT src.seed_value, dst.seed_value, sr.relation_type
                    FROM seed_relations sr
                    JOIN engagement_seeds src ON src.id=sr.source_seed_id
                    JOIN engagement_seeds dst ON dst.id=sr.target_seed_id
                    WHERE sr.engagement_id=1001
                    """
                ).fetchall()
            }
            assert (resource_url, "resource-owner@acme.example", "derived_from") in relations
            assert (
                resource_url,
                "https://auth.acme.example/.well-known/oauth-authorization-server",
                "derived_from",
            ) in relations
            assert (federation_url, "federation-owner@acme.example", "derived_from") in relations
            assert (
                federation_url,
                "https://trust.acme.example/marks/security",
                "derived_from",
            ) in relations
            assert (uma_url, "uma-owner@acme.example", "derived_from") in relations
            assert (
                uma_url,
                "https://uma-api.acme.example/uma/resource_set",
                "derived_from",
            ) in relations
        finally:
            con.close()
    finally:
        server.shutdown()
        thread.join(timeout=5)
        server.server_close()


